"""
CodeFlow Studio — Optional Local Python Execution Server (Zero External Dependencies)
Uses Python's built-in `sys.settrace`, `ast`, and `http.server` to serve the web app
and provide a native `/api/trace` endpoint for real CPython step-by-step tracing.
"""

import ast
import io
import json
import os
import sys
from http.server import SimpleHTTPRequestHandler, HTTPServer

PORT = 8080
BASE_DIR = os.path.dirname(os.path.abspath(__file__))


def safe_repr(val):
    if isinstance(val, (int, float, bool, str, list, dict, tuple, set)) or val is None:
        return repr(val)
    return f"<{type(val).__name__}>"


def trace_python_code(source_code: str, max_steps: int = 250):
    raw_lines = source_code.replace("\r\n", "\n").split("\n")
    steps = []
    stdout_buffer = io.StringIO()
    prev_globals_snapshot = {}

    def tracer(frame, event, arg):
        if frame.f_code.co_filename != "<user_code>":
            return tracer
        if len(steps) >= max_steps:
            raise RuntimeError("Maximum step limit reached (250 steps).")

        if event in ("line", "call", "return"):
            lineno = frame.f_lineno
            code_line = raw_lines[lineno - 1].strip() if 1 <= lineno <= len(raw_lines) else ""
            user_vars = {
                k: v
                for k, v in frame.f_locals.items()
                if not k.startswith("__") and not callable(v)
            }

            variables_list = []
            for k, v in user_vars.items():
                formatted = safe_repr(v)
                if k not in prev_globals_snapshot:
                    status = "new"
                    prev_val = None
                elif prev_globals_snapshot[k] != formatted:
                    status = "updated"
                    prev_val = prev_globals_snapshot[k]
                else:
                    status = "unchanged"
                    prev_val = formatted
                prev_globals_snapshot[k] = formatted
                variables_list.append({
                    "name": k,
                    "type": type(v).__name__,
                    "formattedValue": formatted,
                    "prevFormattedValue": prev_val,
                    "status": status,
                })

            steps.append({
                "stepIndex": len(steps) + 1,
                "line": lineno,
                "codeText": code_line,
                "eventType": event.upper(),
                "variables": variables_list,
                "stdout": stdout_buffer.getvalue().splitlines(),
            })
        return tracer

    compiled = compile(source_code, "<user_code>", "exec")
    env = {"__builtins__": __builtins__}
    old_stdout = sys.stdout
    try:
        sys.stdout = stdout_buffer
        sys.settrace(tracer)
        exec(compiled, env)
    except Exception as exc:
        steps.append({
            "stepIndex": len(steps) + 1,
            "line": getattr(exc, "lineno", 1) or 1,
            "codeText": "",
            "eventType": "ERROR",
            "error": str(exc),
            "variables": [],
            "stdout": stdout_buffer.getvalue().splitlines(),
        })
    finally:
        sys.settrace(None)
        sys.stdout = old_stdout

    return {"rawLines": raw_lines, "steps": steps}


class CodeFlowRequestHandler(SimpleHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=BASE_DIR, **kwargs)

    def do_POST(self):
        if self.path == "/api/trace":
            length = int(self.headers.get("Content-Length", 0))
            body = json.loads(self.rfile.read(length).decode("utf-8"))
            code = body.get("code", "")
            result = trace_python_code(code)
            payload = json.dumps(result).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            self.wfile.write(payload)
        else:
            self.send_error(404, "Endpoint not found")


if __name__ == "__main__":
    print(f"CodeFlow Studio running at http://localhost:{PORT}")
    HTTPServer(("127.0.0.1", PORT), CodeFlowRequestHandler).serve_forever()

