}

// AI-Powered Code Flow Visualizer - Interactive Application Controller (Step 2 Upgraded)

class CodeFlowVisualizerApp {
  constructor() {
    this.tracer = new window.PythonFlowTracer();
    this.currentPresetKey = "for_loop_sum";
    this.sourceCode = window.PRESET_EXAMPLES[this.currentPresetKey].code;
    this.bigPicture = window.PRESET_EXAMPLES[this.currentPresetKey].bigPicture;

    this.traceResult = null;
    this.currentStepIdx = 0; // 0-indexed into traceResult.steps
    this.isPlaying = false;
    this.playInterval = null;
    this.playSpeedMs = 1100;
    this.explanationDepth = "beginner"; // 'eli5' | 'beginner' | 'deep'
    this.quizModeEnabled = false;
    this.isEditingCode = false;
    this.activeMemoryTab = "live"; // 'live' | 'history'

    this.initDOM();
    this.bindEvents();
    this.loadPreset(this.currentPresetKey);
  }

  initDOM() {
    this.presetSelect = document.getElementById("presetSelect");
    this.btnEditToggle = document.getElementById("btnEditToggle");
    this.btnRunTrace = document.getElementById("btnRunTrace");
    this.btnQuizMode = document.getElementById("btnQuizMode");

    // Transport controls
    this.btnFirst = document.getElementById("btnFirst");
    this.btnPrev = document.getElementById("btnPrev");
    this.btnPlay = document.getElementById("btnPlay");
    this.btnNext = document.getElementById("btnNext");
    this.btnLast = document.getElementById("btnLast");
    this.timelineSlider = document.getElementById("timelineSlider");
    this.stepCounter = document.getElementById("stepCounter");
    this.speedPills = document.querySelectorAll(".speed-pill");

    // Left Panel: Code & Console
    this.codeTraceView = document.getElementById("codeTraceView");
    this.codeEditorTextarea = document.getElementById("codeEditorTextarea");
    this.consoleBody = document.getElementById("consoleBody");

    // Center Panel: CFG Flowchart, Live Memory & Final Answer History
    this.flowSvgContainer = document.getElementById("flowSvgContainer");
    this.memoryScroll = document.getElementById("memoryScroll");
    this.historyScroll = document.getElementById("historyScroll");
    this.tabLiveMemory = document.getElementById("tabLiveMemory");
    this.tabVarHistory = document.getElementById("tabVarHistory");
    this.frameCountBadge = document.getElementById("frameCountBadge");

    // Right Panel: Senior Developer Mentor
    this.depthBtns = document.querySelectorAll(".depth-btn");
    this.bigPictureBanner = document.getElementById("bigPictureBanner");
    this.eventBadge = document.getElementById("eventBadge");
    this.stepLineBadge = document.getElementById("stepLineBadge");
    this.stepCodePreview = document.getElementById("stepCodePreview");
    this.evalBreakdownBox = document.getElementById("evalBreakdownBox");
    this.mechanicsContainer = document.getElementById("mechanicsContainer");
    this.whatHappenedText = document.getElementById("whatHappenedText");
    this.howNextDecidedText = document.getElementById("howNextDecidedText");
    this.whyHappenedText = document.getElementById("whyHappenedText");
    this.whatNextText = document.getElementById("whatNextText");

    // Quiz & AI Q&A
    this.quizCard = document.getElementById("quizCard");
    this.quizQuestion = document.getElementById("quizQuestion");
    this.quizOptions = document.getElementById("quizOptions");
    this.chatInput = document.getElementById("chatInput");
    this.btnAskAi = document.getElementById("btnAskAi");
    this.aiAnswerBubble = document.getElementById("aiAnswerBubble");
    this.quickChips = document.querySelectorAll(".chip-btn");

    // Populate Preset Selector
    Object.entries(window.PRESET_EXAMPLES).forEach(([key, item]) => {
      const opt = document.createElement("option");
      opt.value = key;
      opt.textContent = item.title;
      this.presetSelect.appendChild(opt);
    });
  }

  bindEvents() {
    this.presetSelect.addEventListener("change", (e) => {
      this.loadPreset(e.target.value);
    });

    this.btnEditToggle.addEventListener("click", () => {
      this.toggleEditMode(!this.isEditingCode);
    });

    this.btnRunTrace.addEventListener("click", () => {
      if (this.isEditingCode) {
        this.sourceCode = this.codeEditorTextarea.value;
        this.bigPicture = "Custom Python program: step through each line to watch how variables, conditions, loops, and functions execute internally.";
        this.toggleEditMode(false);
      }
      this.runVisualization();
    });

    this.btnQuizMode.addEventListener("click", () => {
      this.quizModeEnabled = !this.quizModeEnabled;
      this.btnQuizMode.classList.toggle("active", this.quizModeEnabled);
      this.btnQuizMode.textContent = this.quizModeEnabled
        ? "Quiz Mode: ON"
        : "Predict Next Step";
      this.renderStep();
    });

    // Memory / History Tabs
    this.tabLiveMemory.addEventListener("click", () => {
      this.activeMemoryTab = "live";
      this.tabLiveMemory.classList.add("active");
      this.tabVarHistory.classList.remove("active");
      this.memoryScroll.classList.remove("hidden");
      this.historyScroll.classList.add("hidden");
    });

    this.tabVarHistory.addEventListener("click", () => {
      this.activeMemoryTab = "history";
      this.tabVarHistory.classList.add("active");
      this.tabLiveMemory.classList.remove("active");
      this.historyScroll.classList.remove("hidden");
      this.memoryScroll.classList.add("hidden");
      this.renderVariableTimeline();
    });

    // Transport buttons
    this.btnFirst.addEventListener("click", () => {
      this.pause();
      this.goToStep(0);
    });

    this.btnPrev.addEventListener("click", () => {
      this.pause();
      this.goToStep(this.currentStepIdx - 1);
    });

    this.btnPlay.addEventListener("click", () => {
      if (this.isPlaying) this.pause();
      else this.play();
    });

    this.btnNext.addEventListener("click", () => {
      this.pause();
      this.goToStep(this.currentStepIdx + 1);
    });

    this.btnLast.addEventListener("click", () => {
      this.pause();
      if (this.traceResult && this.traceResult.steps.length > 0) {
        this.goToStep(this.traceResult.steps.length - 1);
      }
    });

    this.timelineSlider.addEventListener("input", (e) => {
      this.pause();
      this.goToStep(Number(e.target.value));
    });

    // Keyboard shortcuts (Left/Right arrows, Space to play/pause)
    window.addEventListener("keydown", (e) => {
      if (
        document.activeElement === this.codeEditorTextarea ||
        document.activeElement === this.chatInput
      ) {
        return;
      }
      if (e.key === "ArrowRight") {
        e.preventDefault();
        this.pause();
        this.goToStep(this.currentStepIdx + 1);
      } else if (e.key === "ArrowLeft") {
        e.preventDefault();
        this.pause();
        this.goToStep(this.currentStepIdx - 1);
      } else if (e.key === " ") {
        e.preventDefault();
        if (this.isPlaying) this.pause();
        else this.play();
      }
    });

    // Speed pills
    this.speedPills.forEach((pill) => {
      pill.addEventListener("click", () => {
        this.speedPills.forEach((p) => p.classList.remove("active"));
        pill.classList.add("active");
        this.playSpeedMs = Number(pill.dataset.speed);
        if (this.isPlaying) {
          this.pause();
          this.play();
        }
      });
    });

    // Explanation depth buttons
    this.depthBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        this.depthBtns.forEach((b) => b.classList.remove("active"));
        btn.classList.add("active");
        this.explanationDepth = btn.dataset.depth;
        this.renderStep();
      });
    });

    // AI Tutor Q&A
    this.btnAskAi.addEventListener("click", () => this.handleAskAI());
    this.chatInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter") this.handleAskAI();
    });

    this.quickChips.forEach((chip) => {
      chip.addEventListener("click", () => {
        this.chatInput.value = chip.dataset.question;
        this.handleAskAI();
      });
    });
  }

  loadPreset(key) {
    this.pause();
    this.currentPresetKey = key;
    const preset = window.PRESET_EXAMPLES[key];
    this.sourceCode = preset.code;
    this.bigPicture = preset.bigPicture;
    this.codeEditorTextarea.value = this.sourceCode;
    this.toggleEditMode(false);
    this.runVisualization();
  }

  toggleEditMode(editing) {
    this.isEditingCode = editing;
    if (editing) {
      this.pause();
      this.codeEditorTextarea.value = this.sourceCode;
      this.codeEditorTextarea.classList.remove("hidden");
      this.codeTraceView.classList.add("hidden");
      this.btnEditToggle.textContent = "Cancel Edit";
    } else {
      this.codeEditorTextarea.classList.add("hidden");
      this.codeTraceView.classList.remove("hidden");
      this.btnEditToggle.textContent = "Edit Code";
    }
  }

  runVisualization() {
    this.pause();
    this.traceResult = this.tracer.trace(this.sourceCode, this.bigPicture);
    const total = this.traceResult.steps.length;
    this.timelineSlider.max = Math.max(0, total - 1);
    this.currentStepIdx = 0;
    this.aiAnswerBubble.classList.add("hidden");
    this.bigPictureBanner.innerHTML = `<strong>👨‍💻 Senior Dev Big Picture:</strong> ${this.formatMarkdownCode(this.bigPicture)}`;
    this.renderStep();
  }

  goToStep(idx) {
    if (!this.traceResult || this.traceResult.steps.length === 0) return;
    const clamped = Math.max(0, Math.min(idx, this.traceResult.steps.length - 1));
    this.currentStepIdx = clamped;
    this.renderStep();
  }

  play() {
    if (!this.traceResult || this.traceResult.steps.length === 0) return;
    if (this.currentStepIdx >= this.traceResult.steps.length - 1) {
      this.currentStepIdx = 0;
    }
    this.isPlaying = true;
    this.btnPlay.classList.add("playing");
    this.btnPlay.textContent = "Pause";

    this.playInterval = setInterval(() => {
      if (this.currentStepIdx < this.traceResult.steps.length - 1) {
        this.currentStepIdx++;
        this.renderStep();
      } else {
        this.pause();
      }
    }, this.playSpeedMs);
  }

  pause() {
    this.isPlaying = false;
    if (this.playInterval) {
      clearInterval(this.playInterval);
      this.playInterval = null;
    }
    this.btnPlay.classList.remove("playing");
    this.btnPlay.textContent = "Play";
  }

  renderStep() {
    if (!this.traceResult || this.traceResult.steps.length === 0) return;
    const steps = this.traceResult.steps;
    const step = steps[this.currentStepIdx];
    const total = steps.length;

    // Update scrubber and transport controls
    this.timelineSlider.value = this.currentStepIdx;
    this.stepCounter.textContent = `Step ${this.currentStepIdx + 1} / ${total}`;
    this.btnFirst.disabled = this.currentStepIdx === 0;
    this.btnPrev.disabled = this.currentStepIdx === 0;
    this.btnNext.disabled = this.currentStepIdx >= total - 1;
    this.btnLast.disabled = this.currentStepIdx >= total - 1;

    this.renderCodeLines(step);
    this.renderConsoleOutput(step);
    this.renderFlowchartSVG(step);
    this.renderMemoryScopes(step);
    this.renderVariableTimeline();
    this.renderAITutorPanel(step);
  }

  renderCodeLines(step) {
    // Track which step numbers executed each line up to currentStepIdx
    const lineStepOrders = {};
    for (let i = 0; i <= this.currentStepIdx; i++) {
      const s = this.traceResult.steps[i];
      if (s.eventType === "PROGRAM_START") continue;
      if (!lineStepOrders[s.line]) lineStepOrders[s.line] = [];
      lineStepOrders[s.line].push(s.stepIndex);
    }

    const activeScope = step.scopes[step.scopes.length - 1];
    const changedVar = activeScope
      ? activeScope.variables.find((v) => v.status !== "unchanged")
      : null;

    this.codeTraceView.innerHTML = "";
    this.traceResult.rawLines.forEach((rawLine, idx) => {
      const lineNum = idx + 1;
      const isCurrent = step.line === lineNum;
      const isNext = step.nextLine === lineNum && !isCurrent;
      const orders = lineStepOrders[lineNum] || [];
      const isVisited = orders.length > 0;

      const row = document.createElement("div");
      row.className = "code-line";
      if (isCurrent) row.classList.add("is-current");
      if (isNext) row.classList.add("is-next");
      if (isVisited) row.classList.add("is-visited");

      const arrowSymbol = isCurrent ? "▶" : isNext ? "↳" : "";
      const arrowColor = isCurrent ? "#818cf8" : "#f59e0b";

      // Execution order trail pills (shows 1st, 2nd, 3rd step execution history)
      let inlineBadgeHTML = "";
      if (orders.length > 0) {
        const recentOrders = orders.slice(-3);
        const prefix = orders.length > 3 ? `..` : "";
        const orderLabel = prefix + recentOrders.map((n) => `#${n}`).join(",");
        inlineBadgeHTML += `<span class="exec-order-pill ${isCurrent ? "latest-step" : ""}" title="Executed on step(s): ${orders.join(", ")}">${orderLabel}</span>`;
      }

      if (isCurrent) {
        if (changedVar) {
          inlineBadgeHTML += `<span class="inline-pill">${changedVar.name} = ${changedVar.formattedValue}</span>`;
        } else if (step.branchResult !== null) {
          const cls = step.branchResult ? "branch-true" : "branch-false";
          inlineBadgeHTML += `<span class="inline-pill ${cls}">${step.branchResult ? "✓ True" : "✗ False"}</span>`;
        }
      }

      row.innerHTML = `
        <div class="line-gutter">
          <span class="line-arrow" style="color:${arrowColor}">${arrowSymbol}</span>
          <span class="line-num">${lineNum}</span>
        </div>
        <div class="line-code">${this.escapeHTML(rawLine)}</div>
        <div class="line-inline-values">${inlineBadgeHTML}</div>
      `;

      row.addEventListener("click", () => {
        const targetIdx = this.traceResult.steps.findIndex(
          (s, sIdx) => s.line === lineNum && sIdx > 0
        );
        if (targetIdx !== -1) {
          this.pause();
          this.goToStep(targetIdx);
        }
      });

      this.codeTraceView.appendChild(row);
    });
  }

  renderConsoleOutput(step) {
    this.consoleBody.innerHTML = "";
    if (!step.stdout || step.stdout.length === 0) {
      this.consoleBody.innerHTML = `<div class="empty-state">No console output printed yet at Step ${step.stepIndex}.</div>`;
      return;
    }

    step.stdout.forEach((item) => {
      const lineDiv = document.createElement("div");
      lineDiv.className = "console-line";
      if (item.stepIndex === step.stepIndex) {
        lineDiv.classList.add("new-output");
      }
      lineDiv.innerHTML = `
        <span class="console-step-tag">[Step ${item.stepIndex} | L${item.line}]</span>
        <span>${this.escapeHTML(item.text)}</span>
      `;
      this.consoleBody.appendChild(lineDiv);
    });
    this.consoleBody.scrollTop = this.consoleBody.scrollHeight;
  }

  renderFlowchartSVG(step) {
    const cfg = this.traceResult.cfg;
    if (!cfg || !cfg.nodes.length) return;

    const nodeW = 195;
    const nodeH = 36;
    const vGap = 54;
    const svgW = 360;
    const svgH = Math.max(250, cfg.nodes.length * vGap + 40);

    const positions = {};
    cfg.nodes.forEach((n, idx) => {
      positions[n.id] = {
        x: svgW / 2,
        y: 28 + idx * vGap
      };
    });

    const activeNodeId = step.eventType === "PROGRAM_START" ? "start" : `L${step.line}`;
    const nextNodeId = step.nextLine ? `L${step.nextLine}` : "end";

    let edgesSVG = "";
    cfg.edges.forEach((edge) => {
      const p1 = positions[edge.from];
      const p2 = positions[edge.to];
      if (!p1 || !p2) return;

      const isTransition = edge.from === activeNodeId && edge.to === nextNodeId;
      const stroke = isTransition ? "#f59e0b" : edge.isBackEdge ? "#6366f1" : "#334155";
      const strokeWidth = isTransition ? 2.5 : 1.5;

      if (edge.isBackEdge || p2.y <= p1.y) {
        const curveX = 34;
        edgesSVG += `<path d="M ${p1.x - nodeW / 2} ${p1.y} C ${curveX} ${p1.y}, ${curveX} ${p2.y}, ${p2.x - nodeW / 2} ${p2.y}" fill="none" stroke="${stroke}" stroke-width="${strokeWidth}" stroke-dasharray="4 3" />`;
      } else {
        edgesSVG += `<line x1="${p1.x}" y1="${p1.y + nodeH / 2}" x2="${p2.x}" y2="${p2.y - nodeH / 2}" stroke="${stroke}" stroke-width="${strokeWidth}" />`;
      }
    });

    let nodesSVG = "";
    cfg.nodes.forEach((node) => {
      const pos = positions[node.id];
      const isCurrent =
        (step.eventType === "PROGRAM_START" && node.id === "start") ||
        (step.eventType !== "PROGRAM_START" && node.line === step.line);
      const isNext = node.line === step.nextLine && !isCurrent;

      let fill = "#1e293b";
      let stroke = "#334155";
      if (node.type === "start" || node.type === "end") {
        fill = "#0f172a";
        stroke = "#475569";
      } else if (node.type === "condition" || node.type === "loop") {
        fill = "#1e1b4b";
        stroke = "#6366f1";
      }

      if (isCurrent) {
        fill = "#312e81";
        stroke = "#818cf8";
      } else if (isNext) {
        stroke = "#f59e0b";
      }

      const rx = node.type === "start" || node.type === "end" ? 18 : 7;
      nodesSVG += `
        <g transform="translate(${pos.x - nodeW / 2}, ${pos.y - nodeH / 2})" style="cursor:pointer" data-line="${node.line}">
          <rect width="${nodeW}" height="${nodeH}" rx="${rx}" fill="${fill}" stroke="${stroke}" stroke-width="${isCurrent ? 2.5 : 1.5}" />
          <text x="${nodeW / 2}" y="${nodeH / 2 + 4}" text-anchor="middle" fill="#f8fafc" font-family="JetBrains Mono, monospace" font-size="11" font-weight="${isCurrent ? "700" : "500"}">
            ${this.escapeHTML(node.label)}
          </text>
        </g>
      `;
    });

    this.flowSvgContainer.innerHTML = `
      <svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}">
        ${edgesSVG}
        ${nodesSVG}
      </svg>
    `;
  }

  renderMemoryScopes(step) {
    this.memoryScroll.innerHTML = "";
    const scopes = step.scopes || [];
    this.frameCountBadge.textContent = `${scopes.length} Frame${scopes.length > 1 ? "s" : ""}`;

    [...scopes].reverse().forEach((scope) => {
      const card = document.createElement("div");
      card.className = "scope-card";

      const header = document.createElement("div");
      header.className = `scope-header ${scope.isActive ? "active-frame" : ""}`;
      header.innerHTML = `
        <span>${this.escapeHTML(scope.frameName)}</span>
        <span>${scope.isActive ? "● ACTIVE SCOPE" : "CALLER"}</span>
      `;
      card.appendChild(header);

      const varList = document.createElement("div");
      varList.className = "var-list";

      if (scope.variables.length === 0) {
        varList.innerHTML = `<div class="empty-state" style="padding:8px;">No variables stored in this frame yet.</div>`;
      } else {
        const idxVar = scope.variables.find((v) =>
          ["i", "idx", "index", "k"].includes(v.name) && typeof v.value === "number"
        );
        const activeIdxVal = idxVar ? idxVar.value : null;

        scope.variables.forEach((v) => {
          const item = document.createElement("div");
          item.className = "var-item";
          if (v.status === "updated") item.classList.add("var-changed");
          if (v.status === "new") item.classList.add("var-new");

          let badgeHTML = "";
          if (v.status === "new") {
            badgeHTML = `<span class="var-badge-change new">NEW</span>`;
          } else if (v.status === "updated") {
            badgeHTML = `<span class="var-badge-change updated">UPDATED</span>`;
          }

          let valDiffHTML = `<span class="var-curr-val">${this.escapeHTML(v.formattedValue)}</span>`;
          if (v.status === "updated" && v.prevFormattedValue !== null) {
            valDiffHTML = `
              <span class="var-prev-val">${this.escapeHTML(v.prevFormattedValue)}</span>
              <span class="var-arrow">→</span>
              <span class="var-curr-val">${this.escapeHTML(v.formattedValue)}</span>
            `;
          }

          let arrayVisualizerHTML = "";
          if (Array.isArray(v.value)) {
            const cells = v.value
              .map((cellVal, cIdx) => {
                const isPointed = activeIdxVal === cIdx;
                return `
                  <div class="array-cell ${isPointed ? "active-index" : ""}">
                    <span class="array-cell-idx">[${cIdx}]</span>
                    <span class="array-cell-val">${this.escapeHTML(String(cellVal))}</span>
                  </div>
                `;
              })
              .join("");
            arrayVisualizerHTML = `<div class="array-cells">${cells}</div>`;
          }

          item.innerHTML = `
            <div class="var-top-row">
              <div class="var-name-group">
                <span class="var-name">${this.escapeHTML(v.name)}</span>
                <span class="var-type">${v.type}</span>
              </div>
              ${badgeHTML}
            </div>
            <div class="var-value-row">
              ${valDiffHTML}
            </div>
            ${arrayVisualizerHTML}
          `;
          varList.appendChild(item);
        });
      }

      card.appendChild(varList);
      this.memoryScroll.appendChild(card);
    });
  }

  renderVariableTimeline() {
    if (!this.traceResult) return;
    const history = this.traceResult.variableTimeline || [];
    const currentStepNumber = this.currentStepIdx + 1;

    if (history.length === 0) {
      this.historyScroll.innerHTML = `<div class="empty-state">No variable calculations recorded.</div>`;
      return;
    }

    let rowsHTML = "";
    history.forEach((h) => {
      const isCurrent = h.stepIndex === currentStepNumber;
      const isFuture = h.stepIndex > currentStepNumber;
      const changeStr =
        h.status === "new"
          ? `<span style="color:#22d3ee">init → ${this.escapeHTML(h.newVal)}</span>`
          : `<span style="color:#94a3b8">${this.escapeHTML(h.prevVal)}</span> → <strong style="color:#34d399">${this.escapeHTML(h.newVal)}</strong>`;

      rowsHTML += `
        <tr class="${isCurrent ? "active-history-row" : ""}" style="${isFuture ? "opacity:0.4;" : ""}" data-step="${h.stepIndex - 1}">
          <td>#${h.stepIndex} (L${h.line})</td>
          <td><strong>${this.escapeHTML(h.varName)}</strong></td>
          <td>${changeStr}</td>
          <td>${this.escapeHTML(h.evalBreakdown)}</td>
        </tr>
      `;
    });

    this.historyScroll.innerHTML = `
      <div style="font-size:12px; color:#94a3b8; margin-bottom:6px;">
        Full step-by-step calculation trail showing how every variable and final answer is computed (click any row to jump to that step):
      </div>
      <table class="timeline-table">
        <thead>
          <tr>
            <th>Step</th>
            <th>Variable</th>
            <th>Value Change</th>
            <th>How It Was Calculated</th>
          </tr>
        </thead>
        <tbody>${rowsHTML}</tbody>
      </table>
    `;

    this.historyScroll.querySelectorAll("tbody tr").forEach((tr) => {
      tr.addEventListener("click", () => {
        const idx = Number(tr.dataset.step);
        this.pause();
        this.goToStep(idx);
      });
    });
  }

  renderMechanicsCard(step) {
    this.mechanicsContainer.innerHTML = "";
    this.mechanicsContainer.classList.add("hidden");

    // 1. Loop Internals Visualizer
    if (step.loopMechanics) {
      const lm = step.loopMechanics;
      this.mechanicsContainer.classList.remove("hidden");

      if (lm.loopType === "for") {
        const boxesHTML = lm.items
          .map((itemVal, idx) => {
            const isCurrent = idx === lm.currentIndex;
            const isPast = idx < lm.currentIndex;
            const ptrLabel = isCurrent
              ? `▼ ${lm.iterVar}`
              : isPast
              ? "✓"
              : `[${idx}]`;
            return `
              <div class="loop-item-box ${isCurrent ? "current-item" : ""} ${isPast ? "past-item" : ""}">
                <span class="loop-item-ptr">${this.escapeHTML(ptrLabel)}</span>
                <span class="loop-item-val">${this.escapeHTML(itemVal)}</span>
              </div>
            `;
          })
          .join("");

        this.mechanicsContainer.innerHTML = `
          <div class="mechanics-card loop-card">
            <div class="explanation-label" style="color:#22d3ee;">🔄 How This For-Loop Works Internally</div>
            <div class="explanation-text">
              ${
                lm.currentValue === "DONE"
                  ? `All <strong>${lm.totalItems}</strong> items in <code>${this.escapeHTML(lm.iterExpr)}</code> have been visited! Loop exits.`
                  : `Pass <strong>${lm.currentIndex + 1} of ${lm.totalItems}</strong>: Python points at index <code>[${lm.currentIndex}]</code> and unpacks <code>${this.escapeHTML(lm.iterVar)} = ${this.escapeHTML(lm.currentValue)}</code>:`
              }
            </div>
            <div class="loop-strip">${boxesHTML}</div>
          </div>
        `;
      } else {
        this.mechanicsContainer.innerHTML = `
          <div class="mechanics-card loop-card">
            <div class="explanation-label" style="color:#22d3ee;">🔄 How This While-Loop Works Internally</div>
            <div class="explanation-text">
              Check #<strong>${lm.iteration}</strong>: Before running the loop body, Python tests <code>${this.escapeHTML(lm.condition)}</code> (${this.escapeHTML(lm.substituted)}) → <strong>${lm.isContinuing ? "True (Keep Looping)" : "False (Stop Loop)"}</strong>.
            </div>
          </div>
        `;
      }
      return;
    }

    // 2. Condition Truth Evaluator Visualizer
    if (step.conditionMechanics) {
      const cm = step.conditionMechanics;
      this.mechanicsContainer.classList.remove("hidden");
      this.mechanicsContainer.innerHTML = `
        <div class="mechanics-card cond-card">
          <div class="explanation-label" style="color:#fbbf24;">⚖️ How This Condition Evaluates to True or False</div>
          <div class="cond-eval-grid">
            <div class="cond-operand">
              <span class="cond-expr-label">Left: ${this.escapeHTML(cm.leftExpr)}</span>
              <span class="cond-expr-val">${this.escapeHTML(cm.leftVal)}</span>
            </div>
            <span class="cond-op-badge">${this.escapeHTML(cm.operator)}</span>
            <div class="cond-operand">
              <span class="cond-expr-label">Right: ${this.escapeHTML(cm.rightExpr)}</span>
              <span class="cond-expr-val">${this.escapeHTML(cm.rightVal)}</span>
            </div>
            <span class="cond-verdict ${cm.result ? "verdict-true" : "verdict-false"}">
              ${cm.result ? "✓ TRUE" : "✗ FALSE"}
            </span>
          </div>
        </div>
      `;
      return;
    }

    // 3. Function Call / Parameter / Return Visualizer
    if (step.functionMechanics) {
      const fm = step.functionMechanics;
      this.mechanicsContainer.classList.remove("hidden");

      let extraHTML = "";
      if (fm.type === "CALL" && fm.mappings) {
        extraHTML = `
          <div class="param-map-list">
            ${fm.mappings
              .map(
                (m) => `
              <div class="param-map-row">
                <span>Caller Argument: <code>${this.escapeHTML(m.argExpr)}</code> (${this.escapeHTML(m.argVal)})</span>
                <span style="color:#a855f7;">➔</span>
                <span>Function Parameter: <strong><code>${this.escapeHTML(m.paramName)} = ${this.escapeHTML(m.argVal)}</code></strong></span>
              </div>
            `
              )
              .join("")}
          </div>
        `;
      } else if (fm.type === "RETURN") {
        extraHTML = `
          <div class="param-map-row">
            <span>Return Expression: <code>${this.escapeHTML(fm.returnExpr)}</code></span>
            <span style="color:#34d399;">➔</span>
            <span>Sends Back Value: <strong><code>${this.escapeHTML(fm.returnValue)}</code></strong></span>
          </div>
        `;
      }

      this.mechanicsContainer.innerHTML = `
        <div class="mechanics-card func-card">
          <div class="explanation-label" style="color:#d8b4fe;">📦 How Functions, Parameters &amp; Return Work</div>
          <div class="explanation-text">${this.formatMarkdownCode(fm.note)}</div>
          ${extraHTML}
        </div>
      `;
    }
  }

  renderAITutorPanel(step) {
    this.eventBadge.textContent = step.eventType.replace("_", " ");
    this.stepLineBadge.textContent = `Line ${step.line} (Step ${step.stepIndex})`;
    this.stepCodePreview.textContent = step.codeText;
    this.evalBreakdownBox.textContent = step.evalBreakdown;

    this.renderMechanicsCard(step);

    const mainExplanation =
      step.explanations[this.explanationDepth] || step.explanations.beginner;

    this.whatHappenedText.innerHTML = this.formatMarkdownCode(mainExplanation);
    this.howNextDecidedText.innerHTML = this.formatMarkdownCode(
      step.explanations.howNextLineDecided || ""
    );
    this.whyHappenedText.innerHTML = this.formatMarkdownCode(
      step.explanations.whyItHappened || ""
    );
    this.whatNextText.innerHTML = this.formatMarkdownCode(
      step.explanations.whatNext || ""
    );

    if (this.quizModeEnabled && step.quiz) {
      this.quizCard.classList.remove("hidden");
      this.quizQuestion.innerHTML = this.formatMarkdownCode(step.quiz.question);
      this.quizOptions.innerHTML = "";
      step.quiz.options.forEach((opt) => {
        const btn = document.createElement("button");
        btn.className = "quiz-option-btn";
        btn.textContent = opt.label;
        btn.addEventListener("click", () => {
          btn.classList.add(opt.isCorrect ? "correct" : "wrong");
          btn.textContent = `${opt.label} ${opt.isCorrect ? "✓ Correct!" : "✗ Try again"}`;
        });
        this.quizOptions.appendChild(btn);
      });
    } else {
      this.quizCard.classList.add("hidden");
    }
  }

  handleAskAI() {
    const q = this.chatInput.value.trim();
    if (!q || !this.traceResult) return;

    const step = this.traceResult.steps[this.currentStepIdx];
    const activeScope = step.scopes[step.scopes.length - 1];
    const varsSummary = activeScope.variables
      .map((v) => `\`${v.name} = ${v.formattedValue}\``)
      .join(", ");

    let answer = "";
    const lower = q.toLowerCase();

    if (lower.includes("final") || lower.includes("calculate") || lower.includes("answer")) {
      const historyCount = this.traceResult.variableTimeline.length;
      const lastStep = this.traceResult.steps[this.traceResult.steps.length - 1];
      const finalOut =
        lastStep.stdout && lastStep.stdout.length
          ? lastStep.stdout.map((o) => `\`${o.text}\``).join(", ")
          : "see variables in memory";
      answer = `**How the Final Answer Gets Calculated:** Across ${this.traceResult.steps.length} steps and ${historyCount} variable updates, Python builds the final result (${finalOut}). Click the **"How Final Answer is Calculated"** tab in the center panel to inspect every intermediate calculation!`;
    } else if (lower.includes("next") || lower.includes("decide") || lower.includes("order")) {
      answer = `**How Python Decides Which Line Runs Next:** ${step.explanations.howNextLineDecided} (${step.explanations.whatNext})`;
    } else if (lower.includes("loop") || lower.includes("condition") || lower.includes("true") || lower.includes("false")) {
      answer = `**Internal Mechanics on Line ${step.line}:** ${step.explanations.beginner} Evaluation breakdown: \`${step.evalBreakdown}\`.`;
    } else if (lower.includes("function") || lower.includes("parameter") || lower.includes("return") || lower.includes("argument")) {
      answer = `**Functions, Parameters & Return:** When a function is called, arguments from the caller are copied into the function's parameter variables in a new Call Stack frame. When \`return\` runs, that value is sent back to the caller line!`;
    } else {
      answer = `**Senior Dev Mentor (Step ${step.stepIndex}, Line ${step.line}):** ${step.explanations.eli5} Current evaluation: \`${step.evalBreakdown}\`. Variables in memory right now: ${varsSummary || "none yet"}.`;
    }

    this.aiAnswerBubble.innerHTML = this.formatMarkdownCode(answer);
    this.aiAnswerBubble.classList.remove("hidden");
    this.chatInput.value = "";
  }

  formatMarkdownCode(str) {
    if (!str) return "";
    return this.escapeHTML(str)
      .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
      .replace(/`([^`]+)`/g, "<code>$1</code>");
  }

  escapeHTML(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }
}

window.addEventListener("DOMContentLoaded", () => {
  window.visualizerApp = new CodeFlowVisualizerApp();
});

:root {
  --bg-app: #0d1117;
  --bg-panel: #161b22;
  --bg-elevated: #1c2128;
  --bg-input: #0d1117;
  --bg-hover: #21262d;

  --border-subtle: #30363d;
  --border-muted: #21262d;
  --border-focus: #58a6ff;

  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;

  --accent-blue: #58a6ff;
  --accent-green: #3fb950;
  --accent-amber: #d29922;
  --accent-red: #f85149;
  --accent-purple: #bc8cff;
  --accent-cyan: #39c5cf;

  /* Line execution states */
  --line-current-bg: rgba(88, 166, 255, 0.16);
  --line-current-border: #58a6ff;
  --line-executed-bg: rgba(63, 185, 80, 0.06);
  --line-executed-border: rgba(63, 185, 80, 0.45);
  --line-next-bg: rgba(210, 153, 34, 0.12);
  --line-next-border: #d29922;

  /* Syntax Highlighting Colors (GitHub Dark Pro inspired) */
  --syn-keyword: #ff7b72;
  --syn-builtin: #d2a8ff;
  --syn-string: #a5d6ff;
  --syn-number: #79c0ff;
  --syn-comment: #8b949e;
  --syn-op: #ff7b72;
  --syn-func: #d2a8ff;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', Consolas, monospace;

  --radius-sm: 5px;
  --radius-md: 8px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-app);
  color: var(--text-primary);
  font-family: var(--font-sans);
  height: 100vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-size: 13px;
}

/* Top Application Bar */
.app-header {
  height: 50px;
  background-color: var(--bg-panel);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  flex-shrink: 0;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand-logo {
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background-color: #1f6feb;
  color: #ffffff;
  font-weight: 700;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
}

.brand-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.brand-tag {
  font-size: 11px;
  font-weight: 500;
  color: var(--accent-blue);
  background: rgba(88, 166, 255, 0.1);
  border: 1px solid rgba(88, 166, 255, 0.3);
  padding: 1px 7px;
  border-radius: 99px;
}

/* Playback Transport Controls in Header */
.transport-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.scrubber-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 260px;
  margin: 0 8px;
}

.step-badge {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  white-space: nowrap;
}

input[type="range"].timeline-slider {
  -webkit-appearance: none;
  appearance: none;
  flex: 1;
  height: 5px;
  border-radius: 99px;
  background: var(--border-subtle);
  outline: none;
  cursor: pointer;
}

input[type="range"].timeline-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent-blue);
  border: 2px solid var(--bg-panel);
  cursor: pointer;
}

.speed-select {
  background: var(--bg-input);
  color: var(--text-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 4px 6px;
  font-size: 12px;
  font-family: var(--font-mono);
  outline: none;
  cursor: pointer;
}

/* Buttons & Inputs */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 5px 11px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 500;
  font-family: var(--font-sans);
  cursor: pointer;
  border: 1px solid var(--border-subtle);
  background: var(--bg-elevated);
  color: var(--text-primary);
  transition: background 0.12s ease, border-color 0.12s ease;
}

.btn:hover:not(:disabled) {
  background: var(--bg-hover);
  border-color: #484f58;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn-primary {
  background: #238636;
  border-color: rgba(240, 246, 252, 0.1);
  color: #ffffff;
  font-weight: 600;
}

.btn-primary:hover:not(:disabled) {
  background: #2ea043;
}

.btn-accent {
  background: #1f6feb;
  border-color: rgba(240, 246, 252, 0.1);
  color: #ffffff;
  font-weight: 600;
}

.btn-accent:hover:not(:disabled) {
  background: #388bfd;
}

.select-input {
  background: var(--bg-input);
  color: var(--text-primary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 4px 8px;
  font-size: 12px;
  font-family: var(--font-sans);
  outline: none;
  cursor: pointer;
}

/* Upper 3-Column Workspace (Panels A, B, C) */
.upper-workspace {
  flex: 1;
  display: grid;
  grid-template-columns: 1.05fr 1.3fr 1fr;
  gap: 1px;
  background-color: var(--border-subtle);
  min-height: 0;
}

.panel {
  background-color: var(--bg-panel);
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.panel-header {
  height: 38px;
  padding: 0 12px;
  background-color: var(--bg-elevated);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  gap: 8px;
}

.panel-title {
  font-size: 11.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.panel-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

/* ==========================================
   PANEL A: Code Editor — Left Panel
   ========================================== */
.editor-subbar {
  padding: 6px 12px;
  background: var(--bg-app);
  border-bottom: 1px solid var(--border-muted);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  flex-wrap: wrap;
}

.line-state-legend {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 5px 12px;
  background: var(--bg-panel);
  border-bottom: 1px solid var(--border-muted);
  font-size: 11px;
  color: var(--text-secondary);
}

.legend-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.legend-swatch {
  width: 9px;
  height: 9px;
  border-radius: 2px;
}

.swatch-current {
  background: var(--line-current-bg);
  border: 1.5px solid var(--line-current-border);
}

.swatch-executed {
  background: var(--line-executed-bg);
  border: 1.5px solid var(--line-executed-border);
}

.swatch-next {
  background: var(--line-next-bg);
  border: 1.5px solid var(--line-next-border);
}

.swatch-upcoming {
  background: transparent;
  border: 1px dashed var(--text-muted);
}

.editor-main-area {
  flex: 1;
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--bg-input);
}

.code-lines-container {
  flex: 1;
  overflow-y: auto;
  padding: 8px 0;
  font-family: var(--font-mono);
  font-size: 13px;
  line-height: 1.65;
}

.code-row {
  display: flex;
  align-items: center;
  padding: 1px 12px 1px 0;
  border-left: 3px solid transparent;
  cursor: pointer;
  transition: background-color 0.12s ease;
}

.code-row:hover {
  background-color: rgba(255, 255, 255, 0.03);
}

.code-row.state-current {
  background-color: var(--line-current-bg);
  border-left-color: var(--line-current-border);
}

.code-row.state-executed {
  background-color: var(--line-executed-bg);
  border-left-color: var(--line-executed-border);
}

.code-row.state-next {
  background-color: var(--line-next-bg);
  border-left-color: var(--line-next-border);
}

.code-row.state-upcoming {
  opacity: 0.78;
}

.code-gutter {
  width: 56px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 10px;
  gap: 5px;
  user-select: none;
  flex-shrink: 0;
}

.gutter-marker {
  font-size: 10px;
  width: 14px;
  text-align: center;
}

.gutter-ln {
  color: var(--text-muted);
  font-size: 11.5px;
}

.code-syntax {
  white-space: pre;
  flex: 1;
  color: var(--text-primary);
}

.code-row-badges {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-left: 8px;
}

.step-order-tag {
  font-size: 10px;
  font-family: var(--font-mono);
  padding: 0 5px;
  border-radius: 3px;
  background: rgba(139, 148, 158, 0.12);
  color: var(--text-secondary);
}

.inline-state-tag {
  font-size: 10.5px;
  font-family: var(--font-mono);
  padding: 0 6px;
  border-radius: 3px;
  background: rgba(88, 166, 255, 0.15);
  color: var(--accent-blue);
  border: 1px solid rgba(88, 166, 255, 0.3);
}

/* Syntax Highlighting Spans */
.syn-kw { color: var(--syn-keyword); font-weight: 600; }
.syn-bi { color: var(--syn-builtin); }
.syn-str { color: var(--syn-string); }
.syn-num { color: var(--syn-number); }
.syn-com { color: var(--syn-comment); font-style: italic; }
.syn-fn { color: var(--syn-func); font-weight: 600; }

/* Live Editable Code Mirror Overlay / Mode */
.live-editor-wrap {
  flex: 1;
  display: flex;
  overflow: hidden;
  background: var(--bg-input);
}

.editor-line-numbers {
  width: 44px;
  padding: 10px 8px 10px 0;
  text-align: right;
  font-family: var(--font-mono);
  font-size: 13px;
  line-height: 1.65;
  color: var(--text-muted);
  background: var(--bg-panel);
  border-right: 1px solid var(--border-muted);
  user-select: none;
  overflow: hidden;
}

.code-textarea {
  flex: 1;
  background: var(--bg-input);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 13px;
  line-height: 1.65;
  padding: 10px 12px;
  border: none;
  outline: none;
  resize: none;
  tab-size: 4;
}

/* ==========================================
   PANEL B: Execution Flow — Center Panel
   ========================================== */
.flow-panel-content {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.flow-status-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.metric-box {
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 7px 10px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.metric-label {
  font-size: 10px;
  text-transform: uppercase;
  color: var(--text-secondary);
  font-weight: 600;
}

.metric-value {
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}

.metric-value.highlight-blue { color: var(--accent-blue); }
.metric-value.highlight-amber { color: var(--accent-amber); }
.metric-value.highlight-cyan { color: var(--accent-cyan); }

.flow-step-card {
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.flow-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-muted);
  padding-bottom: 6px;
}

.flow-card-title {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.flow-code-pill {
  font-family: var(--font-mono);
  font-size: 12.5px;
  background: var(--bg-elevated);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  border-left: 3px solid var(--accent-blue);
  color: var(--text-primary);
}

.flow-step-explanation {
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--text-primary);
}

.flow-step-explanation code {
  font-family: var(--font-mono);
  font-size: 11.5px;
  background: var(--bg-elevated);
  padding: 1px 5px;
  border-radius: 3px;
  color: var(--accent-cyan);
}

.flow-details-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.flow-mini-box {
  background: var(--bg-elevated);
  border: 1px solid var(--border-muted);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.flow-mini-label {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
}

.flow-mini-content {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text-primary);
}

.flowchart-box {
  flex: 1;
  min-height: 210px;
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.flowchart-svg-wrap {
  flex: 1;
  overflow: auto;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 12px;
}

/* ==========================================
   PANEL C: Variable Inspector — Right Panel
   ========================================== */
.inspector-body {
  flex: 1;
  overflow-y: auto;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.var-inspector-table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-mono);
  font-size: 12px;
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.var-inspector-table th {
  background: var(--bg-elevated);
  color: var(--text-secondary);
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 600;
  text-align: left;
  padding: 7px 8px;
  border-bottom: 1px solid var(--border-subtle);
}

.var-inspector-table td {
  padding: 7px 8px;
  border-bottom: 1px solid var(--border-muted);
  color: var(--text-primary);
}

.var-inspector-table tr.row-created {
  background: rgba(57, 197, 207, 0.12);
}

.var-inspector-table tr.row-updated {
  background: rgba(63, 185, 80, 0.14);
}

.val-prev {
  color: var(--text-muted);
}

.val-curr {
  font-weight: 600;
  color: var(--text-primary);
}

.row-updated .val-curr {
  color: var(--accent-green);
}

.row-created .val-curr {
  color: var(--accent-cyan);
}

.status-pill {
  font-family: var(--font-sans);
  font-size: 10px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 99px;
  text-transform: uppercase;
}

.status-created {
  background: rgba(57, 197, 207, 0.18);
  color: var(--accent-cyan);
