// explainer.js — "Teach Me This Code" Rule-Based Teacher & Advanced Explanation Engine
// Preserves full compatibility with engine.js while providing beginner-friendly teacher lessons.

const PYTHON_SYMBOLS_LIBRARY = [
  { token: "class", label: "class", desc: "Groups related functions together under one name." },
  { token: "def", label: "def", desc: "Creates a function (a reusable set of instructions)." },
  { token: "for", label: "for", desc: "Repeats the indented lines once for each item in a list or range." },
  { token: "while", label: "while", desc: "Keeps repeating the indented lines as long as a condition is True." },
  { token: "range(", label: "range(len(nums))", desc: "Creates index numbers 0, 1, 2... up to the last position in the list." },
  { token: "+=", label: "+=", desc: "Adds a number to the existing variable and saves the new total." },
  { token: "-=", label: "-=", desc: "Subtracts a number from the existing variable." },
  { token: ">=", label: ">=", desc: "Asks: 'Is the left number greater than or equal to the right number?'" },
  { token: "<=", label: "<=", desc: "Asks: 'Is the left number less than or equal to the right number?'" },
  { token: "==", label: "==", desc: "Asks: 'Are these two values equal?'" },
  { token: "<", label: "<", desc: "Asks: 'Is the left number smaller than the right number?'" },
  { token: ">", label: ">", desc: "Asks: 'Is the left number larger than the right number?'" },
  { token: "=", label: "=", desc: "Stores the value on the right inside the variable name on the left." },
  { token: "[", label: "nums[i]", desc: "Looks up the number at position `i` in the list `nums`." },
  { token: "return", label: "return", desc: "Finishes the function and gives back the final answer." }
];

class RuleBasedExplainer {
  enrichTraceWithExplanations(traceResult) {
    if (!traceResult || !traceResult.steps) return traceResult;
    const steps = traceResult.steps;

    // Find the best contiguous subarray if `nums` is present so we can show it at the end
    const bestSubarrayInfo = this.computeBestSubarray(traceResult);

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];
      const prevStep = i > 0 ? steps[i - 1] : null;
      const nextStep = i + 1 < steps.length ? steps[i + 1] : null;

      step.teacherLesson = this.buildTeacherLesson(step, prevStep, nextStep, bestSubarrayInfo);
      step.explanations = this.buildStepExplanation(step, prevStep, nextStep);
      step.practiceQuestion = this.buildPracticeChallenge(step, nextStep);
    }

    traceResult.bestSubarrayInfo = bestSubarrayInfo;
    traceResult.executionSummary = this.buildExecutionSummary(traceResult);
    return traceResult;
  }

  computeBestSubarray(traceResult) {
    const steps = traceResult.steps || [];
    if (!steps.length) return null;

    // Extract input array `nums` from the first step that has it
    let numsArr = null;
    for (const s of steps) {
      const numsRow = (s.variables || []).find((v) => v.name === "nums" && Array.isArray(v.rawValue));
      if (numsRow) {
        numsArr = numsRow.rawValue;
        break;
      }
    }
    if (!numsArr || !numsArr.length) return null;

    let bestSum = numsArr[0];
    let bestStart = 0;
    let bestEnd = 0;
    let currentSum = 0;
    let currentStart = 0;

    for (let i = 0; i < numsArr.length; i++) {
      if (currentSum === 0) currentStart = i;
      currentSum += numsArr[i];
      if (currentSum >= bestSum) {
        bestSum = currentSum;
        bestStart = currentStart;
        bestEnd = i;
      }
      if (currentSum < 0) {
        currentSum = 0;
      }
    }

    return {
      subarray: numsArr.slice(bestStart, bestEnd + 1),
      startIndex: bestStart,
      endIndex: bestEnd,
      maxSum: bestSum
    };
  }

  buildTeacherLesson(step, prevStep, nextStep, bestSubarrayInfo) {
    const n = step.stepIndex;
    const op = step.operationDetail || {};
    const cond = step.condition;
    const nextSentence = this.buildFriendlyWhatNext(step, nextStep);
    const relevantVarsNow = this.formatRelevantVariablesNow(step);

    // 1. Class definition
    if (step.eventType === "CLASS_DEF") {
      return {
        title: `Step ${n}: Create the Solution class`,
        calculationCard: null,
        whatItMeans:
          `Python reads \`class Solution:\`, which is a wrapper container that holds our function. Creating the class does not calculate the answer yet—it just prepares the container.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 2. Method / Function definition
    if (step.eventType === "METHOD_DEF" || step.eventType === "FUNC_DEF") {
      return {
        title: `Step ${n}: Define the ${op.funcName} function`,
        calculationCard: null,
        whatItMeans:
          `Python registers the function \`${op.funcName}\`, which takes a list of numbers called \`${(op.params || ["nums"]).join(", ")}\`. Python only runs the code inside a function when we call it.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 3. Function Call
    if (step.eventType === "FUNC_CALL") {
      const b = (op.paramBindings || [])[0];
      return {
        title: `Step ${n}: Call the function with our list`,
        calculationCard: null,
        whatItMeans: b
          ? `Now we call \`${op.funcName}(nums)\` and pass in our list \`${b.val}\`. Python jumps inside the function to start working through the steps!`
          : `Now we call \`${op.funcName}()\` and jump inside the function to begin executing its lines.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 4. Standard variable assignment (`c = 0`, `ans = nums[0]`, `ans = c`, `c = 0`)
    if (step.eventType === "ASSIGN") {
      if (op.target === "c" && op.isCreated) {
        return {
          title: `Step ${n}: Create the variable c`,
          calculationCard: null,
          whatItMeans:
            `We create a variable named \`c\` and store the number \`${op.afterVal}\` inside it. \`c\` will keep track of our running sum as we add numbers from the list.`,
          variableValuesNow: relevantVarsNow,
          whatHappensNext: nextSentence,
          finalBanner: null
        };
      }
      if (op.target === "ans" && op.isCreated) {
        return {
          title: `Step ${n}: Create the variable ans`,
          calculationCard: null,
          whatItMeans:
            `We create a variable named \`ans\` and set it to the very first number in the list (\`nums[0]\`, which is \`${op.afterVal}\`). \`ans\` remembers the largest sum we have seen so far. Starting with \`nums[0]\` makes sure our code works even if every number in the list is negative!`,
          variableValuesNow: relevantVarsNow,
          whatHappensNext: nextSentence,
          finalBanner: null
        };
      }
      if (op.target === "ans" && !op.isCreated) {
        return {
          title: `Step ${n}: Save the new largest sum in ans`,
          calculationCard: {
            currentNumber: null,
            before: `ans = ${op.beforeVal}`,
            calculation: `ans = c (${op.afterVal})`,
            after: `ans = ${op.afterVal}`
          },
          whatItMeans:
            `Because our current sum \`c\` (\`${op.afterVal}\`) is at least as big as \`ans\` (\`${op.beforeVal}\`), we update \`ans\` to \`${op.afterVal}\`! This is our new best sum so far.`,
          variableValuesNow: relevantVarsNow,
          whatHappensNext: nextSentence,
          finalBanner: null
        };
      }
      if (op.target === "c" && op.afterVal === "0" && !op.isCreated) {
        return {
          title: `Step ${n}: Reset c to zero`,
          calculationCard: {
            currentNumber: null,
            before: `c = ${op.beforeVal}`,
            calculation: `Reset negative sum to 0`,
            after: `c = 0`
          },
          whatItMeans:
            `Because \`c\` was negative (\`${op.beforeVal}\`), keeping it would only make future sums smaller. So we reset \`c\` back to \`0\` to start a fresh continuous section on the next number!`,
          variableValuesNow: relevantVarsNow,
          whatHappensNext: nextSentence,
          finalBanner: null
        };
      }

      return {
        title: `Step ${n}: ${op.isCreated ? "Create" : "Update"} the variable ${op.target}`,
        calculationCard: op.isCreated
          ? null
          : {
              currentNumber: null,
              before: `${op.target} = ${op.beforeVal}`,
              calculation: `${op.target} = ${op.substituted}`,
              after: `${op.target} = ${op.afterVal}`
            },
        whatItMeans: op.isCreated
          ? `We create a variable named \`${op.target}\` and store \`${op.afterVal}\` inside it.`
          : `We calculate \`${op.substituted}\` and update \`${op.target}\` from \`${op.beforeVal}\` to \`${op.afterVal}\`.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 5. Addition / Augmented Assignment (`c += nums[i]`)
    if (step.eventType === "AUG_ASSIGN") {
      const afterNum = Number(op.afterVal);
      const ansRow = (step.variables || []).find((v) => v.name === "ans");
      const ansNum = ansRow ? Number(ansRow.current) : null;

      let teacherNote = `We added \`${op.rhsVal}\` to \`${op.target}\`, changing \`${op.target}\` from \`${op.beforeVal}\` to \`${op.afterVal}\`.`;
      if (op.target === "c") {
        if (afterNum < 0 && ansNum !== null && afterNum >= ansNum) {
          teacherNote = `We added \`${op.rhsVal}\` to \`c\`, giving \`${op.afterVal}\`. That matches or beats \`ans\` (\`${ansNum}\`), and because \`c\` is negative, the second condition will reset \`c\` to zero.`;
        } else if (afterNum < 0) {
          teacherNote = `We added \`${op.rhsVal}\` to \`c\`, giving \`${op.afterVal}\`. Because the result is negative, the \`if c < 0:\` check will reset \`c\` to zero.`;
        } else if (ansNum !== null && afterNum >= ansNum) {
          teacherNote = `We added \`${op.rhsVal}\` to \`c\`, bringing \`c\` up to \`${op.afterVal}\`! Because \`${op.afterVal}\` is at least as large as our best sum \`ans\` (\`${ansNum}\`), the next condition will update \`ans\` to \`${op.afterVal}\`!`;
        } else {
          teacherNote = `We added \`${op.rhsVal}\` to \`c\`, changing \`c\` from \`${op.beforeVal}\` to \`${op.afterVal}\`. Since \`c\` is still positive, we keep building this continuous section.`;
        }
      }

      return {
        title: `Step ${n}: Add the current number`,
        calculationCard: {
          currentNumber: op.rhsVal,
          before: `${op.target} = ${op.beforeVal}`,
          calculation: `${op.target} = ${op.beforeVal} ${op.baseOp} (${op.rhsVal})`,
          after: `${op.target} = ${op.afterVal}`
        },
        whatItMeans: teacherNote,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 6. Loop iteration (`for i in range(len(nums)):`)
    if (step.eventType === "LOOP_ITER" && op.kind === "for_iter") {
      const elemInfo = op.indexedElementInfo;
      return {
        title: `Step ${n}: Loop pass ${op.iteration} of ${op.total} (i = ${op.iterVal})`,
        calculationCard: elemInfo
          ? {
              currentNumber: elemInfo.elementVal,
              before: `Position i = ${elemInfo.indexVal}`,
              calculation: `Look up ${elemInfo.arrayName}[${elemInfo.indexVal}]`,
              after: `Current number is ${elemInfo.elementVal}`
            }
          : null,
        whatItMeans: elemInfo
          ? `The loop moves to position \`i = ${op.iterVal}\` (item ${op.iteration} of ${op.total}). The number at \`nums[${op.iterVal}]\` is **\`${elemInfo.elementVal}\`**.`
          : `The loop starts pass ${op.iteration} of ${op.total} and sets \`${op.iterVar} = ${op.iterVal}\`.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 7. Loop End
    if (step.eventType === "LOOP_END") {
      return {
        title: `Step ${n}: Loop finished all numbers`,
        calculationCard: null,
        whatItMeans:
          `We have checked every single number in the list! The loop is now finished, so Python leaves the loop and moves to the final \`return\` line.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 8. Condition Check (`if c >= ans:` or `if c < 0:`)
    if (step.eventType === "CONDITION" && cond) {
      let stepTitle = `Step ${n}: Check the condition (${cond.expr})`;
      let explanation = "";

      if (cond.expr === "c >= ans") {
        stepTitle = `Step ${n}: Check if c (${cond.leftVal}) beats or ties ans (${cond.rightVal})`;
        explanation = cond.result
          ? `We ask: Is \`c >= ans\` (\`Is ${cond.leftVal} >= ${cond.rightVal}\`)? **Yes, True!** Our current sum \`c\` is at least as big as \`ans\`, so Python goes inside the \`if\` block to update \`ans\`.`
          : `We ask: Is \`c >= ans\` (\`Is ${cond.leftVal} >= ${cond.rightVal}\`)? **No, False.** \`${cond.leftVal}\` is smaller than \`${cond.rightVal}\`, so \`ans\` stays \`${cond.rightVal}\` and Python skips this \`if\` block.`;
      } else if (cond.expr === "c < 0") {
        stepTitle = `Step ${n}: Check if c (${cond.leftVal}) is negative`;
        explanation = cond.result
          ? `We ask: Is \`c < 0\` (\`Is ${cond.leftVal} < 0\`)? **Yes, True!** Because \`c\` is negative (\`${cond.leftVal}\`), Python goes inside this \`if\` block to reset \`c\` back to \`0\`.`
          : `We ask: Is \`c < 0\` (\`Is ${cond.leftVal} < 0\`)? **No, False.** Since \`${cond.leftVal}\` is not negative, we do not reset \`c\`—we keep this sum for the next number!`;
      } else {
        explanation = `We test \`${cond.expr}\` by comparing \`${cond.leftVal} ${cond.operator} ${cond.rightVal}\`, which is **${cond.result ? "True" : "False"}**.`;
      }

      return {
        title: stepTitle,
        calculationCard: {
          currentNumber: null,
          before: `${cond.leftExpr} is ${cond.leftVal}, ${cond.rightExpr} is ${cond.rightVal}`,
          calculation: `${cond.leftVal} ${cond.operator} ${cond.rightVal}`,
          after: cond.result ? "True (Run the indented line)" : "False (Skip the indented line)"
        },
        whatItMeans: explanation,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 9. Return Statement
    if (step.eventType === "RETURN") {
      const subText =
        bestSubarrayInfo && bestSubarrayInfo.subarray
          ? `The continuous section \`[${bestSubarrayInfo.subarray.join(", ")}]\` has the largest sum: **${op.returnVal}**.`
          : `The function finishes and returns the final answer: **${op.returnVal}**.`;

      return {
        title: `Step ${n}: Return the final answer (${op.returnVal})`,
        calculationCard: null,
        whatItMeans:
          `We have finished checking the entire list! \`return ans\` sends our final largest sum **\`${op.returnVal}\`** back as the answer.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: `The program is complete! You can click Restart or try a different list of numbers above.`,
        finalBanner: {
          answer: op.returnVal,
          summary: subText
        }
      };
    }

    // Fallback for print / break / continue / exceptions
    return {
      title: `Step ${n}: Execute line ${step.line}`,
      calculationCard: null,
      whatItMeans:
        step.eventType === "PRINT"
          ? `Python displays \`"${op.output}"\` as output.`
          : step.eventType === "EXCEPTION"
          ? `Python stopped with an error: \`${op.message}\`.`
          : `Python runs \`${step.codeText}\`.`,
      variableValuesNow: relevantVarsNow,
      whatHappensNext: nextSentence,
      finalBanner: null
    };
  }

  formatRelevantVariablesNow(step) {
    const vars = step.variables || [];
    // Filter out large `nums` list from the inline text summary so it focuses on `c`, `ans`, `i`, etc.
    const compact = vars.filter((v) => v.name !== "nums");
    if (compact.length === 0) {
      if (vars.length > 0) {
        return vars.map((v) => `${v.name} = ${v.current}`).join(", ");
      }
      return "No variables created yet";
    }
    const parts = compact.map((v) => `${v.name} = ${v.current}`);
    if (step.loop && step.loop.indexedElementInfo) {
      const el = step.loop.indexedElementInfo;
      parts.push(`${el.arrayName}[${el.indexVal}] = ${el.elementVal}`);
    }
    return parts.join("   •   ");
  }

  buildFriendlyWhatNext(step, nextStep) {
    if (!nextStep) {
      return "We have reached the end of the program!";
    }
    const nextCode = nextStep.codeText || "";
    if (nextStep.eventType === "METHOD_DEF" || nextStep.eventType === "FUNC_DEF") {
      return `Python moves to Line ${nextStep.line} to register the function \`${nextStep.operationDetail.funcName}\`.`;
    }
    if (nextStep.eventType === "FUNC_CALL") {
      return `Python calls the function with our input list and enters the function body.`;
    }
    if (nextCode === "c = 0" && step.eventType === "FUNC_CALL") {
      return `Python moves inside the function to Line ${nextStep.line} and creates the variable \`c = 0\`.`;
    }
    if (nextCode.startsWith("ans =")) {
      return nextCode === "ans = nums[0]"
        ? `Python moves to Line ${nextStep.line} and creates the variable \`ans\` using the first number in the list.`
        : `Because \`c >= ans\` was True, Python moves into the \`if\` block on Line ${nextStep.line} to update \`ans = c\`.`;
    }
    if (nextStep.eventType === "LOOP_ITER") {
      const nextOp = nextStep.operationDetail || {};
      return nextOp.iteration === 1
        ? `Python moves to Line ${nextStep.line} to start the loop with the first number in the list (\`i = 0\`).`
        : `Python loops back up to Line ${nextStep.line} to pick the next number in the list (\`i = ${nextOp.iterVal}\`).`;
    }
    if (nextStep.eventType === "LOOP_END") {
      return `Python checks the loop header on Line ${nextStep.line}, sees there are no numbers left, and finishes the loop.`;
    }
    if (nextCode.startsWith("c +=")) {
      return `Python moves into the loop body on Line ${nextStep.line} and adds the current number \`nums[i]\` to \`c\`.`;
    }
    if (nextCode.startsWith("if c >= ans")) {
      return `Python moves to Line ${nextStep.line} to check if our new sum \`c\` is bigger than or equal to \`ans\`.`;
    }
    if (nextCode.startsWith("if c < 0")) {
      return `Python moves to Line ${nextStep.line} to check if \`c\` became a negative number.`;
    }
    if (nextCode === "c = 0") {
      return `Because \`c < 0\` was True, Python moves to Line ${nextStep.line} and resets \`c\` back to \`0\`.`;
    }
    if (nextStep.eventType === "RETURN") {
      return `The loop is done, so Python moves to Line ${nextStep.line} (\`return ans\`) to give back the final answer!`;
    }
    return `Python moves to Line ${nextStep.line} and runs \`${nextCode}\`.`;
  }

  // Keep technical & 7-part explanation builder for the optional Advanced View
  buildStepExplanation(step, prevStep, nextStep) {
    const lesson = step.teacherLesson || this.buildTeacherLesson(step, prevStep, nextStep, null);
    const code = step.codeText || "";
    const cond = step.condition;
    const beforeVars = step.beforeVars || {};

    const beforeKeys = Object.keys(beforeVars);
    const variablesBefore =
      beforeKeys.length === 0
        ? "No local variables existed before this step."
        : beforeKeys.map((k) => `\`${k} = ${beforeVars[k]}\``).join(", ");

    let whyCondition = "Not a condition line.";
    if (cond) {
      whyCondition = `\`${cond.leftVal} ${cond.operator} ${cond.rightVal}\` evaluated to **${cond.result ? "True" : "False"}**.`;
    }

    return {
      whatBeginner: lesson.whatItMeans,
      whatTechnical: `Event \`${step.eventType}\` at Line ${step.line} in \`${step.functionName}\`: ${step.changedSummary}.`,
      symbolsMeaning: this.explainSymbolsInLine(code),
      whyExecuting: prevStep
        ? `Moved from Line ${prevStep.line} to Line ${step.line}.`
        : `First statement in the program.`,
      variablesBefore,
      whatChangesAfter: step.changedSummary || "No variable changes.",
      whyCondition,
      whatNext: lesson.whatHappensNext
    };
  }

  explainSymbolsInLine(codeText) {
    const matches = [];
    for (const item of PYTHON_SYMBOLS_LIBRARY) {
      if (codeText.includes(item.token)) {
        matches.push(`• \`${item.label}\`: ${item.desc}`);
      }
    }
    return matches.length ? matches.slice(0, 3).join("<br>") : "• Standard Python statement.";
  }

  buildPracticeChallenge(step, nextStep) {
    if (!nextStep) return null;
    if (nextStep.eventType === "CONDITION" && nextStep.condition) {
      const c = nextStep.condition;
      return {
        prompt: `Quick Check: On the next line (\`${nextStep.codeText}\`), will \`${c.expr}\` be True or False?`,
        options: [
          { label: `True (${c.leftVal} ${c.operator} ${c.rightVal})`, correct: c.result === true },
          { label: `False (${c.leftVal} ${c.operator} ${c.rightVal})`, correct: c.result === false }
        ],
        explanation: `With \`${c.leftExpr} = ${c.leftVal}\` and \`${c.rightExpr} = ${c.rightVal}\`, the answer is **${c.result ? "True" : "False"}**.`
      };
    }
    return null;
  }

  buildExecutionSummary(traceResult) {
    if (!traceResult.ok || !traceResult.steps.length) {
      return `Stopped: ${traceResult.errorMessage || "Check syntax or input."}`;
    }
    if (traceResult.finalResult !== null) {
      return `Final Answer: **${traceResult.finalResult}** (${traceResult.steps.length} steps)`;
    }
    return `Completed in ${traceResult.steps.length} steps.`;
  }

  answerBuiltInQuestion(questionId, step, traceResult) {
    if (!step) return "Click Next Step to start exploring.";
    const lesson = step.teacherLesson;
    switch (questionId) {
      case "what_line_does":
        return lesson.whatItMeans;
      case "why_var_changed":
        return step.changedSummary;
      case "what_happens_next":
        return lesson.whatHappensNext;
      case "what_symbol_means":
        return step.explanations.symbolsMeaning;
      default:
        return lesson.whatItMeans;
    }
  }
}

window.RuleBasedExplainer = RuleBasedExplainer;

:root {
  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --bg-subtle: #f1f5f9;
  --bg-code: #f8fafc;

  --border-light: #e2e8f0;
  --border-medium: #cbd5e1;

  --text-main: #0f172a;
  --text-secondary: #475569;
  --text-muted: #94a3b8;

  --primary-blue: #2563eb;
  --primary-blue-hover: #1d4ed8;
  --primary-blue-soft: #eff6ff;
  --primary-blue-border: #93c5fd;

  --changed-green-bg: #ecfdf5;
  --changed-green-border: #6ee7b7;
  --changed-green-text: #065f46;

  --current-line-bg: #dbeafe;
  --current-line-border: #2563eb;

  /* Light-theme syntax colors */
  --syn-kw: #7c3aed;
  --syn-bi: #0284c7;
  --syn-str: #059669;
  --syn-num: #d97706;
  --syn-com: #94a3b8;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', Consolas, monospace;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-page);
  color: var(--text-main);
  font-family: var(--font-sans);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-size: 15px;
  line-height: 1.6;
}

/* =========================================================
   TOP NAVIGATION BAR
   ========================================================= */
.top-bar {
  height: 68px;
  background-color: var(--bg-card);
  border-bottom: 1px solid var(--border-light);
  padding: 0 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  position: sticky;
  top: 0;
  z-index: 20;
}

.brand-area {
  display: flex;
  align-items: center;
  gap: 14px;
}

.teacher-badge {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
}

.step-progress-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--primary-blue);
  background: var(--primary-blue-soft);
  border: 1px solid var(--primary-blue-border);
  padding: 4px 12px;
  border-radius: 99px;
}

.nav-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.btn-nav {
  font-family: var(--font-sans);
  font-size: 14.5px;
  font-weight: 600;
  padding: 9px 18px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-medium);
  background: var(--bg-card);
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-nav:hover:not(:disabled) {
  background: var(--bg-subtle);
  border-color: #94a3b8;
}

.btn-nav:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn-next-prominent {
  background: var(--primary-blue);
  border-color: var(--primary-blue);
  color: #ffffff;
  padding: 10px 26px;
  font-size: 15px;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.25);
}

.btn-next-prominent:hover:not(:disabled) {
  background: var(--primary-blue-hover);
  border-color: var(--primary-blue-hover);
}

.secondary-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-subtle {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 500;
  padding: 7px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-light);
  background: var(--bg-subtle);
  color: var(--text-secondary);
  cursor: pointer;
}

.btn-subtle:hover,
.btn-subtle.active {
  background: #e2e8f0;
  color: var(--text-main);
}

.btn-small-primary {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 600;
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  border: none;
  background: var(--primary-blue);
  color: #ffffff;
  cursor: pointer;
}

/* =========================================================
   OPTIONAL CUSTOM INPUT / CODE DRAWER
   ========================================================= */
.custom-drawer {
  background: var(--bg-subtle);
  border-bottom: 1px solid var(--border-light);
  padding: 10px 28px;
}

.custom-drawer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.drawer-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.drawer-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
}

.drawer-select,
.drawer-input {
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-medium);
  background: var(--bg-card);
  color: var(--text-main);
  font-size: 13px;
  font-family: var(--font-mono);
}

.drawer-input {
  width: 280px;
}

.chip-input {
  font-size: 12px;
  font-family: var(--font-mono);
  padding: 5px 10px;
  border-radius: 6px;
  border: 1px solid var(--border-medium);
  background: var(--bg-card);
  color: var(--text-secondary);
  cursor: pointer;
}

.chip-input:hover {
  border-color: var(--primary-blue);
  color: var(--primary-blue);
}

.validation-banner {
  margin-top: 8px;
  padding: 8px 12px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
  border-radius: var(--radius-sm);
  font-size: 13px;
}

/* =========================================================
   SIMPLE OVERVIEW BANNER
   ========================================================= */
.overview-strip {
  background: var(--primary-blue-soft);
  border-bottom: 1px solid #dbeafe;
  padding: 10px 28px;
  font-size: 15px;
  color: #1e3a8a;
  display: flex;
  align-items: center;
  gap: 8px;
}

.overview-label {
  font-weight: 700;
  text-transform: uppercase;
  font-size: 12px;
  background: #2563eb;
  color: #ffffff;
  padding: 2px 8px;
  border-radius: 4px;
}

/* =========================================================
   MAIN 3-AREA WORKSPACE
   ========================================================= */
.three-area-workspace {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1.45fr 0.9fr;
  gap: 20px;
  padding: 22px 28px;
  max-width: 1560px;
  width: 100%;
  margin: 0 auto;
  align-items: start;
}

.area-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 22px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.03);
}

.area-heading {
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  margin-bottom: 14px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-light);
}

/* =========================================================
   AREA 1: YOUR CODE (LEFT)
   ========================================================= */
.code-view {
  font-family: var(--font-mono);
  font-size: 14px;
  line-height: 1.85;
  background: var(--bg-code);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 12px 0;
  overflow-x: auto;
}

.code-row {
  display: flex;
  align-items: center;
  padding: 2px 14px 2px 0;
  border-left: 4px solid transparent;
  cursor: pointer;
  transition: opacity 0.15s ease, background-color 0.15s ease;
}

/* Keep remaining code visible but slightly less prominent */
.code-row.is-dimmed {
  opacity: 0.58;
}

.code-row.is-dimmed:hover {
  opacity: 0.9;
  background: #f1f5f9;
}

/* Highlight ONLY the current line prominently */
.code-row.is-current-line {
  opacity: 1;
  background-color: var(--current-line-bg);
  border-left-color: var(--current-line-border);
  font-weight: 600;
}

.code-gutter {
  width: 46px;
  text-align: right;
  padding-right: 14px;
  color: var(--text-muted);
  font-size: 12.5px;
  user-select: none;
  flex-shrink: 0;
}

.is-current-line .code-gutter {
  color: var(--primary-blue);
  font-weight: 700;
}

.code-syntax {
  white-space: pre;
  color: var(--text-main);
}

.syn-kw { color: var(--syn-kw); font-weight: 600; }
.syn-bi { color: var(--syn-bi); }
.syn-str { color: var(--syn-str); }
.syn-num { color: var(--syn-num); }
.syn-com { color: var(--syn-com); font-style: italic; }

.live-editor-wrap {
  margin-top: 8px;
}

.code-textarea {
  width: 100%;
  min-height: 340px;
  font-family: var(--font-mono);
  font-size: 14px;
  line-height: 1.7;
  padding: 14px;
  border: 1px solid var(--primary-blue);
  border-radius: var(--radius-md);
  background: var(--bg-card);
  color: var(--text-main);
  outline: none;
}

/* =========================================================
   AREA 2: TEACHING AREA (CENTER — MAIN FOCUS)
   ========================================================= */
.area-teaching {
  border: 2px solid var(--primary-blue-border);
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.06);
}

.teaching-card-inner {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.teach-step-title {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-main);
  line-height: 1.3;
}

.teach-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.teach-label {
  font-size: 13.5px;
  font-weight: 700;
  color: var(--text-secondary);
}

.teach-code-box {
  font-family: var(--font-mono);
  font-size: 16px;
  font-weight: 600;
  background: var(--bg-subtle);
  border-left: 4px solid var(--primary-blue);
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  color: var(--text-main);
}

/* Step Calculation Breakdown Box */
.teach-calc-box {
  background: #f8fafc;
  border: 1px solid var(--border-medium);
  border-radius: var(--radius-md);
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.calc-row {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 15px;
}

.calc-label {
  width: 130px;
  font-weight: 600;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.calc-val {
  font-family: var(--font-mono);
  font-size: 15px;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  padding: 3px 10px;
  border-radius: 6px;
  color: var(--text-main);
}

.calc-highlight {
  background: #eff6ff;
  border-color: #bfdbfe;
  color: #1d4ed8;
  font-weight: 600;
}

.calc-after {
