class PythonExecutionEngine {
  constructor() {
    this.maxSteps = 400;
  }

  validateSupport(sourceCode) {
    if (!sourceCode || !sourceCode.trim()) {
      return {
        ok: false,
        line: 1,
        message: "The code editor is empty. Paste or write a Python program to analyze."
      };
    }

    const lines = sourceCode.replace(/\r\n/g, "\n").split("\n");

    const unsupportedRules = [
      { regex: /^\s*(import|from)\s+/, msg: "`import` statements are not supported in the offline sandbox." },
      { regex: /^\s*async\s+/, msg: "`async` / `await` constructs are not supported." },
      { regex: /\bawait\s+/, msg: "`await` expressions are not supported." },
      { regex: /^\s*with\s+/, msg: "`with` context managers and file I/O are not supported." },
      { regex: /\byield\b/, msg: "Generator `yield` statements are not supported." },
      { regex: /\blambda\b/, msg: "`lambda` expressions are not supported; please use `def`." },
      { regex: /^\s*(try|except|finally)\b/, msg: "`try / except` blocks are not supported." },
      { regex: /\b(open|eval|exec|__import__|input)\s*\(/, msg: "Restricted built-in function (`open`, `eval`, `exec`, `input`) is disabled for security." }
    ];

    let parenDepth = 0;
    let bracketDepth = 0;

    for (let i = 0; i < lines.length; i++) {
      const raw = lines[i];
      const stripped = this.stripInlineComment(raw);
      const trimmed = stripped.trim();
      if (!trimmed) continue;

      for (const rule of unsupportedRules) {
        if (rule.regex.test(trimmed)) {
          return {
            ok: false,
            line: i + 1,
            message: `Unsupported Syntax on Line ${i + 1}: ${rule.msg}`
          };
        }
      }

      if (/^(class|def|if|elif|else|for|while)\b/.test(trimmed) && !trimmed.endsWith(":")) {
        return {
          ok: false,
          line: i + 1,
          message: `SyntaxError on Line ${i + 1}: Block header (\`${trimmed}\`) must end with a colon (\`:\`).`
        };
      }

      for (const ch of trimmed) {
        if (ch === "(") parenDepth++;
        else if (ch === ")") parenDepth--;
        else if (ch === "[") bracketDepth++;
        else if (ch === "]") bracketDepth--;
      }

      if (parenDepth < 0 || bracketDepth < 0) {
        return {
          ok: false,
          line: i + 1,
          message: `SyntaxError on Line ${i + 1}: Unmatched closing parenthesis or bracket.`
        };
      }
    }

    if (parenDepth !== 0 || bracketDepth !== 0) {
      return {
        ok: false,
        line: lines.length,
        message: "SyntaxError: Unclosed parenthesis `(` or bracket `[` in code."
      };
    }

    return { ok: true, line: null, message: null };
  }

  parseInputAssignments(inputCode) {
    const inputVars = {};
    if (!inputCode || !inputCode.trim()) return inputVars;

    // Support multiple comma-separated or newline/semicolon-separated assignments, e.g.:
    // `arr = [1, 2, 3], target = 2` OR `nums = [3, 5, -6, 4]`
    const segments = this.splitTopLevelSegments(inputCode);
    const dummyVars = {};

    for (const seg of segments) {
      const eqIdx = seg.indexOf("=");
      if (eqIdx !== -1) {
        const vName = seg.slice(0, eqIdx).trim();
        const vExpr = seg.slice(eqIdx + 1).trim();
        const val = this.evalExpr(vExpr, dummyVars, {}, {}, [], [], [], [], 1);
        dummyVars[vName] = val;
        inputVars[vName] = val;
      } else {
        // Bare literal like `[1, 2, 3]`
        const val = this.evalExpr(seg, dummyVars, {}, {}, [], [], [], [], 1);
        inputVars["nums"] = val;
      }
    }
    return inputVars;
  }

  splitTopLevelSegments(str) {
    const res = [];
    let cur = "";
    let depth = 0;
    let inSingle = false;
    let inDouble = false;

    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (!inSingle && !inDouble) {
        if (ch === "(" || ch === "[" || ch === "{") depth++;
        else if (ch === ")" || ch === "]" || ch === "}") depth--;
        else if ((ch === ";" || ch === "\n" || (ch === "," && depth === 0)) && cur.includes("=")) {
          res.push(cur.trim());
          cur = "";
          continue;
        }
      }
      cur += ch;
    }
    if (cur.trim()) res.push(cur.trim());
    return res;
  }

  trace(sourceCode, inputCode = "") {
    const validation = this.validateSupport(sourceCode);
    const rawLines = sourceCode.replace(/\r\n/g, "\n").split("\n");

    if (!validation.ok) {
      return {
        ok: false,
        errorType: "UNSUPPORTED_OR_SYNTAX",
        errorMessage: validation.message,
        errorLine: validation.line,
        rawLines,
        steps: [],
        cfg: { nodes: [], edges: [] }
      };
    }

    let inputVars = {};
    try {
      inputVars = this.parseInputAssignments(inputCode);
    } catch (err) {
      return {
        ok: false,
        errorType: "INVALID_INPUT",
        errorMessage: `Invalid Input List: ${err.message || err}`,
        errorLine: 1,
        rawLines,
        steps: [],
        cfg: { nodes: [], edges: [] }
      };
    }

    const statements = this.parseProgram(rawLines);
    const cfg = this.buildControlFlowGraph(statements);

    const steps = [];
    const stdout = [];
    const functions = {};
    const classes = {};
    const callStack = [
      {
        frameName: "Global Scope",
        vars: {},
        prevVars: {}
      }
    ];
    const loopStack = [];

    Object.entries(inputVars).forEach(([k, v]) => {
      callStack[0].vars[k] = Array.isArray(v) ? [...v] : v;
      callStack[0].prevVars[k] = Array.isArray(v) ? [...v] : v;
    });

    let finalReturnVal = null;

    try {
      this.executeSuite(statements, callStack, functions, classes, steps, stdout, loopStack);

      // Auto-invoke if the user only defined a class method OR a top-level function without calling it!
      const fnNames = Object.keys(functions);
      const onlyDefinitionsRan = steps.every(
        (s) => s.eventType === "CLASS_DEF" || s.eventType === "METHOD_DEF" || s.eventType === "FUNC_DEF"
      );

      if (onlyDefinitionsRan && fnNames.length > 0) {
        const fnNode = functions[fnNames[0]];
        const argVals = this.resolveFunctionArguments(fnNode, inputVars);
        const callRes = this.invokeFunctionNode(
          fnNode,
          argVals,
          fnNode.params,
          callStack,
          functions,
          classes,
          steps,
          stdout,
          loopStack,
          fnNode.line
        );
        if (callRes && callRes.returned) {
          finalReturnVal = callRes.value;
        }
      }
    } catch (err) {
      const errLine = err.line || 1;
      const errMsg = err.message || String(err);
      steps.push({
        stepIndex: steps.length + 1,
        line: errLine,
        nextLine: null,
        codeText: rawLines[errLine - 1] ? rawLines[errLine - 1].trim() : "",
        eventType: "EXCEPTION",
        functionName: callStack[callStack.length - 1].frameName,
        beforeVars: this.cloneVarsMap(callStack[callStack.length - 1].vars),
        variables: this.buildInspectorRows(callStack[callStack.length - 1].vars, null),
        changedVars: [],
        changedSummary: `Exception raised: ${errMsg}`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "exception", message: errMsg },
        returnValue: null,
        stdout: [...stdout]
      });

      this.finalizeNextLines(steps);
      return {
        ok: false,
        errorType: "RUNTIME_EXCEPTION",
        errorMessage: errMsg,
        errorLine: errLine,
        rawLines,
        steps,
        cfg,
        finalResult: null
      };
    }

    this.finalizeNextLines(steps);

    return {
      ok: true,
      errorType: null,
      errorMessage: null,
      errorLine: null,
      rawLines,
      steps,
      cfg,
      finalResult: finalReturnVal !== null ? this.formatVal(finalReturnVal) : null
    };
  }

  resolveFunctionArguments(fnNode, inputVars) {
    const inputValues = Object.values(inputVars);
    const firstArray = inputValues.find((v) => Array.isArray(v)) || [-2, 1, -3, 4, -1, 2, 1, -5, 4];

    return fnNode.params.map((paramName, idx) => {
      if (paramName in inputVars) {
        return inputVars[paramName];
      }
      // If function expects `arr` (like binary_search(arr, target)) and user input has `nums = [...]`
      if (["arr", "nums", "items", "numbers", "a"].includes(paramName)) {
        // If function is binary_search, sort a copy so binary search works intuitively on unsorted input!
        if (fnNode.funcName.toLowerCase().includes("binary")) {
          return [...firstArray].sort((a, b) => a - b);
        }
        return [...firstArray];
      }
      if (["target", "val", "key", "x", "k"].includes(paramName)) {
        if ("target" in inputVars) return inputVars["target"];
        if (firstArray.length > 0) {
          const sorted = fnNode.funcName.toLowerCase().includes("binary")
            ? [...firstArray].sort((a, b) => a - b)
            : firstArray;
          return sorted[Math.floor(sorted.length / 2)];
        }
        return 4;
      }
      return inputValues[idx] !== undefined ? inputValues[idx] : 0;
    });
  }

  finalizeNextLines(steps) {
    for (let i = 0; i < steps.length; i++) {
      steps[i].nextLine = i + 1 < steps.length ? steps[i + 1].line : null;
    }
  }

  stripInlineComment(line) {
    let inSingle = false;
    let inDouble = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (ch === "#" && !inSingle && !inDouble) {
        return line.slice(0, i);
      }
    }
    return line;
  }

  parseProgram(rawLines) {
    const items = [];
    for (let i = 0; i < rawLines.length; i++) {
      const stripped = this.stripInlineComment(rawLines[i]);
      const trimmed = stripped.trim();
      if (!trimmed) continue;
      const indent = rawLines[i].match(/^\s*/)[0].length;
      items.push({ line: i + 1, indent, text: trimmed, raw: rawLines[i] });
    }
    return this.buildASTBlock(items, 0, items.length > 0 ? items[0].indent : 0).nodes;
  }

  buildASTBlock(items, startIdx, baseIndent) {
    const nodes = [];
    let i = startIdx;

    while (i < items.length) {
      const item = items[i];
      if (item.indent < baseIndent) break;

      if (item.text.startsWith("class ") && item.text.endsWith(":")) {
        const className = item.text.slice(6, -1).split("(")[0].trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "CLASS",
          line: item.line,
          text: item.text,
          className,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("def ") && item.text.endsWith(":")) {
        const match = item.text.match(/^def\s+([a-zA-Z_]\w*)\s*\((.*)\)\s*(?:->\s*[^:]+)?\s*:$/);
        const funcName = match ? match[1] : "func";
        const rawParams = match && match[2].trim() ? this.splitTopLevelArgs(match[2]) : [];
        const params = rawParams
          .map((p) => p.split(":")[0].split("=")[0].trim())
          .filter((p) => p && p !== "self");
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "DEF",
          line: item.line,
          text: item.text,
          funcName,
          params,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("if ") && item.text.endsWith(":")) {
        const branches = [];
        const cond = item.text.slice(3, -1).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        branches.push({
          type: "if",
          line: item.line,
          text: item.text,
          condition: cond,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;

        while (i < items.length && items[i].indent === item.indent) {
          const cur = items[i];
          if (cur.text.startsWith("elif ") && cur.text.endsWith(":")) {
            const elifCond = cur.text.slice(5, -1).trim();
            const elifBody = this.parseChildSuite(items, i + 1, cur.indent);
            branches.push({
              type: "elif",
              line: cur.line,
              text: cur.text,
              condition: elifCond,
              body: elifBody.nodes
            });
            i = elifBody.nextIdx;
          } else if (cur.text === "else:") {
            const elseBody = this.parseChildSuite(items, i + 1, cur.indent);
            branches.push({
              type: "else",
              line: cur.line,
              text: cur.text,
              condition: null,
              body: elseBody.nodes
            });
            i = elseBody.nextIdx;
            break;
          } else {
            break;
          }
        }
        nodes.push({
          kind: "IF_CHAIN",
          line: item.line,
          text: item.text,
          branches
        });
      } else if (item.text.startsWith("for ") && item.text.endsWith(":")) {
        const header = item.text.slice(4, -1).trim();
        const inIdx = header.indexOf(" in ");
        const iterVar = header.slice(0, inIdx).trim();
        const iterExpr = header.slice(inIdx + 4).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "FOR",
          line: item.line,
          text: item.text,
          iterVar,
          iterExpr,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("while ") && item.text.endsWith(":")) {
        const condition = item.text.slice(6, -1).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "WHILE",
          line: item.line,
          text: item.text,
          condition,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else {
        nodes.push({
          kind: "STMT",
          line: item.line,
          text: item.text
        });
        i++;
      }
    }

    return { nodes, nextIdx: i };
  }

  parseChildSuite(items, nextIdx, parentIndent) {
    if (nextIdx >= items.length || items[nextIdx].indent <= parentIndent) {
      return { nodes: [], nextIdx };
    }
    return this.buildASTBlock(items, nextIdx, items[nextIdx].indent);
  }

  executeSuite(nodes, callStack, functions, classes, steps, stdout, loopStack) {
    for (const node of nodes) {
      if (steps.length >= this.maxSteps) {
        throw {
          line: node.line,
          message: `TimeoutError: Execution exceeded ${this.maxSteps} steps (possible infinite loop).`
        };
      }
      const res = this.executeNode(node, callStack, functions, classes, steps, stdout, loopStack);
      if (res && (res.returned || res.broke || res.continued)) {
        return res;
      }
    }
    return null;
  }

  executeNode(node, callStack, functions, classes, steps, stdout, loopStack) {
    const activeFrame = callStack[callStack.length - 1];

    if (node.kind === "CLASS") {
      classes[node.className] = { name: node.className, methods: {} };
      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: node.text,
        eventType: "CLASS_DEF",
        functionName: activeFrame.frameName,
        beforeVars: this.cloneVarsMap(activeFrame.vars),
        variables: this.buildInspectorRows(activeFrame.vars, null),
        changedVars: [],
        changedSummary: `Defined class '${node.className}'`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "class_def", className: node.className },
        returnValue: null,
        stdout: [...stdout]
      });

      for (const child of node.body) {
        if (child.kind === "DEF") {
          classes[node.className].methods[child.funcName] = child;
          functions[child.funcName] = child;
          steps.push({
            stepIndex: steps.length + 1,
            line: child.line,
            codeText: child.text,
            eventType: "METHOD_DEF",
            functionName: `class ${node.className}`,
            beforeVars: this.cloneVarsMap(activeFrame.vars),
            variables: this.buildInspectorRows(activeFrame.vars, null),
            changedVars: [],
            changedSummary: `Defined method '${child.funcName}(${child.params.join(", ")})'`,
            condition: null,
            loop: null,
            operationDetail: {
              kind: "method_def",
              className: node.className,
              funcName: child.funcName,
              params: child.params
            },
            returnValue: null,
            stdout: [...stdout]
          });
        }
      }
      return null;
    }

    if (node.kind === "DEF") {
      functions[node.funcName] = node;
      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: node.text,
        eventType: "FUNC_DEF",
        functionName: activeFrame.frameName,
        beforeVars: this.cloneVarsMap(activeFrame.vars),
        variables: this.buildInspectorRows(activeFrame.vars, null),
        changedVars: [],
        changedSummary: `Defined function '${node.funcName}(${node.params.join(", ")})'`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "func_def", funcName: node.funcName, params: node.params },
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    if (node.kind === "IF_CHAIN") {
      for (const branch of node.branches) {
        if (branch.type === "else") {
          steps.push({
            stepIndex: steps.length + 1,
            line: branch.line,
            codeText: branch.text,
            eventType: "ELSE_BRANCH",
            functionName: activeFrame.frameName,
            beforeVars: this.cloneVarsMap(activeFrame.vars),
            variables: this.buildInspectorRows(activeFrame.vars, null),
            changedVars: [],
            changedSummary: "Previous conditions were False → entering else block",
            condition: {
              expr: "else",
              leftExpr: "Previous conditions",
              leftVal: "False",
              operator: "->",
              rightExpr: "else",
              rightVal: "True",
              result: true
            },
            loop: this.getCurrentLoopSnapshot(loopStack),
            operationDetail: { kind: "else_branch" },
            returnValue: null,
            stdout: [...stdout]
          });
          return this.executeSuite(branch.body, callStack, functions, classes, steps, stdout, loopStack);
        } else {
          const condInfo = this.evaluateCondition(
            branch.condition,
            activeFrame.vars,
            functions,
            classes,
            callStack,
            steps,
            stdout,
            loopStack,
            branch.line
          );
          steps.push({
            stepIndex: steps.length + 1,
            line: branch.line,
            codeText: branch.text,
            eventType: "CONDITION",
            functionName: activeFrame.frameName,
            beforeVars: this.cloneVarsMap(activeFrame.vars),
            variables: this.buildInspectorRows(activeFrame.vars, null),
            changedVars: [],
            changedSummary: "No variable values changed (Condition check)",
            condition: condInfo,
            loop: this.getCurrentLoopSnapshot(loopStack),
            operationDetail: { kind: "condition", ...condInfo },
            returnValue: null,
            stdout: [...stdout]
          });
          if (condInfo.result) {
            return this.executeSuite(branch.body, callStack, functions, classes, steps, stdout, loopStack);
          }
        }
      }
      return null;
    }

    if (node.kind === "FOR") {
      const iterable = this.evalExpr(
        node.iterExpr,
        activeFrame.vars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        node.line
      );
      const listItems = Array.isArray(iterable) ? iterable : [];

      loopStack.push({
        loopType: "for",
        iterVar: node.iterVar,
        iterExpr: node.iterExpr,
        currentIteration: 0,
        totalIterations: listItems.length,
        currentItemValue: null,
        headerLine: node.line
      });

      for (let idx = 0; idx < listItems.length; idx++) {
        if (steps.length >= this.maxSteps) {
          throw {
            line: node.line,
            message: `TimeoutError: Execution exceeded ${this.maxSteps} steps (possible infinite loop).`
          };
        }

        const beforeMap = this.cloneVarsMap(activeFrame.vars);
        const itemVal = listItems[idx];
        const prevVal = activeFrame.vars[node.iterVar];
        const isCreated = !(node.iterVar in activeFrame.vars);

        activeFrame.prevVars[node.iterVar] = prevVal;
        activeFrame.vars[node.iterVar] = itemVal;

        const topLoop = loopStack[loopStack.length - 1];
        topLoop.currentIteration = idx + 1;
        topLoop.currentItemValue = this.formatVal(itemVal);
        topLoop.currentIndex = idx;

        let indexedElementInfo = null;
        const arrCandidate = activeFrame.vars["nums"] || activeFrame.vars["arr"];
        const arrName = activeFrame.vars["nums"] ? "nums" : activeFrame.vars["arr"] ? "arr" : null;
        if (
          typeof itemVal === "number" &&
          Array.isArray(arrCandidate) &&
          itemVal >= 0 &&
          itemVal < arrCandidate.length
        ) {
          indexedElementInfo = {
            arrayName: arrName,
            indexVar: node.iterVar,
            indexVal: itemVal,
            elementVal: this.formatVal(arrCandidate[itemVal])
          };
        }

        const changeObj = {
          name: node.iterVar,
          status: isCreated ? "created" : "updated",
          prevValue: prevVal
        };

        steps.push({
          stepIndex: steps.length + 1,
          line: node.line,
          codeText: node.text,
          eventType: "LOOP_ITER",
          functionName: activeFrame.frameName,
          beforeVars: beforeMap,
          variables: this.buildInspectorRows(activeFrame.vars, changeObj),
          changedVars: [changeObj],
          changedSummary: isCreated
            ? `${node.iterVar}: (created) → ${this.formatVal(itemVal)}`
            : `${node.iterVar}: ${this.formatVal(prevVal)} → ${this.formatVal(itemVal)}`,
          condition: {
            expr: `${node.iterVar} in ${node.iterExpr}`,
            leftExpr: `Iteration ${idx + 1} of ${listItems.length}`,
            leftVal: `${node.iterVar} = ${this.formatVal(itemVal)}`,
            operator: "in",
            rightExpr: node.iterExpr,
            rightVal: `len=${listItems.length}`,
            result: true
          },
          loop: {
            ...this.getCurrentLoopSnapshot(loopStack),
            indexedElementInfo
          },
          operationDetail: {
            kind: "for_iter",
            iterVar: node.iterVar,
            iterVal: this.formatVal(itemVal),
            iteration: idx + 1,
            total: listItems.length,
            indexedElementInfo
          },
          returnValue: null,
          stdout: [...stdout]
        });

        const bodyRes = this.executeSuite(
          node.body,
          callStack,
          functions,
          classes,
          steps,
          stdout,
          loopStack
        );
        if (bodyRes) {
          if (bodyRes.returned) {
            loopStack.pop();
            return bodyRes;
          }
          if (bodyRes.broke) {
            loopStack.pop();
            return null;
          }
          if (bodyRes.continued) {
            continue;
          }
        }
      }

      loopStack.pop();

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: node.text,
        eventType: "LOOP_END",
        functionName: activeFrame.frameName,
        beforeVars: this.cloneVarsMap(activeFrame.vars),
        variables: this.buildInspectorRows(activeFrame.vars, null),
        changedVars: [],
        changedSummary: `Loop finished all ${listItems.length} iterations`,
        condition: {
          expr: `${node.iterVar} in ${node.iterExpr}`,
          leftExpr: "Remaining items",
          leftVal: "0",
          operator: "==",
          rightExpr: "Exhausted",
          rightVal: "StopIteration",
          result: false
        },
        loop: {
          loopType: "for",
          iterVar: node.iterVar,
          iterExpr: node.iterExpr,
          currentIteration: listItems.length,
          totalIterations: listItems.length,
          isFinished: true
        },
        operationDetail: {
          kind: "for_end",
          iterVar: node.iterVar,
          total: listItems.length
        },
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    if (node.kind === "WHILE") {
      let iter = 0;
      loopStack.push({
        loopType: "while",
        condition: node.condition,
        currentIteration: 0,
        totalIterations: null,
        headerLine: node.line
      });

      while (true) {
        if (steps.length >= this.maxSteps) {
          throw {
            line: node.line,
            message: `TimeoutError: Execution exceeded ${this.maxSteps} steps (possible infinite loop).`
          };
        }
        iter++;
        loopStack[loopStack.length - 1].currentIteration = iter;

        const condInfo = this.evaluateCondition(
          node.condition,
          activeFrame.vars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          node.line
        );

        steps.push({
          stepIndex: steps.length + 1,
          line: node.line,
          codeText: node.text,
          eventType: condInfo.result ? "LOOP_ITER" : "LOOP_END",
          functionName: activeFrame.frameName,
          beforeVars: this.cloneVarsMap(activeFrame.vars),
          variables: this.buildInspectorRows(activeFrame.vars, null),
          changedVars: [],
          changedSummary: condInfo.result
            ? `While condition True (Pass #${iter})`
            : `While condition False (Loop exits)`,
          condition: condInfo,
          loop: this.getCurrentLoopSnapshot(loopStack),
          operationDetail: {
            kind: "while_check",
            iteration: iter,
            ...condInfo
          },
          returnValue: null,
          stdout: [...stdout]
        });

        if (!condInfo.result) break;

        const bodyRes = this.executeSuite(
          node.body,
          callStack,
          functions,
          classes,
          steps,
          stdout,
          loopStack
        );
        if (bodyRes) {
          if (bodyRes.returned) {
            loopStack.pop();
            return bodyRes;
          }
          if (bodyRes.broke) {
            loopStack.pop();
            return null;
          }
          if (bodyRes.continued) {
            continue;
          }
        }
      }

      loopStack.pop();
      return null;
    }

    if (node.kind === "STMT") {
      return this.executeStatement(
        node,
        callStack,
        functions,
        classes,
        steps,
        stdout,
        loopStack
      );
    }

    return null;
  }

  executeStatement(node, callStack, functions, classes, steps, stdout, loopStack) {
    const activeFrame = callStack[callStack.length - 1];
    const text = node.text;
    const beforeMap = this.cloneVarsMap(activeFrame.vars);

    // 1. break
    if (text === "break") {
      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "BREAK",
        functionName: activeFrame.frameName,
        beforeVars: beforeMap,
        variables: this.buildInspectorRows(activeFrame.vars, null),
        changedVars: [],
        changedSummary: "Breaking out of current loop immediately",
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "break" },
        returnValue: null,
        stdout: [...stdout]
      });
      return { broke: true };
    }

    // 2. continue
    if (text === "continue") {
      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "CONTINUE",
        functionName: activeFrame.frameName,
        beforeVars: beforeMap,
        variables: this.buildInspectorRows(activeFrame.vars, null),
        changedVars: [],
        changedSummary: "Skipping rest of current loop pass (continue)",
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "continue" },
        returnValue: null,
        stdout: [...stdout]
      });
      return { continued: true };
    }

    // 3. return
    if (text === "return" || text.startsWith("return ")) {
      const expr = text === "return" ? "None" : text.slice(7).trim();
      const retVal =
        expr === "None"
          ? null
          : this.evalExpr(
              expr,
              activeFrame.vars,
              functions,
              classes,
              callStack,
              steps,
              stdout,
              loopStack,
              node.line
            );
      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "RETURN",
        functionName: activeFrame.frameName,
        beforeVars: beforeMap,
        variables: this.buildInspectorRows(activeFrame.vars, null),
        changedVars: [],
        changedSummary: `Returns ${this.formatVal(retVal)} from ${activeFrame.frameName}`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: {
          kind: "return",
          expr,
          returnVal: this.formatVal(retVal)
        },
        returnValue: this.formatVal(retVal),
        stdout: [...stdout]
      });
      return { returned: true, value: retVal };
    }

    // 4. print(...)
    if (text.startsWith("print(") && text.endsWith(")")) {
      const inner = text.slice(6, -1).trim();
      const args = this.splitTopLevelArgs(inner);
      const vals = args.map((a) =>
        this.evalExpr(
          a,
          activeFrame.vars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          node.line
        )
      );
      const outLine = vals
        .map((v) => (typeof v === "string" ? v : this.formatVal(v)))
        .join(" ");
      stdout.push(outLine);

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "PRINT",
        functionName: activeFrame.frameName,
        beforeVars: beforeMap,
        variables: this.buildInspectorRows(activeFrame.vars, null),
        changedVars: [],
        changedSummary: `Printed "${outLine}"`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "print", output: outLine },
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    // 5. Augmented assignment (+=, -=, *=, //=)
    const augMatch = text.match(/^([a-zA-Z_]\w*)\s*(\+=|-=|\*=|\/\/=)\s*(.+)$/);
    if (augMatch) {
      const varName = augMatch[1];
      const augOp = augMatch[2];
      const baseOp = augOp.slice(0, -1);
      const rhsExpr = augMatch[3].trim();

      if (!(varName in activeFrame.vars)) {
        throw {
          line: node.line,
          message: `NameError: name '${varName}' is not defined before '${augOp}'`
        };
      }

      const prevVal = activeFrame.vars[varName];
      const rhsVal = this.evalExpr(
        rhsExpr,
        activeFrame.vars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        node.line
      );

      let newVal;
      if (baseOp === "+") newVal = prevVal + rhsVal;
      else if (baseOp === "-") newVal = prevVal - rhsVal;
      else if (baseOp === "*") newVal = prevVal * rhsVal;
      else if (baseOp === "//") newVal = Math.floor(prevVal / rhsVal);

      activeFrame.prevVars[varName] = prevVal;
      activeFrame.vars[varName] = newVal;

      const changeObj = {
        name: varName,
        status: "updated",
        prevValue: prevVal
      };

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "AUG_ASSIGN",
        functionName: activeFrame.frameName,
        beforeVars: beforeMap,
        variables: this.buildInspectorRows(activeFrame.vars, changeObj),
        changedVars: [changeObj],
        changedSummary: `${varName}: ${this.formatVal(prevVal)} → ${this.formatVal(newVal)}`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: {
          kind: "aug_assign",
          target: varName,
          augOp,
          baseOp,
          beforeVal: this.formatVal(prevVal),
          rhsExpr,
          rhsVal: this.formatVal(rhsVal),
          afterVal: this.formatVal(newVal)
        },
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    // 6. Tuple / Multiple assignment (`left, right = 0, len(arr) - 1` or `a, b = b, a`)
    const eqPos = this.findSingleAssignmentEquals(text);
    if (eqPos !== -1) {
      const lhsRaw = text.slice(0, eqPos).trim();
      const rhsRaw = text.slice(eqPos + 1).trim();
      const lhsTargets = this.splitTopLevelArgs(lhsRaw);
      const rhsExprs = this.splitTopLevelArgs(rhsRaw);

      if (lhsTargets.length > 1) {
        const evaluatedRhs = rhsExprs.map((e) =>
          this.evalExpr(
            e,
            activeFrame.vars,
            functions,
            classes,
            callStack,
            steps,
            stdout,
            loopStack,
            node.line
          )
        );
        const valuesToAssign =
          evaluatedRhs.length === 1 && Array.isArray(evaluatedRhs[0])
            ? evaluatedRhs[0]
            : evaluatedRhs;

        const changedVarsList = [];
        const summaryParts = [];

        lhsTargets.forEach((targetStr, idx) => {
          const cleanTarget = targetStr.split(":")[0].trim();
          const newVal = valuesToAssign[idx];
          const isCreated = !(cleanTarget in activeFrame.vars);
          const prevVal = activeFrame.vars[cleanTarget];
          activeFrame.prevVars[cleanTarget] = prevVal;
          activeFrame.vars[cleanTarget] = newVal;

          changedVarsList.push({
            name: cleanTarget,
            status: isCreated ? "created" : "updated",
            prevValue: prevVal
          });
          summaryParts.push(`${cleanTarget} = ${this.formatVal(newVal)}`);
        });

        steps.push({
          stepIndex: steps.length + 1,
          line: node.line,
          codeText: text,
          eventType: "ASSIGN",
          functionName: activeFrame.frameName,
          beforeVars: beforeMap,
          variables: this.buildInspectorRowsMulti(activeFrame.vars, changedVarsList),
          changedVars: changedVarsList,
          changedSummary: summaryParts.join(", "),
          condition: null,
          loop: this.getCurrentLoopSnapshot(loopStack),
          operationDetail: {
            kind: "assign",
            target: lhsTargets.join(", "),
            isCreated: changedVarsList.every((c) => c.status === "created"),
            beforeVal: "—",
            rhsExpr: rhsRaw,
            substituted: summaryParts.join(", "),
            afterVal: summaryParts.join(", ")
          },
          returnValue: null,
          stdout: [...stdout]
        });
        return null;
      }

      // Single assignment (`varName = expr` or `arr[i] = expr`)
      const cleanTarget = lhsRaw.split(":")[0].trim();
      const indexAssignMatch = cleanTarget.match(/^([a-zA-Z_]\w*)\[(.+)\]$/);
      if (indexAssignMatch) {
        const arrName = indexAssignMatch[1];
        const idxVal = this.evalExpr(
          indexAssignMatch[2],
          activeFrame.vars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          node.line
        );
        const newVal = this.evalExpr(
          rhsRaw,
          activeFrame.vars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          node.line
        );
        if (Array.isArray(activeFrame.vars[arrName])) {
          const prevArr = [...activeFrame.vars[arrName]];
          activeFrame.vars[arrName][idxVal] = newVal;
          const changeObj = { name: arrName, status: "updated", prevValue: prevArr };
          steps.push({
            stepIndex: steps.length + 1,
            line: node.line,
            codeText: text,
            eventType: "ASSIGN",
            functionName: activeFrame.frameName,
            beforeVars: beforeMap,
            variables: this.buildInspectorRows(activeFrame.vars, changeObj),
            changedVars: [changeObj],
            changedSummary: `${arrName}[${idxVal}] = ${this.formatVal(newVal)}`,
            condition: null,
            loop: this.getCurrentLoopSnapshot(loopStack),
            operationDetail: {
              kind: "assign",
              target: `${arrName}[${idxVal}]`,
              isCreated: false,
              beforeVal: this.formatVal(prevArr[idxVal]),
              rhsExpr: rhsRaw,
              substituted: this.formatVal(newVal),
              afterVal: this.formatVal(newVal)
            },
            returnValue: null,
            stdout: [...stdout]
          });
        }
        return null;
      }

      const varName = cleanTarget;
      const rhsExpr = rhsRaw;
      const prevVal = activeFrame.vars[varName];
      const isCreated = !(varName in activeFrame.vars);
      const substituted = this.substituteVarsInExpr(rhsExpr, activeFrame.vars);
      const newVal = this.evalExpr(
        rhsExpr,
        activeFrame.vars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        node.line
      );

      activeFrame.prevVars[varName] = prevVal;
      activeFrame.vars[varName] = newVal;

      const changeObj = {
        name: varName,
        status: isCreated ? "created" : "updated",
        prevValue: prevVal
      };

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "ASSIGN",
        functionName: activeFrame.frameName,
        beforeVars: beforeMap,
        variables: this.buildInspectorRows(activeFrame.vars, changeObj),
        changedVars: [changeObj],
        changedSummary: isCreated
          ? `${varName}: (created) → ${this.formatVal(newVal)}`
          : `${varName}: ${this.formatVal(prevVal)} → ${this.formatVal(newVal)}`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: {
          kind: "assign",
          target: varName,
          isCreated,
          beforeVal: isCreated ? "—" : this.formatVal(prevVal),
          rhsExpr,
          substituted,
          afterVal: this.formatVal(newVal)
        },
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    return null;
  }

  findSingleAssignmentEquals(str) {
    let depth = 0;
    let inSingle = false;
    let inDouble = false;
    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (!inSingle && !inDouble) {
        if (ch === "(" || ch === "[" || ch === "{") depth++;
        else if (ch === ")" || ch === "]" || ch === "}") depth--;
        else if (
          ch === "=" &&
          depth === 0 &&
          str[i - 1] !== "=" &&
          str[i - 1] !== "!" &&
          str[i - 1] !== "<" &&
          str[i - 1] !== ">" &&
          str[i + 1] !== "="
        ) {
          return i;
        }
      }
    }
    return -1;
  }

  invokeFunctionNode(
    fnNode,
    argVals,
    rawArgs,
    callStack,
    functions,
    classes,
    steps,
    stdout,
    loopStack,
    callerLine
  ) {
    const newVars = {};
    const paramBindings = [];
    fnNode.params.forEach((p, idx) => {
      const val = argVals[idx];
      newVars[p] = Array.isArray(val) ? [...val] : val;
      paramBindings.push({
        param: p,
        argExpr: rawArgs[idx] || p,
        val: this.formatVal(val)
      });
    });

    const newFrame = {
      frameName: `${fnNode.funcName}(${fnNode.params.map((p, i) => `${p}=${this.formatVal(argVals[i])}`).join(", ")})`,
      vars: newVars,
      prevVars: {}
    };

    callStack.push(newFrame);

    const createdRows = fnNode.params.map((p) => ({
      name: p,
      previous: "—",
      current: this.formatVal(newVars[p]),
      rawValue: newVars[p],
      type: this.getPythonType(newVars[p]),
      status: "created"
    }));

    steps.push({
      stepIndex: steps.length + 1,
      line: fnNode.line,
      codeText: fnNode.text,
      eventType: "FUNC_CALL",
      functionName: newFrame.frameName,
      beforeVars: {},
      variables: createdRows,
      changedVars: createdRows,
      changedSummary: paramBindings.map((b) => `${b.param}: (arg) → ${b.val}`).join(", "),
      condition: null,
      loop: null,
      operationDetail: {
        kind: "func_call",
        funcName: fnNode.funcName,
        callerLine,
        paramBindings
      },
      returnValue: null,
      stdout: [...stdout]
    });

    const res = this.executeSuite(
      fnNode.body,
      callStack,
      functions,
      classes,
      steps,
      stdout,
      loopStack
    );
    callStack.pop();
    return res;
  }

  evaluateCondition(condExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line) {
    const ops = ["==", "!=", ">=", "<=", ">", "<"];
    for (const op of ops) {
      const idx = condExpr.indexOf(op);
      if (idx !== -1) {
        const leftExpr = condExpr.slice(0, idx).trim();
        const rightExpr = condExpr.slice(idx + op.length).trim();
        const leftVal = this.evalExpr(leftExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line);
        const rightVal = this.evalExpr(rightExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line);
        const boolVal = Boolean(this.evalExpr(condExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line));
        return {
          expr: condExpr,
          leftExpr,
          leftVal: this.formatVal(leftVal),
          operator: op,
          rightExpr,
          rightVal: this.formatVal(rightVal),
          result: boolVal
        };
      }
    }
    const boolVal = Boolean(this.evalExpr(condExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line));
    return {
      expr: condExpr,
      leftExpr: condExpr,
      leftVal: this.formatVal(boolVal),
      operator: "is",
      rightExpr: "True",
      rightVal: "True",
      result: boolVal
    };
  }

  evalExpr(expr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum) {
    const trimmed = expr.trim();

    const rangeMatch = trimmed.match(/^range\((.+)\)$/);
    if (rangeMatch) {
      const parts = this.splitTopLevelArgs(rangeMatch[1]).map((a) =>
        Number(this.evalExpr(a, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum))
      );
      let start = 0,
        stop = 0,
        step = 1;
      if (parts.length === 1) stop = parts[0];
      else if (parts.length === 2) {
        start = parts[0];
        stop = parts[1];
      } else if (parts.length >= 3) {
        start = parts[0];
        stop = parts[1];
        step = parts[2] || 1;
      }
      const arr = [];
      if (step > 0) {
        for (let v = start; v < stop; v += step) arr.push(v);
      } else if (step < 0) {
        for (let v = start; v > stop; v += step) arr.push(v);
      }
      return arr;
    }

    const builtinMatch = trimmed.match(/^(len|min|max|abs|sum)\((.+)\)$/);
    if (builtinMatch) {
      const fnName = builtinMatch[1];
      const args = this.splitTopLevelArgs(builtinMatch[2]).map((a) =>
        this.evalExpr(a, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum)
      );
      if (fnName === "len") return args[0] && typeof args[0].length === "number" ? args[0].length : 0;
      if (fnName === "abs") return Math.abs(args[0]);
      if (fnName === "sum") return Array.isArray(args[0]) ? args[0].reduce((a, b) => a + b, 0) : 0;
      if (fnName === "min") return Array.isArray(args[0]) ? Math.min(...args[0]) : Math.min(...args);
      if (fnName === "max") return Array.isArray(args[0]) ? Math.max(...args[0]) : Math.max(...args);
    }

    const indexMatch = trimmed.match(/^([a-zA-Z_]\w*)\[(.+)\]$/);
    if (indexMatch) {
      const arrName = indexMatch[1];
      const idxVal = this.evalExpr(indexMatch[2], scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum);
      const arrObj = scopeVars[arrName];
      if (!Array.isArray(arrObj)) {
        throw { line: lineNum, message: `TypeError: '${arrName}' is not a list` };
      }
      const normalizedIdx = idxVal < 0 ? arrObj.length + idxVal : idxVal;
      if (normalizedIdx < 0 || normalizedIdx >= arrObj.length) {
        throw {
          line: lineNum,
          message: `IndexError: list index [${idxVal}] out of range for '${arrName}' (length ${arrObj.length})`
        };
      }
      return arrObj[normalizedIdx];
    }

    const methodCallMatch = trimmed.match(/^(?:[a-zA-Z_]\w*\(\)\.)?([a-zA-Z_]\w*)\((.*)\)$/);
    if (methodCallMatch && functions[methodCallMatch[1]]) {
      const fnNode = functions[methodCallMatch[1]];
      const rawArgs = methodCallMatch[2].trim() ? this.splitTopLevelArgs(methodCallMatch[2]) : [];
      const argVals = rawArgs.map((a) =>
        this.evalExpr(a, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum)
      );
      const res = this.invokeFunctionNode(
        fnNode,
        argVals,
        rawArgs,
        callStack,
        functions,
        classes,
        steps,
        stdout,
        loopStack,
        lineNum
      );
      return res && res.returned ? res.value : null;
    }

    let jsExpr = trimmed
      .replace(/\/\//g, "___INTDIV___")
      .replace(/\band\b/g, "&&")
      .replace(/\bor\b/g, "||")
      .replace(/\bnot\s+/g, "!")
      .replace(/\bTrue\b/g, "true")
      .replace(/\bFalse\b/g, "false")
      .replace(/\bNone\b/g, "null");

    if (jsExpr.includes("___INTDIV___")) {
      const parts = jsExpr.split("___INTDIV___");
      if (parts.length === 2) {
        jsExpr = `Math.floor((${parts[0]}) / (${parts[1]}))`;
      }
    }

    const keys = Object.keys(scopeVars);
    const vals = keys.map((k) => scopeVars[k]);
    try {
      const fn = new Function(...keys, `return (${jsExpr});`);
      const out = fn(...vals);
      if (typeof out === "number" && !Number.isFinite(out)) {
        throw new Error("ZeroDivisionError: division by zero");
      }
      return out;
    } catch (e) {
      throw { line: lineNum, message: e.message || String(e) };
    }
  }

  getCurrentLoopSnapshot(loopStack) {
    if (!loopStack.length) return null;
    return { ...loopStack[loopStack.length - 1] };
  }

  cloneVarsMap(vars) {
    const out = {};
    Object.keys(vars).forEach((k) => {
      out[k] = this.formatVal(vars[k]);
    });
    return out;
  }

  buildInspectorRows(vars, changedVarInfo) {
    return Object.keys(vars).map((name) => {
      const val = vars[name];
      const isChanged = changedVarInfo && changedVarInfo.name === name;
      let status = "unchanged";
      let prevStr = this.formatVal(val);

      if (isChanged) {
        status = changedVarInfo.status;
        prevStr =
          changedVarInfo.status === "created"
            ? "—"
            : this.formatVal(changedVarInfo.prevValue);
      }

      return {
        name,
        previous: prevStr,
        current: this.formatVal(val),
        rawValue: Array.isArray(val) ? [...val] : val,
        type: this.getPythonType(val),
        status
      };
    });
  }

  buildInspectorRowsMulti(vars, changedVarsList) {
    return Object.keys(vars).map((name) => {
      const val = vars[name];
      const found = changedVarsList.find((c) => c.name === name);
      let status = "unchanged";
      let prevStr = this.formatVal(val);

      if (found) {
        status = found.status;
        prevStr = found.status === "created" ? "—" : this.formatVal(found.prevValue);
      }

      return {
        name,
        previous: prevStr,
        current: this.formatVal(val),
        rawValue: Array.isArray(val) ? [...val] : val,
        type: this.getPythonType(val),
        status
      };
    });
  }

  substituteVarsInExpr(expr, scopeVars) {
    let result = expr;
    const sortedNames = Object.keys(scopeVars).sort((a, b) => b.length - a.length);
    for (const name of sortedNames) {
      const regex = new RegExp(`\\b${name}\\b`, "g");
      result = result.replace(regex, this.formatVal(scopeVars[name]));
    }
    return result;
  }

  splitTopLevelArgs(str) {
    if (!str.trim()) return [];
    const res = [];
    let current = "";
    let depth = 0;
    let inSingle = false;
    let inDouble = false;

    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (!inSingle && !inDouble) {
        if (ch === "(" || ch === "[") depth++;
        else if (ch === ")" || ch === "]") depth--;
        else if (ch === "," && depth === 0) {
          res.push(current.trim());
          current = "";
          continue;
        }
      }
      current += ch;
    }
    if (current.trim()) res.push(current.trim());
    return res;
  }

  getPythonType(val) {
    if (val === null || val === undefined) return "NoneType";
    if (Array.isArray(val)) return "list";
    if (typeof val === "boolean") return "bool";
    if (typeof val === "number") return Number.isInteger(val) ? "int" : "float";
    if (typeof val === "string") return "str";
    return typeof val;
  }

  formatVal(val) {
    if (val === null || val === undefined) return "None";
    if (typeof val === "boolean") return val ? "True" : "False";
    if (typeof val === "string") return `"${val}"`;
    if (Array.isArray(val)) return `[${val.map((v) => this.formatVal(v)).join(", ")}]`;
    return String(val);
  }

  buildControlFlowGraph(statements) {
    const nodes = [];
    const edges = [];

    const addNode = (id, label, type, line) => {
      nodes.push({ id, label, type, line });
      return id;
    };

    const startId = addNode("start", "START", "start", 0);

    const buildList = (stmts, prevIds) => {
      let currentPrevs = prevIds;
      for (const s of stmts) {
        if (s.kind === "CLASS") {
          const cid = addNode(`L${s.line}`, `class ${s.className}`, "class", s.line);
          currentPrevs.forEach((p) => edges.push({ from: p, to: cid }));
          currentPrevs = buildList(s.body, [cid]);
        } else if (s.kind === "DEF") {
          const fid = addNode(`L${s.line}`, `def ${s.funcName}()`, "func", s.line);
          currentPrevs.forEach((p) => edges.push({ from: p, to: fid }));
          currentPrevs = buildList(s.body, [fid]);
        } else if (s.kind === "IF_CHAIN") {
          const exitIds = [];
          let condPrevIds = currentPrevs;
          for (const br of s.branches) {
            if (br.type === "else") {
              const bodyEnd = buildList(br.body, condPrevIds);
              exitIds.push(...bodyEnd);
              condPrevIds = [];
            } else {
              const cid = addNode(`L${br.line}`, `${br.condition} ?`, "decision", br.line);
              condPrevIds.forEach((p) => edges.push({ from: p, to: cid }));
              const bodyEnd = buildList(br.body, [cid]);
              exitIds.push(...bodyEnd);
              condPrevIds = [cid];
            }
          }
          currentPrevs = [...exitIds, ...condPrevIds];
        } else if (s.kind === "FOR" || s.kind === "WHILE") {
          const label =
            s.kind === "FOR"
              ? `for ${s.iterVar} in ${s.iterExpr}`
              : `while ${s.condition}`;
          const loopId = addNode(`L${s.line}`, label, "loop", s.line);
          currentPrevs.forEach((p) => edges.push({ from: p, to: loopId }));
          const bodyEnd = buildList(s.body, [loopId]);
          bodyEnd.forEach((b) => edges.push({ from: b, to: loopId, isBackEdge: true }));
          currentPrevs = [loopId];
        } else {
          const type = s.text.startsWith("return") ? "return" : "stmt";
          const nid = addNode(
            `L${s.line}`,
            s.text.length > 26 ? s.text.slice(0, 24) + ".." : s.text,
            type,
            s.line
          );
          currentPrevs.forEach((p) => edges.push({ from: p, to: nid }));
          currentPrevs = [nid];
        }
      }
      return currentPrevs;
    };

    const lastIds = buildList(statements, [startId]);
    const endId = addNode("end", "END", "end", 9999);
    lastIds.forEach((p) => edges.push({ from: p, to: endId }));

    return { nodes, edges };
  }
}

