1482:   evalExpr(expr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum) {
1483:     const trimmed = expr.trim();
1484: 
1485:     const rangeMatch = trimmed.match(/^range\((.+)\)$/);
1486:     if (rangeMatch) {
1487:       const parts = this.splitTopLevelArgs(rangeMatch[1]).map((a) =>
1488:         Number(this.evalExpr(a, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum))
1489:       );
1490:       let start = 0,
1491:         stop = 0,
1492:         step = 1;
1493:       if (parts.length === 1) stop = parts[0];
1494:       else if (parts.length === 2) {
1495:         start = parts[0];
1496:         stop = parts[1];
1497:       } else if (parts.length >= 3) {
1498:         start = parts[0];
1499:         stop = parts[1];
1500:         step = parts[2] || 1;
1501:       }
1502:       const arr = [];
1503:       if (step > 0) {
1504:         for (let v = start; v < stop; v += step) arr.push(v);
1505:       } else if (step < 0) {
1506:         for (let v = start; v > stop; v += step) arr.push(v);
1507:       }
1508:       return arr;
1509:     }
1510: 
1511:     const builtinMatch = trimmed.match(/^(len|min|max|abs|sum)\((.+)\)$/);
1512:     if (builtinMatch) {
1513:       const fnName = builtinMatch[1];
1514:       const args = this.splitTopLevelArgs(builtinMatch[2]).map((a) =>
1515:         this.evalExpr(a, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum)
1516:       );
1517:       if (fnName === "len") return args[0] && typeof args[0].length === "number" ? args[0].length : 0;
1518:       if (fnName === "abs") return Math.abs(args[0]);
1519:       if (fnName === "sum") return Array.isArray(args[0]) ? args[0].reduce((a, b) => a + b, 0) : 0;
1520:       if (fnName === "min") return Array.isArray(args[0]) ? Math.min(...args[0]) : Math.min(...args);
1521:       if (fnName === "max") return Array.isArray(args[0]) ? Math.max(...args[0]) : Math.max(...args);
1522:     }
1523: 
1524:     const indexMatch = trimmed.match(/^([a-zA-Z_]\w*)\[(.+)\]$/);
1525:     if (indexMatch) {
1526:       const arrName = indexMatch[1];
1527:       const idxVal = this.evalExpr(indexMatch[2], scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum);
1528:       const arrObj = scopeVars[arrName];
1529:       if (!Array.isArray(arrObj)) {
1530:         throw { line: lineNum, message: `TypeError: '${arrName}' is not a list` };
