class MemoryHeapTracker {
  constructor(formatValFn, getTypeFn) {
    this.formatVal = formatValFn;
    this.getType = getTypeFn;
    this.scalarCounter = 0x1000;
    this.containerCounter = 0x2000;
    this.scalarPool = new Map(); // key: `${type}:${repr}` -> address
    this.containerWeakMap = new WeakMap(); // Array reference -> address
    this.heapRegistry = new Map(); // address -> metadata
  }

  getOrAllocate(val, stepIdx) {
    const pyType = this.getType(val);
    const valRepr = this.formatVal(val);

    if (Array.isArray(val)) {
      let addr = this.containerWeakMap.get(val);
      if (!addr) {
        addr = `@0x${this.containerCounter.toString(16).toUpperCase().padStart(4, "0")}`;
        this.containerCounter += 0x40;
        this.containerWeakMap.set(val, addr);
      }
      this.heapRegistry.set(addr, {
        address: addr,
        type: "list",
        repr: valRepr,
        isMutable: true,
        elements: val.map((item) => this.formatVal(item)),
        rawElements: [...val],
        lastTouchedStep: stepIdx
      });
      return addr;
    }

    const key = `${pyType}:${valRepr}`;
    let addr = this.scalarPool.get(key);
    if (!addr) {
      addr = `@0x${this.scalarCounter.toString(16).toUpperCase().padStart(4, "0")}`;
      this.scalarCounter += 0x08;
      this.scalarPool.set(key, addr);
    }
    this.heapRegistry.set(addr, {
      address: addr,
      type: pyType,
      repr: valRepr,
      isMutable: false,
      elements: null,
      rawElements: null,
      lastTouchedStep: stepIdx
    });
    return addr;
  }

  captureSnapshot(scopeFrames, stepIdx, changedVars = []) {
    const refCounts = new Map();
    const referencedBy = new Map();

    for (const addr of this.heapRegistry.keys()) {
      refCounts.set(addr, 0);
      referencedBy.set(addr, []);
    }

    for (const scope of scopeFrames) {
      const scopeTag = scope.scopeType === "GLOBAL" ? "Global" : scope.funcShortName || scope.title;
      for (const v of scope.variables) {
        if (v.address && this.heapRegistry.has(v.address)) {
          refCounts.set(v.address, (refCounts.get(v.address) || 0) + 1);
          referencedBy.get(v.address).push(`${scopeTag}.${v.name}`);
        }
      }
    }

    const changedAddrSet = new Set(changedVars.map((c) => c.address).filter(Boolean));
    const activeHeap = [];
    const gcHeap = [];

    for (const [addr, meta] of this.heapRegistry.entries()) {
      const rc = refCounts.get(addr) || 0;
      const entry = {
        ...meta,
        refCount: rc,
        referencedBy: referencedBy.get(addr) || [],
        isHighlighted: changedAddrSet.has(addr),
        gcStatus: rc > 0 ? "active" : "unreferenced"
      };
      if (rc > 0) {
        activeHeap.push(entry);
      } else {
        gcHeap.push(entry);
      }
    }

    return {
      stackScopes: scopeFrames,
      heapObjects: activeHeap,
      gcObjects: gcHeap.slice(-4), // Most recent unreferenced objects for Visual GC view
      totalUnreferencedCount: gcHeap.length
    };
  }
}

class PythonExecutionEngine {
  constructor() {
    this.maxSteps = 400;
  }

  validateSupport(sourceCode) {
    if (!sourceCode || !sourceCode.trim()) {
      return {
        ok: false,
        line: 1,
        message: "The code editor is empty. Paste or write a Python program to analyze."
      };
    }

    const lines = sourceCode.replace(/\r\n/g, "\n").split("\n");

    const unsupportedRules = [
      { regex: /^\s*(import|from)\s+/, msg: "`import` statements are not supported in the offline sandbox." },
      { regex: /^\s*async\s+/, msg: "`async` / `await` constructs are not supported." },
      { regex: /\bawait\s+/, msg: "`await` expressions are not supported." },
      { regex: /^\s*with\s+/, msg: "`with` context managers and file I/O are not supported." },
      { regex: /\byield\b/, msg: "Generator `yield` statements are not supported." },
      { regex: /\blambda\b/, msg: "`lambda` expressions are not supported; please use `def`." },
      { regex: /^\s*(try|except|finally)\b/, msg: "`try / except` blocks are not supported." },
      { regex: /\b(open|eval|exec|__import__|input)\s*\(/, msg: "Restricted built-in function (`open`, `eval`, `exec`, `input`) is disabled for security." }
    ];

    let parenDepth = 0;
    let bracketDepth = 0;

    for (let i = 0; i < lines.length; i++) {
      const raw = lines[i];
      const stripped = this.stripInlineComment(raw);
      const trimmed = stripped.trim();
      if (!trimmed) continue;

      for (const rule of unsupportedRules) {
        if (rule.regex.test(trimmed)) {
          return {
            ok: false,
            line: i + 1,
            message: `Unsupported Syntax on Line ${i + 1}: ${rule.msg}`
          };
        }
      }

      if (/^(class|def|if|elif|else|for|while)\b/.test(trimmed) && !trimmed.endsWith(":")) {
        return {
          ok: false,
          line: i + 1,
          message: `SyntaxError on Line ${i + 1}: Block header (\`${trimmed}\`) must end with a colon (\`:\`).`
        };
      }

      for (const ch of trimmed) {
        if (ch === "(") parenDepth++;
        else if (ch === ")") parenDepth--;
        else if (ch === "[") bracketDepth++;
        else if (ch === "]") bracketDepth--;
      }

      if (parenDepth < 0 || bracketDepth < 0) {
        return {
          ok: false,
          line: i + 1,
          message: `SyntaxError on Line ${i + 1}: Unmatched closing parenthesis or bracket.`
        };
      }
    }

    if (parenDepth !== 0 || bracketDepth !== 0) {
      return {
        ok: false,
        line: lines.length,
        message: "SyntaxError: Unclosed parenthesis `(` or bracket `[` in code."
      };
    }

    return { ok: true, line: null, message: null };
  }

  parseInputAssignments(inputCode) {
    const inputVars = {};
    if (!inputCode || !inputCode.trim()) return inputVars;

    const segments = this.splitTopLevelSegments(inputCode);
    const dummyVars = {};

    for (const seg of segments) {
      const eqIdx = seg.indexOf("=");
      if (eqIdx !== -1) {
        const vName = seg.slice(0, eqIdx).trim();
        const vExpr = seg.slice(eqIdx + 1).trim();
        const val = this.evalExpr(vExpr, dummyVars, {}, {}, [], [], [], [], 1);
        dummyVars[vName] = val;
        inputVars[vName] = val;
      } else {
        const val = this.evalExpr(seg, dummyVars, {}, {}, [], [], [], [], 1);
        inputVars["nums"] = val;
      }
    }
    return inputVars;
  }

  splitTopLevelSegments(str) {
    const res = [];
    let cur = "";
    let depth = 0;
    let inSingle = false;
    let inDouble = false;

    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (!inSingle && !inDouble) {
        if (ch === "(" || ch === "[" || ch === "{") depth++;
        else if (ch === ")" || ch === "]" || ch === "}") depth--;
        else if ((ch === ";" || ch === "\n" || (ch === "," && depth === 0)) && cur.includes("=")) {
          res.push(cur.trim());
          cur = "";
          continue;
        }
      }
      cur += ch;
    }
    if (cur.trim()) res.push(cur.trim());
    return res;
  }

  trace(sourceCode, inputCode = "") {
    const validation = this.validateSupport(sourceCode);
    const rawLines = sourceCode.replace(/\r\n/g, "\n").split("\n");

    if (!validation.ok) {
      return {
        ok: false,
        errorType: "UNSUPPORTED_OR_SYNTAX",
        errorMessage: validation.message,
        errorLine: validation.line,
        rawLines,
        steps: [],
        cfg: { nodes: [], edges: [] }
      };
    }

    let inputVars = {};
    try {
      inputVars = this.parseInputAssignments(inputCode);
    } catch (err) {
      return {
        ok: false,
        errorType: "INVALID_INPUT",
        errorMessage: `Invalid Input List: ${err.message || err}`,
        errorLine: 1,
        rawLines,
        steps: [],
        cfg: { nodes: [], edges: [] }
      };
    }

    this.heapTracker = new MemoryHeapTracker(
      (v) => this.formatVal(v),
      (v) => this.getPythonType(v)
    );

    const statements = this.parseProgram(rawLines);
    const cfg = this.buildControlFlowGraph(statements);

    const steps = [];
    const stdout = [];
    const functions = {};
    const classes = {};
    const callStack = [
      {
        frameId: "global",
        frameName: "Global Scope",
        funcShortName: "Global",
        scopeType: "GLOBAL",
        vars: {},
        prevVars: {}
      }
    ];
    const loopStack = [];

    Object.entries(inputVars).forEach(([k, v]) => {
      const cloned = Array.isArray(v) ? [...v] : v;
      callStack[0].vars[k] = cloned;
      callStack[0].prevVars[k] = cloned;
      this.heapTracker.getOrAllocate(cloned, 0);
    });

    let finalReturnVal = null;

    try {
      this.executeSuite(statements, callStack, functions, classes, steps, stdout, loopStack);

      const fnNames = Object.keys(functions);
      const onlyDefinitionsRan = steps.every(
        (s) => s.eventType === "CLASS_DEF" || s.eventType === "METHOD_DEF" || s.eventType === "FUNC_DEF"
      );

      if (onlyDefinitionsRan && fnNames.length > 0) {
        const fnNode = functions[fnNames[0]];
        const argVals = this.resolveFunctionArguments(fnNode, callStack[0].vars);
        const callRes = this.invokeFunctionNode(
          fnNode,
          argVals,
          fnNode.params,
          callStack,
          functions,
          classes,
          steps,
          stdout,
          loopStack,
          fnNode.line
        );
        if (callRes && callRes.returned) {
          finalReturnVal = callRes.value;
        }
      }
    } catch (err) {
      const errLine = err.line || 1;
      const errMsg = err.message || String(err);
      const activeFrame = callStack[callStack.length - 1];
      this.pushStepSnapshot(steps, {
        line: errLine,
        codeText: rawLines[errLine - 1] ? rawLines[errLine - 1].trim() : "",
        eventType: "EXCEPTION",
        callStack,
        beforeVars: this.cloneVarsMap(activeFrame.vars),
        changedVars: [],
        changedSummary: `Exception raised: ${errMsg}`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "exception", message: errMsg },
        exprFrames: [{ expr: rawLines[errLine - 1] ? rawLines[errLine - 1].trim() : "", focus: `Error: ${errMsg}`, shortCircuited: false }],
        returnValue: null,
        stdout: [...stdout]
      });

      this.finalizeNextLines(steps);
      return {
        ok: false,
        errorType: "RUNTIME_EXCEPTION",
        errorMessage: errMsg,
        errorLine: errLine,
        rawLines,
        steps,
        cfg,
        finalResult: null
      };
    }

    this.finalizeNextLines(steps);

    return {
      ok: true,
      errorType: null,
      errorMessage: null,
      errorLine: null,
      rawLines,
      steps,
      cfg,
      finalResult: finalReturnVal !== null ? this.formatVal(finalReturnVal) : null
    };
  }

  pushStepSnapshot(steps, payload) {
    const stepIndex = steps.length + 1;
    const callStack = payload.callStack;
    const activeFrame = callStack[callStack.length - 1];
    const changedVars = payload.changedVars || [];

    const variables = this.buildInspectorRowsMulti(activeFrame.vars, changedVars, stepIndex);
    const scopeFrames = this.captureScopeFrames(callStack, changedVars, stepIndex);
    const memoryModel = this.heapTracker.captureSnapshot(scopeFrames, stepIndex, variables.filter((v) => v.status !== "unchanged"));

    steps.push({
      stepIndex,
      line: payload.line,
      nextLine: null,
      codeText: payload.codeText,
      eventType: payload.eventType,
      functionName: activeFrame.frameName,
      scopeType: activeFrame.scopeType || (callStack.length > 1 ? "LOCAL" : "GLOBAL"),
      beforeVars: payload.beforeVars,
      variables,
      changedVars,
      changedSummary: payload.changedSummary,
      condition: payload.condition || null,
      loop: payload.loop || null,
      operationDetail: payload.operationDetail || null,
      exprFrames:
        payload.exprFrames && payload.exprFrames.length
          ? payload.exprFrames
          : [{ expr: payload.codeText, focus: "Statement executed", shortCircuited: false }],
      scopeFrames,
      memoryModel,
      returnValue: payload.returnValue !== undefined ? payload.returnValue : null,
      stdout: payload.stdout || []
    });
  }

  captureScopeFrames(callStack, activeChangedVars, stepIdx) {
    return callStack.map((frame, idx) => {
      const isActive = idx === callStack.length - 1;
      const frameChanges = isActive ? activeChangedVars : [];
      const rows = this.buildInspectorRowsMulti(frame.vars, frameChanges, stepIdx);
      return {
        scopeId: frame.frameId || (idx === 0 ? "global" : `local_${idx}`),
        scopeType: frame.scopeType || (idx === 0 ? "GLOBAL" : "LOCAL"),
        title: idx === 0 ? "Global Scope" : `Local Scope: ${frame.funcShortName || frame.frameName}`,
        functionName: frame.frameName,
        funcShortName: frame.funcShortName || (idx === 0 ? "Global" : frame.frameName),
        isActive,
        variables: rows
      };
    });
  }

  resolveFunctionArguments(fnNode, globalVars) {
    const inputValues = Object.values(globalVars);
    const firstArray = inputValues.find((v) => Array.isArray(v)) || [-2, 1, -3, 4, -1, 2, 1, -5, 4];

    return fnNode.params.map((paramName, idx) => {
      if (paramName in globalVars) {
        // Return the exact reference so Global and Local scopes share the heap address @0x2000!
        return globalVars[paramName];
      }
      if (["arr", "nums", "items", "numbers", "a"].includes(paramName)) {
        if (fnNode.funcName.toLowerCase().includes("binary")) {
          const isSorted = firstArray.every((v, i, a) => i === 0 || a[i - 1] <= v);
          if (!isSorted) {
            const sortedArr = [...firstArray].sort((a, b) => a - b);
            globalVars[paramName] = sortedArr;
            return sortedArr;
          }
        }
        globalVars[paramName] = firstArray;
        return firstArray;
      }
      if (["target", "val", "key", "x", "k"].includes(paramName)) {
        if ("target" in globalVars) return globalVars["target"];
        const targetVal =
          firstArray.length > 0 ? firstArray[Math.floor(firstArray.length / 2)] : 4;
        globalVars[paramName] = targetVal;
        return targetVal;
      }
      return inputValues[idx] !== undefined ? inputValues[idx] : 0;
    });
  }

  finalizeNextLines(steps) {
    for (let i = 0; i < steps.length; i++) {
      steps[i].nextLine = i + 1 < steps.length ? steps[i + 1].line : null;
    }
  }

  stripInlineComment(line) {
    let inSingle = false;
    let inDouble = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (ch === "#" && !inSingle && !inDouble) {
        return line.slice(0, i);
      }
    }
    return line;
  }

  parseProgram(rawLines) {
    const items = [];
    for (let i = 0; i < rawLines.length; i++) {
      const stripped = this.stripInlineComment(rawLines[i]);
      const trimmed = stripped.trim();
      if (!trimmed) continue;
      const indent = rawLines[i].match(/^\s*/)[0].length;
      items.push({ line: i + 1, indent, text: trimmed, raw: rawLines[i] });
    }
    return this.buildASTBlock(items, 0, items.length > 0 ? items[0].indent : 0).nodes;
  }

  buildASTBlock(items, startIdx, baseIndent) {
    const nodes = [];
    let i = startIdx;

    while (i < items.length) {
      const item = items[i];
      if (item.indent < baseIndent) break;

      if (item.text.startsWith("class ") && item.text.endsWith(":")) {
        const className = item.text.slice(6, -1).split("(")[0].trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "CLASS",
          line: item.line,
          text: item.text,
          className,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("def ") && item.text.endsWith(":")) {
        const match = item.text.match(/^def\s+([a-zA-Z_]\w*)\s*\((.*)\)\s*(?:->\s*[^:]+)?\s*:$/);
        const funcName = match ? match[1] : "func";
        const rawParams = match && match[2].trim() ? this.splitTopLevelArgs(match[2]) : [];
        const params = rawParams
          .map((p) => p.split(":")[0].split("=")[0].trim())
          .filter((p) => p && p !== "self");
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "DEF",
          line: item.line,
          text: item.text,
          funcName,
          params,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("if ") && item.text.endsWith(":")) {
        const branches = [];
        const cond = item.text.slice(3, -1).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        branches.push({
          type: "if",
          line: item.line,
          text: item.text,
          condition: cond,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;

        while (i < items.length && items[i].indent === item.indent) {
          const cur = items[i];
          if (cur.text.startsWith("elif ") && cur.text.endsWith(":")) {
            const elifCond = cur.text.slice(5, -1).trim();
            const elifBody = this.parseChildSuite(items, i + 1, cur.indent);
            branches.push({
              type: "elif",
              line: cur.line,
              text: cur.text,
              condition: elifCond,
              body: elifBody.nodes
            });
            i = elifBody.nextIdx;
          } else if (cur.text === "else:") {
            const elseBody = this.parseChildSuite(items, i + 1, cur.indent);
            branches.push({
              type: "else",
              line: cur.line,
              text: cur.text,
              condition: null,
              body: elseBody.nodes
            });
            i = elseBody.nextIdx;
            break;
          } else {
            break;
          }
        }
        nodes.push({
          kind: "IF_CHAIN",
          line: item.line,
          text: item.text,
          branches
        });
      } else if (item.text.startsWith("for ") && item.text.endsWith(":")) {
        const header = item.text.slice(4, -1).trim();
        const inIdx = header.indexOf(" in ");
        const iterVar = header.slice(0, inIdx).trim();
        const iterExpr = header.slice(inIdx + 4).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "FOR",
          line: item.line,
          text: item.text,
          iterVar,
          iterExpr,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("while ") && item.text.endsWith(":")) {
        const condition = item.text.slice(6, -1).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "WHILE",
          line: item.line,
          text: item.text,
          condition,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else {
        nodes.push({
          kind: "STMT",
          line: item.line,
          text: item.text
        });
        i++;
      }
    }

    return { nodes, nextIdx: i };
  }

  parseChildSuite(items, nextIdx, parentIndent) {
    if (nextIdx >= items.length || items[nextIdx].indent <= parentIndent) {
      return { nodes: [], nextIdx };
    }
    return this.buildASTBlock(items, nextIdx, items[nextIdx].indent);
  }

  executeSuite(nodes, callStack, functions, classes, steps, stdout, loopStack) {
    for (const node of nodes) {
      if (steps.length >= this.maxSteps) {
        throw {
          line: node.line,
          message: `TimeoutError: Execution exceeded ${this.maxSteps} steps (possible infinite loop).`
        };
      }
      const res = this.executeNode(node, callStack, functions, classes, steps, stdout, loopStack);
      if (res && (res.returned || res.broke || res.continued)) {
        return res;
      }
    }
    return null;
  }

  executeNode(node, callStack, functions, classes, steps, stdout, loopStack) {
    const activeFrame = callStack[callStack.length - 1];

    if (node.kind === "CLASS") {
      classes[node.className] = { name: node.className, methods: {} };
      this.pushStepSnapshot(steps, {
        line: node.line,
        codeText: node.text,
        eventType: "CLASS_DEF",
        callStack,
        beforeVars: this.cloneVarsMap(activeFrame.vars),
        changedVars: [],
        changedSummary: `Defined class '${node.className}'`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "class_def", className: node.className },
        exprFrames: [{ expr: node.text, focus: `Register class ${node.className}`, shortCircuited: false }],
        returnValue: null,
        stdout: [...stdout]
      });

      for (const child of node.body) {
        if (child.kind === "DEF") {
          classes[node.className].methods[child.funcName] = child;
          functions[child.funcName] = child;
          this.pushStepSnapshot(steps, {
            line: child.line,
            codeText: child.text,
            eventType: "METHOD_DEF",
            callStack,
            beforeVars: this.cloneVarsMap(activeFrame.vars),
            changedVars: [],
            changedSummary: `Defined method '${child.funcName}(${child.params.join(", ")})'`,
            condition: null,
            loop: null,
            operationDetail: {
              kind: "method_def",
              className: node.className,
              funcName: child.funcName,
              params: child.params
            },
            exprFrames: [{ expr: child.text, focus: `Bind method ${child.funcName}`, shortCircuited: false }],
            returnValue: null,
            stdout: [...stdout]
          });
        }
      }
      return null;
    }

    if (node.kind === "DEF") {
      functions[node.funcName] = node;
      this.pushStepSnapshot(steps, {
        line: node.line,
        codeText: node.text,
        eventType: "FUNC_DEF",
        callStack,
        beforeVars: this.cloneVarsMap(activeFrame.vars),
        changedVars: [],
        changedSummary: `Defined function '${node.funcName}(${node.params.join(", ")})'`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "func_def", funcName: node.funcName, params: node.params },
        exprFrames: [{ expr: node.text, focus: `Register function ${node.funcName} in Global Scope`, shortCircuited: false }],
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    if (node.kind === "IF_CHAIN") {
      for (const branch of node.branches) {
        if (branch.type === "else") {
          this.pushStepSnapshot(steps, {
            line: branch.line,
            codeText: branch.text,
            eventType: "ELSE_BRANCH",
            callStack,
            beforeVars: this.cloneVarsMap(activeFrame.vars),
            changedVars: [],
            changedSummary: "Previous conditions were False → entering else block",
            condition: {
              expr: "else",
              leftExpr: "Previous conditions",
              leftVal: "False",
              operator: "->",
              rightExpr: "else",
              rightVal: "True",
              result: true
            },
            loop: this.getCurrentLoopSnapshot(loopStack),
            operationDetail: { kind: "else_branch" },
            exprFrames: [
              { expr: "else:", focus: "All previous if/elif conditions evaluated to False", shortCircuited: false }
            ],
            returnValue: null,
            stdout: [...stdout]
          });
          return this.executeSuite(branch.body, callStack, functions, classes, steps, stdout, loopStack);
        } else {
          const kw = branch.type === "elif" ? "elif " : "if ";
          const evalRes = this.evaluateConditionWithFrames(
            branch.condition,
            kw,
            ":",
            activeFrame.vars,
            functions,
            classes,
            callStack,
            steps,
            stdout,
            loopStack,
            branch.line
          );
          const condInfo = evalRes.condInfo;
          this.pushStepSnapshot(steps, {
            line: branch.line,
            codeText: branch.text,
            eventType: "CONDITION",
            callStack,
            beforeVars: this.cloneVarsMap(activeFrame.vars),
            changedVars: [],
            changedSummary: "No variable values changed (Condition check)",
            condition: condInfo,
            loop: this.getCurrentLoopSnapshot(loopStack),
            operationDetail: { kind: "condition", ...condInfo },
            exprFrames: evalRes.frames,
            returnValue: null,
            stdout: [...stdout]
          });
          if (condInfo.result) {
            return this.executeSuite(branch.body, callStack, functions, classes, steps, stdout, loopStack);
          }
        }
      }
      return null;
    }

    if (node.kind === "FOR") {
      const iterEval = this.evaluateExpressionWithSteps(
        node.iterExpr,
        `for ${node.iterVar} in `,
        ":",
        activeFrame.vars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        node.line
      );
      const iterable = iterEval.value;
      const listItems = Array.isArray(iterable) ? iterable : [];

      loopStack.push({
        loopType: "for",
        iterVar: node.iterVar,
        iterExpr: node.iterExpr,
        currentIteration: 0,
        totalIterations: listItems.length,
        currentItemValue: null,
        headerLine: node.line
      });

      for (let idx = 0; idx < listItems.length; idx++) {
        if (steps.length >= this.maxSteps) {
          throw {
            line: node.line,
            message: `TimeoutError: Execution exceeded ${this.maxSteps} steps (possible infinite loop).`
          };
        }

        const beforeMap = this.cloneVarsMap(activeFrame.vars);
        const itemVal = listItems[idx];
        const prevVal = activeFrame.vars[node.iterVar];
        const isCreated = !(node.iterVar in activeFrame.vars);

        activeFrame.prevVars[node.iterVar] = prevVal;
        activeFrame.vars[node.iterVar] = itemVal;

        const topLoop = loopStack[loopStack.length - 1];
        topLoop.currentIteration = idx + 1;
        topLoop.currentItemValue = this.formatVal(itemVal);
        topLoop.currentIndex = idx;

        let indexedElementInfo = null;
        const arrCandidate = activeFrame.vars["nums"] || activeFrame.vars["arr"];
        const arrName = activeFrame.vars["nums"] ? "nums" : activeFrame.vars["arr"] ? "arr" : null;
        if (
          typeof itemVal === "number" &&
          Array.isArray(arrCandidate) &&
          itemVal >= 0 &&
          itemVal < arrCandidate.length
        ) {
          indexedElementInfo = {
            arrayName: arrName,
            indexVar: node.iterVar,
            indexVal: itemVal,
            elementVal: this.formatVal(arrCandidate[itemVal])
          };
        }

        const changeObj = {
          name: node.iterVar,
          status: isCreated ? "created" : "updated",
          prevValue: prevVal
        };

        const loopFrames = [
          { expr: node.text, focus: `Loop pass ${idx + 1} of ${listItems.length}`, shortCircuited: false },
          ...iterEval.frames.slice(1),
          {
            expr: `${node.iterVar} = ${this.formatVal(itemVal)}`,
            focus: `Bind loop variable ${node.iterVar} → ${this.formatVal(itemVal)}`,
            shortCircuited: false
          }
        ];

        this.pushStepSnapshot(steps, {
          line: node.line,
          codeText: node.text,
          eventType: "LOOP_ITER",
          callStack,
          beforeVars: beforeMap,
          changedVars: [changeObj],
          changedSummary: isCreated
            ? `${node.iterVar}: (created) → ${this.formatVal(itemVal)}`
            : `${node.iterVar}: ${this.formatVal(prevVal)} → ${this.formatVal(itemVal)}`,
          condition: {
            expr: `${node.iterVar} in ${node.iterExpr}`,
            leftExpr: `Iteration ${idx + 1} of ${listItems.length}`,
            leftVal: `${node.iterVar} = ${this.formatVal(itemVal)}`,
            operator: "in",
            rightExpr: node.iterExpr,
            rightVal: `len=${listItems.length}`,
            result: true
          },
          loop: {
            ...this.getCurrentLoopSnapshot(loopStack),
            indexedElementInfo
          },
          operationDetail: {
            kind: "for_iter",
            iterVar: node.iterVar,
            iterVal: this.formatVal(itemVal),
            iteration: idx + 1,
            total: listItems.length,
            indexedElementInfo
          },
          exprFrames: loopFrames,
          returnValue: null,
          stdout: [...stdout]
        });

        const bodyRes = this.executeSuite(
          node.body,
          callStack,
          functions,
          classes,
          steps,
          stdout,
          loopStack
        );
        if (bodyRes) {
          if (bodyRes.returned) {
            loopStack.pop();
            return bodyRes;
          }
          if (bodyRes.broke) {
            loopStack.pop();
            return null;
          }
          if (bodyRes.continued) {
            continue;
          }
        }
      }

      loopStack.pop();

      this.pushStepSnapshot(steps, {
        line: node.line,
        codeText: node.text,
        eventType: "LOOP_END",
        callStack,
        beforeVars: this.cloneVarsMap(activeFrame.vars),
        changedVars: [],
        changedSummary: `Loop finished all ${listItems.length} iterations`,
        condition: {
          expr: `${node.iterVar} in ${node.iterExpr}`,
          leftExpr: "Remaining items",
          leftVal: "0",
          operator: "==",
          rightExpr: "Exhausted",
          rightVal: "StopIteration",
          result: false
        },
        loop: {
          loopType: "for",
          iterVar: node.iterVar,
          iterExpr: node.iterExpr,
          currentIteration: listItems.length,
          totalIterations: listItems.length,
          isFinished: true
        },
        operationDetail: {
          kind: "for_end",
          iterVar: node.iterVar,
          total: listItems.length
        },
        exprFrames: [
          { expr: node.text, focus: `Sequence ${node.iterExpr} exhausted (${listItems.length}/${listItems.length} items done)`, shortCircuited: false }
        ],
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    if (node.kind === "WHILE") {
      let iter = 0;
      loopStack.push({
        loopType: "while",
        condition: node.condition,
        currentIteration: 0,
        totalIterations: null,
        headerLine: node.line
      });

      while (true) {
        if (steps.length >= this.maxSteps) {
          throw {
            line: node.line,
            message: `TimeoutError: Execution exceeded ${this.maxSteps} steps (possible infinite loop).`
          };
        }
        iter++;
        loopStack[loopStack.length - 1].currentIteration = iter;

        const evalRes = this.evaluateConditionWithFrames(
          node.condition,
          "while ",
          ":",
          activeFrame.vars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          node.line
        );
        const condInfo = evalRes.condInfo;

        this.pushStepSnapshot(steps, {
          line: node.line,
          codeText: node.text,
          eventType: condInfo.result ? "LOOP_ITER" : "LOOP_END",
          callStack,
          beforeVars: this.cloneVarsMap(activeFrame.vars),
          changedVars: [],
          changedSummary: condInfo.result
            ? `While condition True (Pass #${iter})`
            : `While condition False (Loop exits)`,
          condition: condInfo,
          loop: this.getCurrentLoopSnapshot(loopStack),
          operationDetail: {
            kind: "while_check",
            iteration: iter,
            ...condInfo
          },
          exprFrames: evalRes.frames,
          returnValue: null,
          stdout: [...stdout]
        });

        if (!condInfo.result) break;

        const bodyRes = this.executeSuite(
          node.body,
          callStack,
          functions,
          classes,
          steps,
          stdout,
          loopStack
        );
        if (bodyRes) {
          if (bodyRes.returned) {
            loopStack.pop();
            return bodyRes;
          }
          if (bodyRes.broke) {
            loopStack.pop();
            return null;
          }
          if (bodyRes.continued) {
            continue;
          }
        }
      }

      loopStack.pop();
      return null;
    }

    if (node.kind === "STMT") {
      return this.executeStatement(
        node,
        callStack,
        functions,
        classes,
        steps,
        stdout,
        loopStack
      );
    }

    return null;
  }

  executeStatement(node, callStack, functions, classes, steps, stdout, loopStack) {
    const activeFrame = callStack[callStack.length - 1];
    const text = node.text;
    const beforeMap = this.cloneVarsMap(activeFrame.vars);

    // 1. break
    if (text === "break") {
      this.pushStepSnapshot(steps, {
        line: node.line,
        codeText: text,
        eventType: "BREAK",
        callStack,
        beforeVars: beforeMap,
        changedVars: [],
        changedSummary: "Breaking out of current loop immediately",
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "break" },
        exprFrames: [{ expr: "break", focus: "Exit active loop immediately", shortCircuited: false }],
        returnValue: null,
        stdout: [...stdout]
      });
      return { broke: true };
    }

    // 2. continue
    if (text === "continue") {
      this.pushStepSnapshot(steps, {
        line: node.line,
        codeText: text,
        eventType: "CONTINUE",
        callStack,
        beforeVars: beforeMap,
        changedVars: [],
        changedSummary: "Skipping rest of current loop pass (continue)",
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "continue" },
        exprFrames: [{ expr: "continue", focus: "Jump to next loop iteration", shortCircuited: false }],
        returnValue: null,
        stdout: [...stdout]
      });
      return { continued: true };
    }

    // 3. return
    if (text === "return" || text.startsWith("return ")) {
      const expr = text === "return" ? "None" : text.slice(7).trim();
      const evalRes =
        expr === "None"
          ? { value: null, frames: [{ expr: "return None", focus: "Returns None", shortCircuited: false }] }
          : this.evaluateExpressionWithSteps(
              expr,
              "return ",
              "",
              activeFrame.vars,
              functions,
              classes,
              callStack,
              steps,
              stdout,
              loopStack,
              node.line
            );
      const retVal = evalRes.value;

      this.pushStepSnapshot(steps, {
        line: node.line,
        codeText: text,
        eventType: "RETURN",
        callStack,
        beforeVars: beforeMap,
        changedVars: [],
        changedSummary: `Returns ${this.formatVal(retVal)} from ${activeFrame.frameName}`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: {
          kind: "return",
          expr,
          returnVal: this.formatVal(retVal)
        },
        exprFrames: evalRes.frames,
        returnValue: this.formatVal(retVal),
        stdout: [...stdout]
      });
      return { returned: true, value: retVal };
    }

    // 4. print(...)
    if (text.startsWith("print(") && text.endsWith(")")) {
      const inner = text.slice(6, -1).trim();
      const args = this.splitTopLevelArgs(inner);
      const vals = args.map((a) =>
        this.evalExpr(
          a,
          activeFrame.vars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          node.line
        )
      );
      const outLine = vals
        .map((v) => (typeof v === "string" ? v : this.formatVal(v)))
        .join(" ");
      stdout.push(outLine);

      this.pushStepSnapshot(steps, {
        line: node.line,
        codeText: text,
        eventType: "PRINT",
        callStack,
        beforeVars: beforeMap,
        changedVars: [],
        changedSummary: `Printed "${outLine}"`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: { kind: "print", output: outLine },
        exprFrames: [
          { expr: text, focus: "Evaluate print arguments", shortCircuited: false },
          { expr: `print(${vals.map((v) => this.formatVal(v)).join(", ")})`, focus: `Output: "${outLine}"`, shortCircuited: false }
        ],
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    // 5. Augmented assignment (+=, -=, *=, //=)
    const augMatch = text.match(/^([a-zA-Z_]\w*)\s*(\+=|-=|\*=|\/\/=)\s*(.+)$/);
    if (augMatch) {
      const varName = augMatch[1];
      const augOp = augMatch[2];
      const baseOp = augOp.slice(0, -1);
      const rhsExpr = augMatch[3].trim();

      if (!(varName in activeFrame.vars)) {
        throw {
          line: node.line,
          message: `NameError: name '${varName}' is not defined before '${augOp}'`
        };
      }

      const prevVal = activeFrame.vars[varName];
      const rhsEval = this.evaluateExpressionWithSteps(
        rhsExpr,
        `${varName} ${augOp} `,
        "",
        activeFrame.vars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        node.line
      );
      const rhsVal = rhsEval.value;

      let newVal;
      if (baseOp === "+") newVal = prevVal + rhsVal;
      else if (baseOp === "-") newVal = prevVal - rhsVal;
      else if (baseOp === "*") newVal = prevVal * rhsVal;
      else if (baseOp === "//") newVal = Math.floor(prevVal / rhsVal);

      activeFrame.prevVars[varName] = prevVal;
      activeFrame.vars[varName] = newVal;

      const changeObj = {
        name: varName,
        status: "updated",
        prevValue: prevVal
      };

      const frames = [
        ...rhsEval.frames,
        {
          expr: `${varName} = ${this.formatVal(prevVal)} ${baseOp} ${this.formatVal(rhsVal)}`,
          focus: `Substitute current ${varName} (${this.formatVal(prevVal)})`,
          shortCircuited: false
        },
        {
          expr: `${varName} = ${this.formatVal(newVal)}`,
          focus: `Rebind ${varName} → ${this.formatVal(newVal)}`,
          shortCircuited: false
        }
      ];

      this.pushStepSnapshot(steps, {
        line: node.line,
        codeText: text,
        eventType: "AUG_ASSIGN",
        callStack,
        beforeVars: beforeMap,
        changedVars: [changeObj],
        changedSummary: `${varName}: ${this.formatVal(prevVal)} → ${this.formatVal(newVal)}`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: {
          kind: "aug_assign",
          target: varName,
          augOp,
          baseOp,
          beforeVal: this.formatVal(prevVal),
          rhsExpr,
          rhsVal: this.formatVal(rhsVal),
          afterVal: this.formatVal(newVal)
        },
        exprFrames: frames,
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    // 6. Tuple / Multiple assignment (`left, right = 0, len(arr) - 1` or `a, b = b, a`)
    const eqPos = this.findSingleAssignmentEquals(text);
    if (eqPos !== -1) {
      const lhsRaw = text.slice(0, eqPos).trim();
      const rhsRaw = text.slice(eqPos + 1).trim();
      const lhsTargets = this.splitTopLevelArgs(lhsRaw);
      const rhsExprs = this.splitTopLevelArgs(rhsRaw);

      if (lhsTargets.length > 1) {
        const tupleFrames = [{ expr: text, focus: "Original tuple assignment", shortCircuited: false }];
        const evaluatedRhs = [];
        const currentRhsStrings = [...rhsExprs];

        for (let idx = 0; idx < rhsExprs.length; idx++) {
          const subRes = this.evaluateExpressionWithSteps(
            rhsExprs[idx],
            "",
            "",
            activeFrame.vars,
            functions,
            classes,
            callStack,
            steps,
            stdout,
            loopStack,
            node.line
          );
          evaluatedRhs.push(subRes.value);
          for (let fIdx = 1; fIdx < subRes.frames.length; fIdx++) {
            currentRhsStrings[idx] = subRes.frames[fIdx].expr;
            tupleFrames.push({
              expr: `${lhsTargets.join(", ")} = ${currentRhsStrings.join(", ")}`,
              focus: subRes.frames[fIdx].focus,
              shortCircuited: false
            });
          }
          currentRhsStrings[idx] = this.formatVal(subRes.value);
        }

        const valuesToAssign =
          evaluatedRhs.length === 1 && Array.isArray(evaluatedRhs[0])
            ? evaluatedRhs[0]
            : evaluatedRhs;

        const changedVarsList = [];
        const summaryParts = [];

        lhsTargets.forEach((targetStr, idx) => {
          const cleanTarget = targetStr.split(":")[0].trim();
          const newVal = valuesToAssign[idx];
          const isCreated = !(cleanTarget in activeFrame.vars);
          const prevVal = activeFrame.vars[cleanTarget];
          activeFrame.prevVars[cleanTarget] = prevVal;
          activeFrame.vars[cleanTarget] = newVal;

          changedVarsList.push({
            name: cleanTarget,
            status: isCreated ? "created" : "updated",
            prevValue: prevVal
          });
          summaryParts.push(`${cleanTarget} = ${this.formatVal(newVal)}`);
        });

        this.pushStepSnapshot(steps, {
          line: node.line,
          codeText: text,
          eventType: "ASSIGN",
          callStack,
          beforeVars: beforeMap,
          changedVars: changedVarsList,
          changedSummary: summaryParts.join(", "),
          condition: null,
          loop: this.getCurrentLoopSnapshot(loopStack),
          operationDetail: {
            kind: "assign",
            target: lhsTargets.join(", "),
            isCreated: changedVarsList.every((c) => c.status === "created"),
            beforeVal: "—",
            rhsExpr: rhsRaw,
            substituted: currentRhsStrings.join(", "),
            afterVal: summaryParts.join(", ")
          },
          exprFrames: tupleFrames,
          returnValue: null,
          stdout: [...stdout]
        });
        return null;
      }

      // Single assignment (`varName = expr` or `arr[i] = expr`)
      const cleanTarget = lhsRaw.split(":")[0].trim();
      const indexAssignMatch = cleanTarget.match(/^([a-zA-Z_]\w*)\[(.+)\]$/);
      if (indexAssignMatch) {
        const arrName = indexAssignMatch[1];
        const idxVal = this.evalExpr(
          indexAssignMatch[2],
          activeFrame.vars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          node.line
        );
        const evalRes = this.evaluateExpressionWithSteps(
          rhsRaw,
          `${arrName}[${idxVal}] = `,
          "",
          activeFrame.vars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          node.line
        );
        const newVal = evalRes.value;
        if (Array.isArray(activeFrame.vars[arrName])) {
          const prevArr = [...activeFrame.vars[arrName]];
          activeFrame.vars[arrName][idxVal] = newVal;
          const changeObj = { name: arrName, status: "updated", prevValue: prevArr };
          this.pushStepSnapshot(steps, {
            line: node.line,
            codeText: text,
            eventType: "ASSIGN",
            callStack,
            beforeVars: beforeMap,
            changedVars: [changeObj],
            changedSummary: `${arrName}[${idxVal}] = ${this.formatVal(newVal)}`,
            condition: null,
            loop: this.getCurrentLoopSnapshot(loopStack),
            operationDetail: {
              kind: "assign",
              target: `${arrName}[${idxVal}]`,
              isCreated: false,
              beforeVal: this.formatVal(prevArr[idxVal]),
              rhsExpr: rhsRaw,
              substituted: this.formatVal(newVal),
              afterVal: this.formatVal(newVal)
            },
            exprFrames: evalRes.frames,
            returnValue: null,
            stdout: [...stdout]
          });
        }
        return null;
      }

      const varName = cleanTarget;
      const rhsExpr = rhsRaw;
      const prevVal = activeFrame.vars[varName];
      const isCreated = !(varName in activeFrame.vars);
      const evalRes = this.evaluateExpressionWithSteps(
        rhsExpr,
        `${varName} = `,
        "",
        activeFrame.vars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        node.line
      );
      const newVal = evalRes.value;
      const substituted =
        evalRes.frames.length > 1
          ? evalRes.frames[Math.min(1, evalRes.frames.length - 1)].expr.replace(`${varName} = `, "")
          : this.formatVal(newVal);

      activeFrame.prevVars[varName] = prevVal;
      activeFrame.vars[varName] = newVal;

      const changeObj = {
        name: varName,
        status: isCreated ? "created" : "updated",
        prevValue: prevVal
      };

      this.pushStepSnapshot(steps, {
        line: node.line,
        codeText: text,
        eventType: "ASSIGN",
        callStack,
        beforeVars: beforeMap,
        changedVars: [changeObj],
        changedSummary: isCreated
          ? `${varName}: (created) → ${this.formatVal(newVal)}`
          : `${varName}: ${this.formatVal(prevVal)} → ${this.formatVal(newVal)}`,
        condition: null,
        loop: this.getCurrentLoopSnapshot(loopStack),
        operationDetail: {
          kind: "assign",
          target: varName,
          isCreated,
          beforeVal: isCreated ? "—" : this.formatVal(prevVal),
          rhsExpr,
          substituted,
          afterVal: this.formatVal(newVal)
        },
        exprFrames: evalRes.frames,
        returnValue: null,
        stdout: [...stdout]
      });
      return null;
    }

    return null;
  }

  findSingleAssignmentEquals(str) {
    let depth = 0;
    let inSingle = false;
    let inDouble = false;
    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (!inSingle && !inDouble) {
        if (ch === "(" || ch === "[" || ch === "{") depth++;
        else if (ch === ")" || ch === "]" || ch === "}") depth--;
        else if (
          ch === "=" &&
          depth === 0 &&
          str[i - 1] !== "=" &&
          str[i - 1] !== "!" &&
          str[i - 1] !== "<" &&
          str[i - 1] !== ">" &&
          str[i + 1] !== "="
        ) {
          return i;
        }
      }
    }
    return -1;
  }

  invokeFunctionNode(
    fnNode,
    argVals,
    rawArgs,
    callStack,
    functions,
    classes,
    steps,
    stdout,
    loopStack,
    callerLine
  ) {
    const newVars = {};
    const paramBindings = [];
    const createdChanges = [];

    fnNode.params.forEach((p, idx) => {
      const val = argVals[idx];
      // Preserve array reference identity so Global and Local scopes point to the same heap list!
      newVars[p] = val;
      paramBindings.push({
        param: p,
        argExpr: rawArgs[idx] || p,
        val: this.formatVal(val)
      });
      createdChanges.push({
        name: p,
        status: "created",
        prevValue: undefined
      });
    });

    const newFrame = {
      frameId: `local_${callStack.length}_${fnNode.funcName}`,
      frameName: `${fnNode.funcName}(${fnNode.params.map((p, i) => `${p}=${this.formatVal(argVals[i])}`).join(", ")})`,
      funcShortName: `${fnNode.funcName}()`,
      scopeType: "LOCAL",
      vars: newVars,
      prevVars: {}
    };

    callStack.push(newFrame);

    this.pushStepSnapshot(steps, {
      line: fnNode.line,
      codeText: fnNode.text,
      eventType: "FUNC_CALL",
      callStack,
      beforeVars: {},
      changedVars: createdChanges,
      changedSummary: paramBindings.map((b) => `${b.param}: (arg) → ${b.val}`).join(", "),
      condition: null,
      loop: null,
      operationDetail: {
        kind: "func_call",
        funcName: fnNode.funcName,
        callerLine,
        paramBindings
      },
      exprFrames: [
        {
          expr: `${fnNode.funcName}(${ rawArgs.join(", ") })`,
          focus: `Enter new Local Scope for ${fnNode.funcName}()`,
          shortCircuited: false
        },
        {
          expr: paramBindings.map((b) => `${b.param} = ${b.val}`).join(", "),
          focus: "Bind local parameter names to argument memory addresses",
          shortCircuited: false
        }
      ],
      returnValue: null,
      stdout: [...stdout]
    });

    const res = this.executeSuite(
      fnNode.body,
      callStack,
      functions,
      classes,
      steps,
      stdout,
      loopStack
    );
    callStack.pop();
    return res;
  }

  /* =========================================================
     TASK 2.1, 2.2 & 2.3: THONNY-STYLE STEP-BY-STEP SUB-EXPRESSION
     EVALUATOR WITH SHORT-CIRCUIT ('and' / 'or') SUPPORT
     ========================================================= */
  splitTopLevelLogical(expr, keyword) {
    const parts = [];
    let cur = "";
    let depth = 0;
    let inSingle = false;
    let inDouble = false;
    const token = ` ${keyword} `;

    for (let i = 0; i < expr.length; i++) {
      const ch = expr[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (!inSingle && !inDouble) {
        if (ch === "(" || ch === "[" || ch === "{") depth++;
        else if (ch === ")" || ch === "]" || ch === "}") depth--;
        else if (depth === 0 && expr.slice(i, i + token.length) === token) {
          parts.push(cur.trim());
          cur = "";
          i += token.length - 1;
          continue;
        }
      }
      cur += ch;
    }
    if (cur.trim()) parts.push(cur.trim());
    return parts;
  }

  evaluateConditionWithFrames(
    condExpr,
    prefix,
    suffix,
    scopeVars,
    functions,
    classes,
    callStack,
    steps,
    stdout,
    loopStack,
    line
  ) {
    const evalRes = this.evaluateExpressionWithSteps(
      condExpr,
      prefix,
      suffix,
      scopeVars,
      functions,
      classes,
      callStack,
      steps,
      stdout,
      loopStack,
      line
    );
    const boolVal = Boolean(evalRes.value);

    // If short-circuited on logical `and` / `or`, build condition summary from the evaluated clauses
    const orParts = this.splitTopLevelLogical(condExpr, "or");
    const andParts = this.splitTopLevelLogical(condExpr, "and");
    if (orParts.length > 1 || andParts.length > 1) {
      const opWord = orParts.length > 1 ? "or" : "and";
      const clauses = orParts.length > 1 ? orParts : andParts;
      const firstVal = Boolean(
        this.evalExpr(clauses[0], scopeVars, functions, classes, callStack, steps, stdout, loopStack, line)
      );
      const shortCircuited =
        (opWord === "and" && !firstVal) || (opWord === "or" && firstVal);
      return {
        condInfo: {
          expr: condExpr,
          leftExpr: clauses[0],
          leftVal: this.formatVal(firstVal),
          operator: opWord,
          rightExpr: clauses.slice(1).join(` ${opWord} `),
          rightVal: shortCircuited ? "(short-circuited)" : this.formatVal(boolVal),
          result: boolVal,
          shortCircuited
        },
        frames: evalRes.frames
      };
    }

    const ops = ["==", "!=", ">=", "<=", ">", "<"];
    for (const op of ops) {
      const idx = condExpr.indexOf(op);
      if (idx !== -1) {
        const leftExpr = condExpr.slice(0, idx).trim();
        const rightExpr = condExpr.slice(idx + op.length).trim();
        const leftVal = this.evalExpr(leftExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line);
        const rightVal = this.evalExpr(rightExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, line);
        return {
          condInfo: {
            expr: condExpr,
            leftExpr,
            leftVal: this.formatVal(leftVal),
            operator: op,
            rightExpr,
            rightVal: this.formatVal(rightVal),
            result: boolVal
          },
          frames: evalRes.frames
        };
      }
    }

    return {
      condInfo: {
        expr: condExpr,
        leftExpr: condExpr,
        leftVal: this.formatVal(boolVal),
        operator: "is",
        rightExpr: "True",
        rightVal: "True",
        result: boolVal
      },
      frames: evalRes.frames
    };
  }

  evaluateExpressionWithSteps(
    rawExpr,
    prefix,
    suffix,
    scopeVars,
    functions,
    classes,
    callStack,
    steps,
    stdout,
    loopStack,
    lineNum
  ) {
    const trimmed = rawExpr.trim();
    const frames = [
      {
        expr: `${prefix}${trimmed}${suffix}`,
        highlightSub: trimmed,
        focus: "Original expression",
        shortCircuited: false
      }
    ];

    const pushFrame = (exprStr, highlightSub, focus, shortCircuited = false) => {
      const full = `${prefix}${exprStr}${suffix}`;
      if (frames[frames.length - 1].expr !== full || shortCircuited) {
        frames.push({ expr: full, highlightSub, focus, shortCircuited });
      }
    };

    // Task 2.3: Short-circuit `or` evaluation
    const orClauses = this.splitTopLevelLogical(trimmed, "or");
    if (orClauses.length > 1) {
      const evaluatedStrs = [];
      let finalVal = false;
      for (let i = 0; i < orClauses.length; i++) {
        const clause = orClauses[i];
        const sub = this.evaluateExpressionWithSteps(
          clause,
          "",
          "",
          scopeVars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          lineNum
        );
        const cBool = Boolean(sub.value);
        evaluatedStrs.push(this.formatVal(cBool));
        const remaining = orClauses.slice(i + 1);
        const currentCombined = [...evaluatedStrs, ...remaining].join(" or ");
        pushFrame(
          currentCombined,
          this.formatVal(cBool),
          `Evaluate clause \`${clause}\` → \`${this.formatVal(cBool)}\``
        );
        if (cBool && remaining.length > 0) {
          pushFrame(
            "True",
            "True",
            `Short-circuit \`or\`: Left side is True, so \`${remaining.join(" or ")}\` is skipped!`,
            true
          );
          return { value: sub.value, frames };
        }
        finalVal = sub.value;
      }
      pushFrame(this.formatVal(Boolean(finalVal)), this.formatVal(Boolean(finalVal)), `Final result: ${this.formatVal(Boolean(finalVal))}`);
      return { value: finalVal, frames };
    }

    // Task 2.3: Short-circuit `and` evaluation
    const andClauses = this.splitTopLevelLogical(trimmed, "and");
    if (andClauses.length > 1) {
      const evaluatedStrs = [];
      let finalVal = true;
      for (let i = 0; i < andClauses.length; i++) {
        const clause = andClauses[i];
        const sub = this.evaluateExpressionWithSteps(
          clause,
          "",
          "",
          scopeVars,
          functions,
          classes,
          callStack,
          steps,
          stdout,
          loopStack,
          lineNum
        );
        const cBool = Boolean(sub.value);
        evaluatedStrs.push(this.formatVal(cBool));
        const remaining = andClauses.slice(i + 1);
        const currentCombined = [...evaluatedStrs, ...remaining].join(" and ");
        pushFrame(
          currentCombined,
          this.formatVal(cBool),
          `Evaluate clause \`${clause}\` → \`${this.formatVal(cBool)}\``
        );
        if (!cBool && remaining.length > 0) {
          pushFrame(
            "False",
            "False",
            `Short-circuit \`and\`: \`${clause}\` is False, so \`${remaining.join(" and ")}\` is skipped safely!`,
            true
          );
          return { value: false, frames };
        }
        finalVal = sub.value;
      }
      pushFrame(this.formatVal(Boolean(finalVal)), this.formatVal(Boolean(finalVal)), `Final result: ${this.formatVal(Boolean(finalVal))}`);
      return { value: finalVal, frames };
    }

    // Standard single-clause sub-expression reduction
    let working = trimmed;

    // Step 1: Substitute scalar variables inside the expression (e.g. `left`, `right`, `mid`, `target`, `i`, `c`, `ans`)
    const scalarNames = Object.keys(scopeVars)
      .filter((k) => !Array.isArray(scopeVars[k]))
      .sort((a, b) => b.length - a.length);

    for (const vName of scalarNames) {
      const regex = new RegExp(`\\b${vName}\\b`, "g");
      if (regex.test(working)) {
        const vVal = this.formatVal(scopeVars[vName]);
        working = working.replace(regex, vVal);
        pushFrame(working, vVal, `Look up variable \`${vName}\` → \`${vVal}\``);
      }
    }

    // Step 2: Evaluate list indexing expressions `arr[idx]` or `nums[idx]`
    const indexRegex = /\b([a-zA-Z_]\w*)\[([^\[\]]+)\]/;
    let safety = 0;
    while (indexRegex.test(working) && safety < 10) {
      safety++;
      const m = working.match(indexRegex);
      const fullMatch = m[0];
      const arrName = m[1];
      const innerIdxExpr = m[2];
      if (!(arrName in scopeVars)) break;

      const idxVal = this.evalExpr(
        innerIdxExpr,
        scopeVars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        lineNum
      );
      if (String(idxVal) !== innerIdxExpr.trim()) {
        working = working.replace(fullMatch, `${arrName}[${idxVal}]`);
        pushFrame(working, `${arrName}[${idxVal}]`, `Evaluate index \`${innerIdxExpr}\` → \`${idxVal}\``);
      }

      const elemVal = this.evalExpr(
        `${arrName}[${idxVal}]`,
        scopeVars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        lineNum
      );
      const elemStr = this.formatVal(elemVal);
      working = working.replace(`${arrName}[${idxVal}]`, elemStr);
      pushFrame(working, elemStr, `Look up \`${arrName}[${idxVal}]\` → \`${elemStr}\``);
    }

    // Step 3: Evaluate nested built-in calls (`len(arr)`, `min(...)`, `max(...)`, `abs(...)`, `sum(...)`, `range(...)`)
    const builtinSubRegex = /\b(len|min|max|abs|sum|range|int|float|str|bool|list|round)\(([^()]*)\)/;
    safety = 0;
    while (builtinSubRegex.test(working) && safety < 10) {
      safety++;
      const m = working.match(builtinSubRegex);
      const callStr = m[0];
      const bVal = this.evalExpr(
        callStr,
        scopeVars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        lineNum
      );
      const bStr = this.formatVal(bVal);
      working = working.replace(callStr, bStr);
      pushFrame(working, bStr, `Evaluate \`${callStr}\` → \`${bStr}\``);
    }

    // Step 4: Evaluate innermost parenthesized arithmetic `(0 + 6)`
    const parenArithRegex = /\(([-+]?\d+(?:\.\d+)?\s*(?:\+|-|\*|\/\/|\/|%)\s*[-+]?\d+(?:\.\d+)?)\)/;
    safety = 0;
    while (parenArithRegex.test(working) && safety < 10) {
      safety++;
      const m = working.match(parenArithRegex);
      const fullParen = m[0];
      const innerArith = m[1];
      const pVal = this.evalExpr(
        innerArith,
        scopeVars,
        functions,
        classes,
        callStack,
        steps,
        stdout,
        loopStack,
        lineNum
      );
      const pStr = this.formatVal(pVal);
      working = working.replace(fullParen, pStr);
      pushFrame(working, pStr, `Calculate \`${fullParen}\` → \`${pStr}\``);
    }

    // Step 5: Evaluate full expression for final value
    const finalVal = this.evalExpr(
      trimmed,
      scopeVars,
      functions,
      classes,
      callStack,
      steps,
      stdout,
      loopStack,
      lineNum
    );
    const finalStr = this.formatVal(finalVal);
    if (working !== finalStr) {
      pushFrame(finalStr, finalStr, `Evaluate \`${working}\` → \`${finalStr}\``);
    }

    return { value: finalVal, frames };
  }

  evalExpr(expr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum) {
    const trimmed = expr.trim();

    // Task 2.3: Top-level short-circuit `or` inside evalExpr
    const orParts = this.splitTopLevelLogical(trimmed, "or");
    if (orParts.length > 1) {
      let lastVal = false;
      for (const part of orParts) {
        lastVal = this.evalExpr(part, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum);
        if (Boolean(lastVal)) return lastVal;
      }
      return lastVal;
    }

    // Task 2.3: Top-level short-circuit `and` inside evalExpr
    const andParts = this.splitTopLevelLogical(trimmed, "and");
    if (andParts.length > 1) {
      let lastVal = true;
      for (const part of andParts) {
        lastVal = this.evalExpr(part, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum);
        if (!Boolean(lastVal)) return false;
      }
      return lastVal;
    }

    const rangeMatch = trimmed.match(/^range\((.+)\)$/);
    if (rangeMatch) {
      const parts = this.splitTopLevelArgs(rangeMatch[1]).map((a) =>
        Number(this.evalExpr(a, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum))
      );
      let start = 0,
        stop = 0,
        step = 1;
      if (parts.length === 1) stop = parts[0];
      else if (parts.length === 2) {
        start = parts[0];
        stop = parts[1];
      } else if (parts.length >= 3) {
        start = parts[0];
        stop = parts[1];
        step = parts[2] || 1;
      }
      const arr = [];
      if (step > 0) {
        for (let v = start; v < stop; v += step) arr.push(v);
      } else if (step < 0) {
        for (let v = start; v > stop; v += step) arr.push(v);
      }
      return arr;
    }

    const builtinMatch = trimmed.match(/^(len|min|max|abs|sum)\(([^()]*)\)$/);
    if (builtinMatch) {
      const fnName = builtinMatch[1];
      const args = this.splitTopLevelArgs(builtinMatch[2]).map((a) =>
        this.evalExpr(a, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum)
      );
      if (fnName === "len") return args[0] && typeof args[0].length === "number" ? args[0].length : 0;
      if (fnName === "abs") return Math.abs(args[0]);
      if (fnName === "sum") return Array.isArray(args[0]) ? args[0].reduce((a, b) => a + b, 0) : 0;
      if (fnName === "min") return Array.isArray(args[0]) ? Math.min(...args[0]) : Math.min(...args);
      if (fnName === "max") return Array.isArray(args[0]) ? Math.max(...args[0]) : Math.max(...args);
    }

    const indexMatch = trimmed.match(/^([a-zA-Z_]\w*)\[([^\[\]]+)\]$/);
    if (indexMatch) {
      const arrName = indexMatch[1];
      const idxVal = this.evalExpr(indexMatch[2], scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum);
      const arrObj = scopeVars[arrName];
      if (!Array.isArray(arrObj)) {
        throw { line: lineNum, message: `TypeError: '${arrName}' is not a list` };
      }
      const normalizedIdx = idxVal < 0 ? arrObj.length + idxVal : idxVal;
      if (normalizedIdx < 0 || normalizedIdx >= arrObj.length) {
        throw {
          line: lineNum,
          message: `IndexError: list index [${idxVal}] out of range for '${arrName}' (length ${arrObj.length})`
        };
      }
      return arrObj[normalizedIdx];
    }

    const methodCallMatch = trimmed.match(/^(?:[a-zA-Z_]\w*\(\)\.)?([a-zA-Z_]\w*)\((.*)\)$/);
    if (methodCallMatch && functions[methodCallMatch[1]]) {
      const fnNode = functions[methodCallMatch[1]];
      const rawArgs = methodCallMatch[2].trim() ? this.splitTopLevelArgs(methodCallMatch[2]) : [];
      const argVals = rawArgs.map((a) =>
        this.evalExpr(a, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum)
      );
      const res = this.invokeFunctionNode(
        fnNode,
        argVals,
        rawArgs,
        callStack,
        functions,
        classes,
        steps,
        stdout,
        loopStack,
        lineNum
      );
      return res && res.returned ? res.value : null;
    }

    // Pre-validate any array indexing inside compound expressions (`arr[mid] == target`, `nums[i] + nums[j]`)
    const subIndexRegex = /\b([a-zA-Z_]\w*)\[([^\[\]]+)\]/g;
    let idxMatch;
    while ((idxMatch = subIndexRegex.exec(trimmed)) !== null) {
      const aName = idxMatch[1];
      const iExpr = idxMatch[2];
      if (aName in scopeVars && Array.isArray(scopeVars[aName])) {
        const iVal = this.evalExpr(iExpr, scopeVars, functions, classes, callStack, steps, stdout, loopStack, lineNum);
        const aObj = scopeVars[aName];
        const norm = iVal < 0 ? aObj.length + iVal : iVal;
        if (norm < 0 || norm >= aObj.length) {
          throw {
            line: lineNum,
            message: `IndexError: list index [${iVal}] out of range for '${aName}' (length ${aObj.length})`
          };
        }
      }
    }

    let jsExpr = trimmed
      .replace(/\/\//g, "___INTDIV___")
      .replace(/\band\b/g, "&&")
      .replace(/\bor\b/g, "||")
      .replace(/\bnot\s+/g, "!")
      .replace(/\bTrue\b/g, "true")
      .replace(/\bFalse\b/g, "false")
      .replace(/\bNone\b/g, "null");

    if (jsExpr.includes("___INTDIV___")) {
      const parts = jsExpr.split("___INTDIV___");
      if (parts.length === 2) {
        jsExpr = `Math.floor((${parts[0]}) / (${parts[1]}))`;
      }
    }

    // Provide Python built-ins directly inside the JS evaluation context so nested calls like `len(arr) - 1` always work!
    const pyBuiltins = {
      len: (x) => (x && typeof x.length === "number" ? x.length : 0),
      abs: (x) => Math.abs(x),
      min: (...args) => (args.length === 1 && Array.isArray(args[0]) ? Math.min(...args[0]) : Math.min(...args)),
      max: (...args) => (args.length === 1 && Array.isArray(args[0]) ? Math.max(...args[0]) : Math.max(...args)),
      sum: (arr) => (Array.isArray(arr) ? arr.reduce((a, b) => a + b, 0) : 0),
      int: (x) => parseInt(x, 10) || 0,
      float: (x) => parseFloat(x) || 0.0,
      str: (x) => String(x),
      bool: (x) => Boolean(x),
      round: (x) => Math.round(x),
      list: (x) => (Array.isArray(x) ? [...x] : Array.from(x || []))
    };

    const combinedScope = { ...pyBuiltins, ...scopeVars };
    const keys = Object.keys(combinedScope);
    const vals = keys.map((k) => combinedScope[k]);
    try {
      const fn = new Function(...keys, `return (${jsExpr});`);
      const out = fn(...vals);
      if (typeof out === "number" && !Number.isFinite(out)) {
        throw new Error("ZeroDivisionError: division by zero");
      }
      return out;
    } catch (e) {
      throw { line: lineNum, message: e.message || String(e) };
    }
  }

  getCurrentLoopSnapshot(loopStack) {
    if (!loopStack.length) return null;
    return { ...loopStack[loopStack.length - 1] };
  }

  cloneVarsMap(vars) {
    const out = {};
    Object.keys(vars).forEach((k) => {
      out[k] = this.formatVal(vars[k]);
    });
    return out;
  }

  buildInspectorRowsMulti(vars, changedVarsList = [], stepIdx = 0) {
    return Object.keys(vars).map((name) => {
      const val = vars[name];
      const found = (changedVarsList || []).find((c) => c.name === name);
      let status = "unchanged";
      let prevStr = this.formatVal(val);

      if (found) {
        status = found.status;
        prevStr = found.status === "created" ? "—" : this.formatVal(found.prevValue);
      }

      const address = this.heapTracker ? this.heapTracker.getOrAllocate(val, stepIdx) : "@0x1000";

      return {
        name,
        address,
        previous: prevStr,
        current: this.formatVal(val),
        rawValue: Array.isArray(val) ? [...val] : val,
        type: this.getPythonType(val),
        status
      };
    });
  }

  splitTopLevelArgs(str) {
    if (!str.trim()) return [];
    const res = [];
    let current = "";
    let depth = 0;
    let inSingle = false;
    let inDouble = false;

    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (!inSingle && !inDouble) {
        if (ch === "(" || ch === "[") depth++;
        else if (ch === ")" || ch === "]") depth--;
        else if (ch === "," && depth === 0) {
          res.push(current.trim());
          current = "";
          continue;
        }
      }
      current += ch;
    }
    if (current.trim()) res.push(current.trim());
    return res;
  }

  getPythonType(val) {
    if (val === null || val === undefined) return "NoneType";
    if (Array.isArray(val)) return "list";
    if (typeof val === "boolean") return "bool";
    if (typeof val === "number") return Number.isInteger(val) ? "int" : "float";
    if (typeof val === "string") return "str";
    return typeof val;
  }

  formatVal(val) {
    if (val === null || val === undefined) return "None";
    if (typeof val === "boolean") return val ? "True" : "False";
    if (typeof val === "string") return `"${val}"`;
    if (Array.isArray(val)) return `[${val.map((v) => this.formatVal(v)).join(", ")}]`;
    return String(val);
  }

  buildControlFlowGraph(statements) {
    const nodes = [];
    const edges = [];

    const addNode = (id, label, type, line) => {
      nodes.push({ id, label, type, line });
      return id;
    };

    const startId = addNode("start", "START", "start", 0);

    const buildList = (stmts, prevIds) => {
      let currentPrevs = prevIds;
      for (const s of stmts) {
        if (s.kind === "CLASS") {
          const cid = addNode(`L${s.line}`, `class ${s.className}`, "class", s.line);
          currentPrevs.forEach((p) => edges.push({ from: p, to: cid }));
          currentPrevs = buildList(s.body, [cid]);
        } else if (s.kind === "DEF") {
          const fid = addNode(`L${s.line}`, `def ${s.funcName}()`, "func", s.line);
          currentPrevs.forEach((p) => edges.push({ from: p, to: fid }));
          currentPrevs = buildList(s.body, [fid]);
        } else if (s.kind === "IF_CHAIN") {
          const exitIds = [];
          let condPrevIds = currentPrevs;
          for (const br of s.branches) {
            if (br.type === "else") {
              const bodyEnd = buildList(br.body, condPrevIds);
              exitIds.push(...bodyEnd);
              condPrevIds = [];
            } else {
              const cid = addNode(`L${br.line}`, `${br.condition} ?`, "decision", br.line);
              condPrevIds.forEach((p) => edges.push({ from: p, to: cid }));
              const bodyEnd = buildList(br.body, [cid]);
              exitIds.push(...bodyEnd);
              condPrevIds = [cid];
            }
          }
          currentPrevs = [...exitIds, ...condPrevIds];
        } else if (s.kind === "FOR" || s.kind === "WHILE") {
          const label =
            s.kind === "FOR"
              ? `for ${s.iterVar} in ${s.iterExpr}`
              : `while ${s.condition}`;
          const loopId = addNode(`L${s.line}`, label, "loop", s.line);
          currentPrevs.forEach((p) => edges.push({ from: p, to: loopId }));
          const bodyEnd = buildList(s.body, [loopId]);
          bodyEnd.forEach((b) => edges.push({ from: b, to: loopId, isBackEdge: true }));
          currentPrevs = [loopId];
        } else {
          const type = s.text.startsWith("return") ? "return" : "stmt";
          const nid = addNode(
            `L${s.line}`,
            s.text.length > 26 ? s.text.slice(0, 24) + ".." : s.text,
            type,
            s.line
          );
          currentPrevs.forEach((p) => edges.push({ from: p, to: nid }));
          currentPrevs = [nid];
        }
      }
      return currentPrevs;
    };

    const lastIds = buildList(statements, [startId]);
    const endId = addNode("end", "END", "end", 9999);
    lastIds.forEach((p) => edges.push({ from: p, to: endId }));

    return { nodes, edges };
  }
}

window.PRELOADED_PROGRAMS = PRELOADED_PROGRAMS;
window.PythonExecutionEngine = PythonExecutionEngine;

// app_build/explainer.js — "Teach Me This Code" Thonny-Style Rule-Based Teacher
// Preserves full compatibility with engine.js while explaining:
// 1. Step-by-step sub-expression reductions & short-circuit logic ('and' / 'or')
// 2. Stack & Heap memory references (Name -> @Address -> Value)
// 3. Global vs. Local scope isolation

const PYTHON_SYMBOLS_LIBRARY = [
  { token: "class", label: "class", desc: "Groups related functions together under one name." },
  { token: "def", label: "def", desc: "Creates a function (a reusable set of instructions)." },
  { token: "for", label: "for", desc: "Repeats the indented lines once for each item in a list or range." },
  { token: "while", label: "while", desc: "Keeps repeating the indented lines as long as a condition is True." },
  { token: "range(", label: "range(len(nums))", desc: "Creates index numbers 0, 1, 2... up to the last position in the list." },
  { token: "len(", label: "len(arr)", desc: "Counts how many items are inside the list." },
  { token: "and", label: "and", desc: "Short-circuit AND: checks the left side first; if False, skips the right side immediately." },
  { token: "or", label: "or", desc: "Short-circuit OR: checks the left side first; if True, skips the right side immediately." },
  { token: "//", label: "//", desc: "Floor division: divides and rounds down to a whole integer index." },
  { token: "+=", label: "+=", desc: "Adds a number to the existing variable and binds the name to the new value's address." },
  { token: "-=", label: "-=", desc: "Subtracts a number from the existing variable." },
  { token: ">=", label: ">=", desc: "Asks: 'Is the left number greater than or equal to the right number?'" },
  { token: "<=", label: "<=", desc: "Asks: 'Is the left number less than or equal to the right number?'" },
  { token: "==", label: "==", desc: "Asks: 'Are these two values equal?'" },
  { token: "<", label: "<", desc: "Asks: 'Is the left number smaller than the right number?'" },
  { token: ">", label: ">", desc: "Asks: 'Is the left number larger than the right number?'" },
  { token: "=", label: "=", desc: "Evaluates the right side first and points the variable name on the left to its heap address." },
  { token: "[", label: "arr[i]", desc: "Looks up the item at index `i` inside the list object on the heap." },
  { token: "return", label: "return", desc: "Finishes the local function scope and sends back the final answer." }
];

class RuleBasedExplainer {
  enrichTraceWithExplanations(traceResult) {
    if (!traceResult || !traceResult.steps) return traceResult;
    const steps = traceResult.steps;

    const bestSubarrayInfo = this.computeBestSubarray(traceResult);

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];
      const prevStep = i > 0 ? steps[i - 1] : null;
      const nextStep = i + 1 < steps.length ? steps[i + 1] : null;

      step.teacherLesson = this.buildTeacherLesson(step, prevStep, nextStep, bestSubarrayInfo);
      step.explanations = this.buildStepExplanation(step, prevStep, nextStep);
      step.practiceQuestion = this.buildPracticeChallenge(step, nextStep);
    }

    traceResult.bestSubarrayInfo = bestSubarrayInfo;
    traceResult.executionSummary = this.buildExecutionSummary(traceResult);
    return traceResult;
  }

  computeBestSubarray(traceResult) {
    const steps = traceResult.steps || [];
    if (!steps.length) return null;

    let numsArr = null;
    for (const s of steps) {
      const numsRow = (s.variables || []).find((v) => v.name === "nums" && Array.isArray(v.rawValue));
      if (numsRow) {
        numsArr = numsRow.rawValue;
        break;
      }
    }
    if (!numsArr || !numsArr.length) return null;

    let bestSum = numsArr[0];
    let bestStart = 0;
    let bestEnd = 0;
    let currentSum = 0;
    let currentStart = 0;

    for (let i = 0; i < numsArr.length; i++) {
      if (currentSum === 0) currentStart = i;
      currentSum += numsArr[i];
      if (currentSum >= bestSum) {
        bestSum = currentSum;
        bestStart = currentStart;
        bestEnd = i;
      }
      if (currentSum < 0) {
        currentSum = 0;
      }
    }

    return {
      subarray: numsArr.slice(bestStart, bestEnd + 1),
      startIndex: bestStart,
      endIndex: bestEnd,
      maxSum: bestSum
    };
  }

  buildTeacherLesson(step, prevStep, nextStep, bestSubarrayInfo) {
    const n = step.stepIndex;
    const op = step.operationDetail || {};
    const cond = step.condition;
    const nextSentence = this.buildFriendlyWhatNext(step, nextStep);
    const relevantVarsNow = this.formatRelevantVariablesNow(step);
    const exprFrames = step.exprFrames || [];
    const scFrame = exprFrames.find((f) => f.shortCircuited);

    // 1. Class definition
    if (step.eventType === "CLASS_DEF") {
      return {
        title: `Step ${n}: Create the Solution class`,
        calculationCard: null,
        whatItMeans:
          `Python reads \`class Solution:\` in **Global Scope**, which is a container that holds our method. Creating the class does not calculate the answer yet—it just prepares the container.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 2. Method / Function definition
    if (step.eventType === "METHOD_DEF" || step.eventType === "FUNC_DEF") {
      return {
        title: `Step ${n}: Define the ${op.funcName} function`,
        calculationCard: null,
        whatItMeans:
          `Python registers the function \`${op.funcName}(${(op.params || ["nums"]).join(", ")})\` in **Global Scope**. Python only creates a **Local Scope** for this function when we call it.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 3. Function Call
    if (step.eventType === "FUNC_CALL") {
      const bindings = op.paramBindings || [];
      const bText = bindings.map((b) => `\`${b.param}\` → \`${b.val}\``).join(", ");
      return {
        title: `Step ${n}: Call ${op.funcName}() & create Local Scope`,
        calculationCard: null,
        whatItMeans: bindings.length
          ? `We call \`${op.funcName}()\` and open a new **Local Scope** stack frame! Parameter names (${bText}) now point directly to the argument addresses on the **Heap**.`
          : `We call \`${op.funcName}()\` and enter a new **Local Scope** to execute its lines.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 4. Standard variable assignment
    if (step.eventType === "ASSIGN") {
      const changedAddr = (step.variables || []).find((v) => v.name === op.target)?.address;
      const addrNote = changedAddr ? ` (pointing to heap address \`${changedAddr}\`)` : "";

      if (op.target === "c" && op.isCreated) {
        return {
          title: `Step ${n}: Create the variable c`,
          calculationCard: null,
          whatItMeans:
            `We create a local variable named \`c\`${addrNote} and store the number \`${op.afterVal}\` inside it. \`c\` will keep track of our running sum as we add numbers from the list.`,
          variableValuesNow: relevantVarsNow,
          whatHappensNext: nextSentence,
          finalBanner: null
        };
      }
      if (op.target === "ans" && op.isCreated) {
        return {
          title: `Step ${n}: Create the variable ans`,
          calculationCard: {
            currentNumber: null,
            before: `Look up nums[0]`,
            calculation: `nums[0] → ${op.afterVal}`,
            after: `ans = ${op.afterVal}`
          },
          whatItMeans:
            `We evaluate \`nums[0]\` (\`${op.afterVal}\`) and bind \`ans\`${addrNote} to \`${op.afterVal}\`. \`ans\` remembers the largest sum we have seen so far.`,
          variableValuesNow: relevantVarsNow,
          whatHappensNext: nextSentence,
          finalBanner: null
        };
      }
      if (op.target === "ans" && !op.isCreated) {
        return {
          title: `Step ${n}: Save the new largest sum in ans`,
          calculationCard: {
            currentNumber: null,
            before: `ans = ${op.beforeVal}`,
            calculation: `ans = c (${op.afterVal})`,
            after: `ans = ${op.afterVal}`
          },
          whatItMeans:
            `Because our current sum \`c\` (\`${op.afterVal}\`) is at least as big as \`ans\` (\`${op.beforeVal}\`), we rebind \`ans\`${addrNote} to \`${op.afterVal}\`!`,
          variableValuesNow: relevantVarsNow,
          whatHappensNext: nextSentence,
          finalBanner: null
        };
      }
      if (op.target === "c" && op.afterVal === "0" && !op.isCreated) {
        return {
          title: `Step ${n}: Reset c to zero`,
          calculationCard: {
            currentNumber: null,
            before: `c = ${op.beforeVal}`,
            calculation: `Reset negative sum to 0`,
            after: `c = 0`
          },
          whatItMeans:
            `Because \`c\` was negative (\`${op.beforeVal}\`), keeping it would only make future sums smaller. So we rebind \`c\`${addrNote} back to \`0\` (and the old negative value becomes unreferenced on the heap).`,
          variableValuesNow: relevantVarsNow,
          whatHappensNext: nextSentence,
          finalBanner: null
        };
      }

      return {
        title: `Step ${n}: ${op.isCreated ? "Create" : "Update"} ${op.target}`,
        calculationCard: {
          currentNumber: null,
          before: op.isCreated ? `Expression: ${op.rhsExpr}` : `${op.target} = ${op.beforeVal}`,
          calculation: `${op.rhsExpr} → ${op.substituted}`,
          after: `${op.afterVal.includes("=") ? op.afterVal : `${op.target} = ${op.afterVal}`}`
        },
        whatItMeans: op.isCreated
          ? `Python evaluates \`${op.rhsExpr}\` step-by-step into \`${op.substituted}\` and binds \`${op.target}\`${addrNote} in **${step.functionName}**.`
          : `Python evaluates \`${op.rhsExpr}\` (\`${op.substituted}\`) and updates \`${op.target}\`${addrNote} from \`${op.beforeVal}\` to \`${op.afterVal}\`.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 5. Addition / Augmented Assignment (`c += nums[i]`)
    if (step.eventType === "AUG_ASSIGN") {
      const afterNum = Number(op.afterVal);
      const ansRow = (step.variables || []).find((v) => v.name === "ans");
      const ansNum = ansRow ? Number(ansRow.current) : null;

      let teacherNote = `We evaluated \`${op.rhsExpr}\` → \`${op.rhsVal}\`, added it to \`${op.target}\` (\`${op.beforeVal}\`), and rebound \`${op.target}\` to \`${op.afterVal}\`.`;
      if (op.target === "c") {
        if (afterNum < 0 && ansNum !== null && afterNum >= ansNum) {
          teacherNote = `We added \`${op.rhsVal}\` to \`c\`, giving \`${op.afterVal}\`. That matches or beats \`ans\` (\`${ansNum}\`), and because \`c\` is negative, the second condition will reset \`c\` to zero.`;
        } else if (afterNum < 0) {
          teacherNote = `We added \`${op.rhsVal}\` to \`c\`, giving \`${op.afterVal}\`. Because the result is negative, the \`if c < 0:\` check will reset \`c\` to zero.`;
        } else if (ansNum !== null && afterNum >= ansNum) {
          teacherNote = `We added \`${op.rhsVal}\` to \`c\`, bringing \`c\` up to \`${op.afterVal}\`! Because \`${op.afterVal}\` is at least as large as our best sum \`ans\` (\`${ansNum}\`), the next condition will update \`ans\` to \`${op.afterVal}\`!`;
        } else {
          teacherNote = `We added \`${op.rhsVal}\` to \`c\`, changing \`c\` from \`${op.beforeVal}\` to \`${op.afterVal}\`. Since \`c\` is still positive, we keep building this continuous section.`;
        }
      }

      return {
        title: `Step ${n}: Add the current number`,
        calculationCard: {
          currentNumber: op.rhsVal,
          before: `${op.target} = ${op.beforeVal}`,
          calculation: `${op.target} = ${op.beforeVal} ${op.baseOp} (${op.rhsVal})`,
          after: `${op.target} = ${op.afterVal}`
        },
        whatItMeans: teacherNote,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 6. For Loop iteration (`for i in range(len(nums)):`)
    if (step.eventType === "LOOP_ITER" && op.kind === "for_iter") {
      const elemInfo = op.indexedElementInfo;
      return {
        title: `Step ${n}: Loop pass ${op.iteration} of ${op.total} (${op.iterVar} = ${op.iterVal})`,
        calculationCard: elemInfo
          ? {
              currentNumber: elemInfo.elementVal,
              before: `Position ${elemInfo.indexVar} = ${elemInfo.indexVal}`,
              calculation: `Look up ${elemInfo.arrayName}[${elemInfo.indexVal}]`,
              after: `Current number is ${elemInfo.elementVal}`
            }
          : null,
        whatItMeans: elemInfo
          ? `The loop moves to position \`${op.iterVar} = ${op.iterVal}\` (item ${op.iteration} of ${op.total}). The number at \`${elemInfo.arrayName}[${op.iterVal}]\` on the heap is **\`${elemInfo.elementVal}\`**.`
          : `The loop starts pass ${op.iteration} of ${op.total} and binds \`${op.iterVar} = ${op.iterVal}\`.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 6b. While Loop iteration (`while left <= right:`)
    if (step.eventType === "LOOP_ITER" && op.kind === "while_check" && cond) {
      return {
        title: `Step ${n}: Check while loop condition (${cond.expr})`,
        calculationCard: {
          currentNumber: null,
          before: `${cond.leftExpr} = ${cond.leftVal}, ${cond.rightExpr} = ${cond.rightVal}`,
          calculation: `${cond.leftVal} ${cond.operator} ${cond.rightVal}`,
          after: `True (Enter loop pass #${op.iteration})`
        },
        whatItMeans: scFrame
          ? `We test \`${cond.expr}\`: ${scFrame.focus}. Result is **True**, so Python enters loop pass #${op.iteration}.`
          : `We check if \`${cond.expr}\` (\`${cond.leftVal} ${cond.operator} ${cond.rightVal}\`). It evaluates to **True**, so Python enters loop pass #${op.iteration}!`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 7. Loop End
    if (step.eventType === "LOOP_END") {
      return {
        title: `Step ${n}: Loop finished`,
        calculationCard: cond
          ? {
              currentNumber: null,
              before: `${cond.leftExpr} (${cond.leftVal})`,
              calculation: `${cond.leftVal} ${cond.operator} ${cond.rightVal}`,
              after: `False (Exit loop)`
            }
          : null,
        whatItMeans:
          op.kind === "while_check" && cond
            ? `We check \`${cond.expr}\` (\`${cond.leftVal} ${cond.operator} ${cond.rightVal}\`), which is now **False**! Python exits the \`while\` loop.`
            : `We have checked every single item in the sequence! The loop is now finished, so Python leaves the loop.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 8. Condition Check (`if c >= ans:`, `if arr[mid] == target:`, or compound short-circuit conditions)
    if (step.eventType === "CONDITION" && cond) {
      let stepTitle = `Step ${n}: Check the condition (${cond.expr})`;
      let explanation = "";

      if (scFrame) {
        stepTitle = `Step ${n}: Short-Circuit Condition Check (${cond.expr})`;
        explanation = `Python evaluates \`${cond.expr}\` left-to-right using **short-circuit logic**: ${scFrame.focus}. Because the outcome is already determined (**${cond.result ? "True" : "False"}**), Python never evaluates the remaining clause!`;
      } else if (cond.expr === "c >= ans") {
        stepTitle = `Step ${n}: Check if c (${cond.leftVal}) beats or ties ans (${cond.rightVal})`;
        explanation = cond.result
          ? `We ask: Is \`c >= ans\` (\`Is ${cond.leftVal} >= ${cond.rightVal}\`)? **Yes, True!** Our current sum \`c\` is at least as big as \`ans\`, so Python goes inside the \`if\` block to update \`ans\`.`
          : `We ask: Is \`c >= ans\` (\`Is ${cond.leftVal} >= ${cond.rightVal}\`)? **No, False.** \`${cond.leftVal}\` is smaller than \`${cond.rightVal}\`, so \`ans\` stays \`${cond.rightVal}\` and Python skips this \`if\` block.`;
      } else if (cond.expr === "c < 0") {
        stepTitle = `Step ${n}: Check if c (${cond.leftVal}) is negative`;
        explanation = cond.result
          ? `We ask: Is \`c < 0\` (\`Is ${cond.leftVal} < 0\`)? **Yes, True!** Because \`c\` is negative (\`${cond.leftVal}\`), Python goes inside this \`if\` block to reset \`c\` back to \`0\`.`
          : `We ask: Is \`c < 0\` (\`Is ${cond.leftVal} < 0\`)? **No, False.** Since \`${cond.leftVal}\` is not negative, we do not reset \`c\`—we keep this sum for the next number!`;
      } else {
        explanation = `Python reduces the sub-expressions inside \`${cond.expr}\` to \`${cond.leftVal} ${cond.operator} ${cond.rightVal}\`, which evaluates to **${cond.result ? "True" : "False"}**.`;
      }

      return {
        title: stepTitle,
        calculationCard: {
          currentNumber: null,
          before: `${cond.leftExpr} is ${cond.leftVal}, ${cond.rightExpr} is ${cond.rightVal}`,
          calculation: `${cond.leftVal} ${cond.operator} ${cond.rightVal}`,
          after: cond.result ? "True (Run the indented line)" : "False (Skip the indented line)"
        },
        whatItMeans: explanation,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 8b. Else branch
    if (step.eventType === "ELSE_BRANCH") {
      return {
        title: `Step ${n}: Enter the else branch`,
        calculationCard: null,
        whatItMeans:
          `Because all preceding \`if\` / \`elif\` conditions were **False**, Python automatically enters the \`else:\` block.`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextSentence,
        finalBanner: null
      };
    }

    // 9. Return Statement
    if (step.eventType === "RETURN") {
      const subText =
        bestSubarrayInfo && bestSubarrayInfo.subarray && step.codeText.includes("ans")
          ? `The continuous section \`[${bestSubarrayInfo.subarray.join(", ")}]\` has the largest sum: **${op.returnVal}**.`
          : `The function finishes its **Local Scope** frame and returns the final answer: **${op.returnVal}**.`;

      return {
        title: `Step ${n}: Return the answer (${op.returnVal})`,
        calculationCard: null,
        whatItMeans:
          `\`${step.codeText}\` evaluates to **\`${op.returnVal}\`**, sends **\`${op.returnVal}\`** back to the caller, and destroys the local scope frame for \`${step.functionName}\`!`,
        variableValuesNow: relevantVarsNow,
        whatHappensNext: nextStep
          ? nextSentence
          : `The program is complete! You can click Restart or try a different input above.`,
        finalBanner: !nextStep
          ? {
              answer: op.returnVal,
              summary: subText
            }
          : null
      };
    }

    // Fallback for print / break / continue / exceptions
    return {
      title: `Step ${n}: Execute line ${step.line}`,
      calculationCard: null,
      whatItMeans:
        step.eventType === "PRINT"
          ? `Python displays \`"${op.output}"\` as output.`
          : step.eventType === "EXCEPTION"
          ? `Python stopped with an error: \`${op.message}\`.`
          : `Python runs \`${step.codeText}\`.`,
      variableValuesNow: relevantVarsNow,
      whatHappensNext: nextSentence,
      finalBanner: null
    };
  }

  formatRelevantVariablesNow(step) {
    const vars = step.variables || [];
    const compact = vars.filter((v) => !Array.isArray(v.rawValue));
    if (compact.length === 0) {
      if (vars.length > 0) {
        return vars.map((v) => `${v.name} (${v.address || "@0x2000"}) = ${v.current}`).join(", ");
      }
      return "No variables created yet";
    }
    const parts = compact.map((v) => `${v.name} = ${v.current}`);
    if (step.loop && step.loop.indexedElementInfo) {
      const el = step.loop.indexedElementInfo;
      parts.push(`${el.arrayName}[${el.indexVal}] = ${el.elementVal}`);
    }
    return parts.join("   •   ");
  }

  buildFriendlyWhatNext(step, nextStep) {
    if (!nextStep) {
      return "We have reached the end of the program!";
    }
    const nextCode = nextStep.codeText || "";
    if (nextStep.eventType === "METHOD_DEF" || nextStep.eventType === "FUNC_DEF") {
      return `Python moves to Line ${nextStep.line} to register the function \`${nextStep.operationDetail.funcName}\`.`;
    }
    if (nextStep.eventType === "FUNC_CALL") {
      return `Python calls \`${nextStep.operationDetail.funcName}()\`, creates a new Local Scope frame, and enters the function body.`;
    }
    if (nextStep.eventType === "LOOP_ITER") {
      const nextOp = nextStep.operationDetail || {};
      if (nextOp.kind === "while_check") {
        return `Python moves to Line ${nextStep.line} to test the \`while\` loop condition (\`${nextStep.condition?.expr || nextCode}\`).`;
      }
      return nextOp.iteration === 1
        ? `Python moves to Line ${nextStep.line} to start the loop with the first item (\`${nextOp.iterVar} = ${nextOp.iterVal}\`).`
        : `Python loops back up to Line ${nextStep.line} to advance to the next item (\`${nextOp.iterVar} = ${nextOp.iterVal}\`).`;
    }
    if (nextStep.eventType === "LOOP_END") {
      return `Python checks the loop header on Line ${nextStep.line}, sees the loop condition is finished, and exits the loop.`;
    }
    if (nextStep.eventType === "RETURN") {
      return `Python moves to Line ${nextStep.line} (\`${nextCode}\`) to return the result and exit the local function scope.`;
    }
    return `Python moves to Line ${nextStep.line} and evaluates \`${nextCode}\`.`;
  }

  buildStepExplanation(step, prevStep, nextStep) {
    const lesson = step.teacherLesson || this.buildTeacherLesson(step, prevStep, nextStep, null);
    const code = step.codeText || "";
    const cond = step.condition;
    const beforeVars = step.beforeVars || {};

    const beforeKeys = Object.keys(beforeVars);
    const variablesBefore =
      beforeKeys.length === 0
        ? "No local variables existed before this step."
        : beforeKeys.map((k) => `\`${k} = ${beforeVars[k]}\``).join(", ");

    let whyCondition = "Not a condition line.";
    if (cond) {
      whyCondition = cond.shortCircuited
        ? `Short-circuited on \`${cond.leftExpr} = ${cond.leftVal}\` (${cond.operator}) → **${cond.result ? "True" : "False"}**.`
        : `\`${cond.leftVal} ${cond.operator} ${cond.rightVal}\` evaluated to **${cond.result ? "True" : "False"}**.`;
    }

    return {
      whatBeginner: lesson.whatItMeans,
      whatTechnical: `Event \`${step.eventType}\` at Line ${step.line} in \`${step.functionName}\` (${step.scopeType || "LOCAL"}): ${step.changedSummary}.`,
      symbolsMeaning: this.explainSymbolsInLine(code),
      whyExecuting: prevStep
        ? `Moved from Line ${prevStep.line} to Line ${step.line}.`
        : `First statement in the program.`,
      variablesBefore,
      whatChangesAfter: step.changedSummary || "No variable changes.",
      whyCondition,
      whatNext: lesson.whatHappensNext
    };
  }

  explainSymbolsInLine(codeText) {
    const matches = [];
    for (const item of PYTHON_SYMBOLS_LIBRARY) {
      if (codeText.includes(item.token)) {
        matches.push(`• \`${item.label}\`: ${item.desc}`);
      }
    }
    return matches.length ? matches.slice(0, 3).join("<br>") : "• Standard Python statement.";
  }

  buildPracticeChallenge(step, nextStep) {
    if (!nextStep) return null;
    if (nextStep.eventType === "CONDITION" && nextStep.condition) {
      const c = nextStep.condition;
      return {
        prompt: `Quick Check: On the next line (\`${nextStep.codeText}\`), will \`${c.expr}\` be True or False?`,
        options: [
          { label: `True (${c.leftVal} ${c.operator} ${c.rightVal})`, correct: c.result === true },
          { label: `False (${c.leftVal} ${c.operator} ${c.rightVal})`, correct: c.result === false }
        ],
        explanation: `With \`${c.leftExpr} = ${c.leftVal}\` and \`${c.rightExpr} = ${c.rightVal}\`, the answer is **${c.result ? "True" : "False"}**.`
      };
    }
    return null;
  }

  buildExecutionSummary(traceResult) {
    if (!traceResult.ok || !traceResult.steps.length) {
      return `Stopped: ${traceResult.errorMessage || "Check syntax or input."}`;
    }
    if (traceResult.finalResult !== null) {
      return `Final Answer: **${traceResult.finalResult}** (${traceResult.steps.length} steps)`;
    }
    return `Completed in ${traceResult.steps.length} steps.`;
  }
}

window.RuleBasedExplainer = RuleBasedExplainer;

:root {
  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --bg-subtle: #f1f5f9;
  --bg-code: #f8fafc;

  --border-light: #e2e8f0;
  --border-medium: #cbd5e1;

  --text-main: #0f172a;
  --text-secondary: #475569;
  --text-muted: #94a3b8;

  --primary-blue: #2563eb;
  --primary-blue-hover: #1d4ed8;
  --primary-blue-soft: #eff6ff;
  --primary-blue-border: #93c5fd;

  --local-purple: #7c3aed;
  --local-purple-soft: #f5f3ff;
  --local-purple-border: #c4b5fd;

  --global-teal: #0d9488;
  --global-teal-soft: #f0fdfa;
  --global-teal-border: #99f6e4;

  --addr-amber-bg: #fffbeb;
  --addr-amber-border: #fcd34d;
  --addr-amber-text: #b45309;

  --changed-green-bg: #ecfdf5;
  --changed-green-border: #6ee7b7;
  --changed-green-text: #065f46;

  --current-line-bg: #dbeafe;
  --current-line-border: #2563eb;

  /* Light-theme syntax colors */
  --syn-kw: #7c3aed;
  --syn-bi: #0284c7;
  --syn-str: #059669;
  --syn-num: #d97706;
  --syn-com: #94a3b8;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', Consolas, monospace;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-page);
  color: var(--text-main);
  font-family: var(--font-sans);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-size: 15px;
  line-height: 1.6;
}

/* =========================================================
   TOP NAVIGATION BAR
   ========================================================= */
.top-bar {
  height: 68px;
  background-color: var(--bg-card);
  border-bottom: 1px solid var(--border-light);
  padding: 0 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  position: sticky;
  top: 0;
  z-index: 20;
}

.brand-area {
  display: flex;
  align-items: center;
  gap: 12px;
}

.teacher-badge {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
}

.step-progress-label {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--primary-blue);
  background: var(--primary-blue-soft);
  border: 1px solid var(--primary-blue-border);
  padding: 4px 12px;
  border-radius: 99px;
}

/* Scope Pills (Global vs. Local) */
.scope-pill {
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 99px;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.scope-global {
  background: var(--global-teal-soft);
  color: var(--global-teal);
  border: 1px solid var(--global-teal-border);
}

.scope-local {
  background: var(--local-purple-soft);
  color: var(--local-purple);
  border: 1px solid var(--local-purple-border);
}

.nav-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-nav {
  font-family: var(--font-sans);
  font-size: 14px;
  font-weight: 600;
  padding: 8px 15px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-medium);
  background: var(--bg-card);
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-nav:hover:not(:disabled) {
  background: var(--bg-subtle);
  border-color: #94a3b8;
}

.btn-nav:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn-substep {
  background: #fffbeb;
  border-color: #fcd34d;
  color: #92400e;
}

.btn-substep:hover:not(:disabled) {
  background: #fef3c7;
  border-color: #f59e0b;
}

.btn-next-prominent {
  background: var(--primary-blue);
  border-color: var(--primary-blue);
  color: #ffffff;
  padding: 9px 22px;
  font-size: 14.5px;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.25);
}

.btn-next-prominent:hover:not(:disabled) {
  background: var(--primary-blue-hover);
  border-color: var(--primary-blue-hover);
}

.secondary-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-subtle {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 500;
  padding: 7px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-light);
  background: var(--bg-subtle);
  color: var(--text-secondary);
  cursor: pointer;
}

.btn-subtle:hover,
.btn-subtle.active {
  background: #e2e8f0;
  color: var(--text-main);
}

.btn-small-primary {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 600;
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  border: none;
  background: var(--primary-blue);
  color: #ffffff;
  cursor: pointer;
}

/* =========================================================
   OPTIONAL CUSTOM INPUT / CODE DRAWER
   ========================================================= */
.custom-drawer {
  background: var(--bg-subtle);
  border-bottom: 1px solid var(--border-light);
  padding: 10px 28px;
}

.custom-drawer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.drawer-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.drawer-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
}

.drawer-select,
.drawer-input {
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-medium);
  background: var(--bg-card);
  color: var(--text-main);
  font-size: 13px;
  font-family: var(--font-mono);
}

.drawer-input {
  width: 280px;
}

.chip-input {
  font-size: 12px;
  font-family: var(--font-mono);
  padding: 5px 10px;
  border-radius: 6px;
  border: 1px solid var(--border-medium);
  background: var(--bg-card);
  color: var(--text-secondary);
  cursor: pointer;
}

.chip-input:hover {
  border-color: var(--primary-blue);
  color: var(--primary-blue);
}

.validation-banner {
  margin-top: 8px;
  padding: 8px 12px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
  border-radius: var(--radius-sm);
  font-size: 13px;
}

/* =========================================================
   SIMPLE OVERVIEW BANNER
   ========================================================= */
.overview-strip {
  background: var(--primary-blue-soft);
  border-bottom: 1px solid #dbeafe;
  padding: 10px 28px;
  font-size: 15px;
  color: #1e3a8a;
  display: flex;
  align-items: center;
  gap: 8px;
}

.overview-label {
  font-weight: 700;
  text-transform: uppercase;
  font-size: 12px;
  background: #2563eb;
  color: #ffffff;
  padding: 2px 8px;
  border-radius: 4px;
}

/* =========================================================
   MAIN 3-AREA WORKSPACE
   ========================================================= */
.three-area-workspace {
  flex: 1;
  display: grid;
  grid-template-columns: 0.95fr 1.35fr 1.05fr;
  gap: 20px;
  padding: 22px 28px;
  max-width: 1620px;
  width: 100%;
  margin: 0 auto;
  align-items: start;
}

.area-card {
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.03);
}

.area-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-light);
}

.area-heading {
  font-size: 13.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
}

.code-scope-tag,
.ref-legend-pill {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  padding: 2px 8px;
  border-radius: 6px;
}

/* =========================================================
   AREA 1: YOUR CODE (LEFT)
   ========================================================= */
.code-view {
  font-family: var(--font-mono);
  font-size: 13.5px;
  line-height: 1.85;
  background: var(--bg-code);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 12px 0;
  overflow-x: auto;
}

.code-row {
  display: flex;
  align-items: center;
  padding: 2px 14px 2px 0;
  border-left: 4px solid transparent;
  cursor: pointer;
  transition: opacity 0.15s ease, background-color 0.15s ease;
}

.code-row.is-dimmed {
  opacity: 0.58;
}

.code-row.is-dimmed:hover {
  opacity: 0.9;
  background: #f1f5f9;
}

.code-row.is-current-line {
  opacity: 1;
  background-color: var(--current-line-bg);
  border-left-color: var(--current-line-border);
  font-weight: 600;
}

.code-gutter {
  width: 44px;
  text-align: right;
  padding-right: 12px;
  color: var(--text-muted);
  font-size: 12px;
  user-select: none;
  flex-shrink: 0;
}

.is-current-line .code-gutter {
  color: var(--primary-blue);
  font-weight: 700;
}

.code-syntax {
  white-space: pre;
  color: var(--text-main);
}

.syn-kw { color: var(--syn-kw); font-weight: 600; }
.syn-bi { color: var(--syn-bi); }
.syn-str { color: var(--syn-str); }
.syn-num { color: var(--syn-num); }
.syn-com { color: var(--syn-com); font-style: italic; }

.live-editor-wrap {
  margin-top: 8px;
}

.code-textarea {
  width: 100%;
  min-height: 340px;
  font-family: var(--font-mono);
  font-size: 13.5px;
  line-height: 1.7;
  padding: 14px;
  border: 1px solid var(--primary-blue);
  border-radius: var(--radius-md);
  background: var(--bg-card);
  color: var(--text-main);
  outline: none;
}

/* =========================================================
   AREA 2: TEACHING AREA & THONNY EXPRESSION STEPPER (CENTER)
   ========================================================= */
.area-teaching {
  border: 2px solid var(--primary-blue-border);
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.06);
}

.teaching-card-inner {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.teach-header-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.teach-step-title {
  font-size: 21px;
  font-weight: 700;
  color: var(--text-main);
  line-height: 1.3;
}

.teach-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.teach-label {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-secondary);
}

.teach-code-box {
