  color: #78350f;
  cursor: pointer;
  transition: all 0.12s ease;
}

.thonny-chip.is-active-substep {
  background: #f59e0b;
  border-color: #d97706;
  color: #ffffff;
  font-weight: 700;
}

.thonny-chip.is-sc-chip {
  border-color: #ef4444;
  background: #fee2e2;
  color: #991b1b;
  font-weight: 700;
}

.thonny-arrow {
  color: #d97706;
  font-size: 12px;
  font-weight: 700;
}

/* Step Calculation Breakdown Box */
.teach-calc-box {
  background: #f8fafc;
  border: 1px solid var(--border-medium);
  border-radius: var(--radius-md);
  padding: 13px 16px;
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.calc-row {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 14.5px;
}

.calc-label {
  width: 125px;
  font-weight: 600;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.calc-val {
  font-family: var(--font-mono);
  font-size: 14px;
