}

.calc-highlight {
  background: #eff6ff;
  border-color: #bfdbfe;
  color: #1d4ed8;
  font-weight: 600;
}

.calc-after {
  background: var(--changed-green-bg);
  border-color: var(--changed-green-border);
  color: var(--changed-green-text);
  font-weight: 700;
}

.teach-meaning-text {
  font-size: 16px;
  line-height: 1.65;
  color: var(--text-main);
}

.teach-meaning-text code,
.teach-next-text code,
.final-answer-detail code,
.thonny-focus-note code {
  font-family: var(--font-mono);
  font-size: 14px;
  background: var(--bg-subtle);
  padding: 2px 6px;
  border-radius: 5px;
  color: #1e40af;
  font-weight: 600;
}

.teach-vars-now {
  font-family: var(--font-mono);
  font-size: 14.5px;
  font-weight: 600;
  background: var(--changed-green-bg);
  border: 1px solid var(--changed-green-border);
  color: var(--changed-green-text);
  padding: 10px 14px;
  border-radius: var(--radius-sm);
}

.teach-next-box {
  background: var(--bg-subtle);
  padding: 11px 15px;
  border-radius: var(--radius-md);
}

.teach-next-text {
  font-size: 14.5px;
  color: var(--text-secondary);
}

/* Final Answer Banner */
.final-answer-banner {
  background: #ecfdf5;
  border: 2px solid #10b981;
  border-radius: var(--radius-md);
  padding: 16px 18px;
