  flex-direction: column;
  gap: 6px;
}

.final-answer-heading {
  font-size: 21px;
  font-weight: 800;
  color: #065f46;
}

.final-answer-detail {
  font-size: 15px;
  color: #047857;
}

/* =========================================================
   AREA 3: SCOPE ISOLATION & STACK/HEAP MEMORY MODEL (RIGHT)
   ========================================================= */
.memory-section-block {
  margin-bottom: 16px;
}

.memory-section-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

.scope-frames-container {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.scope-frame-card {
  border: 1.5px solid var(--border-medium);
  border-radius: var(--radius-md);
  background: var(--bg-card);
  overflow: hidden;
  transition: all 0.15s ease;
}

.scope-frame-card.is-local-scope {
  border-color: var(--local-purple-border);
}

.scope-frame-card.is-global-scope {
  border-color: var(--global-teal-border);
}

.scope-frame-card.is-inactive-scope {
  opacity: 0.78;
}

.scope-frame-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 12px;
  font-size: 12px;
  font-weight: 700;
}

.is-local-scope .scope-frame-header {
  background: var(--local-purple-soft);
  color: var(--local-purple);
  border-bottom: 1px solid var(--local-purple-border);
}

.is-global-scope .scope-frame-header {
  background: var(--global-teal-soft);
  color: var(--global-teal);
  border-bottom: 1px solid var(--global-teal-border);
}

.scope-active-tag {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  padding: 1px 6px;
  border-radius: 99px;
  background: rgba(15, 23, 42, 0.08);
}

.scope-vars-list {
  display: flex;
  flex-direction: column;
}

.scope-var-row {
  display: grid;
  grid-template-columns: 1fr auto 1.1fr;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-light);
  font-family: var(--font-mono);
  font-size: 13px;
}

.scope-var-row:last-child {
  border-bottom: none;
}

.scope-var-row.var-row-changed {
  background: var(--changed-green-bg);
}

.var-name-cell {
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 6px;
}

.ref-arrow-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 700;
  color: var(--addr-amber-text);
  background: var(--addr-amber-bg);
  border: 1px solid var(--addr-amber-border);
  padding: 2px 7px;
  border-radius: 6px;
}

.var-val-preview {
  text-align: right;
  font-weight: 600;
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.changed-pill {
  font-family: var(--font-sans);
  font-size: 10px;
  font-weight: 700;
  background: #10b981;
  color: #ffffff;
  padding: 1px 6px;
  border-radius: 99px;
}

/* Heap Memory Objects & Visual Garbage Collection */
.heap-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.btn-gc-toggle {
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 6px;
  border: 1px solid var(--border-medium);
  background: var(--bg-subtle);
  color: var(--text-secondary);
  cursor: pointer;
}

.btn-gc-toggle.active {
  background: #fee2e2;
  border-color: #fca5a5;
  color: #991b1b;
}

.heap-objects-container {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.heap-obj-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 11px;
  border: 1px solid var(--border-medium);
  border-radius: var(--radius-sm);
  background: var(--bg-subtle);
